-- ═══════════════════════════════════════════════════════════════════════
-- BỎ HẲN CHỮ VIẾT TẮT KHỎI NỘI DUNG (sinh tự động — chớ sửa tay)
--
-- Đợt trước mở rộng lần đầu và giữ chữ tắt trong ngoặc: "vectơ pháp tuyến
-- (VTPT)". Chủ dự án quyết bỏ hẳn chữ tắt → thay MỌI lần xuất hiện bằng cụm
-- đầy đủ và gỡ luôn phần trong ngoặc.
--
-- Lần này sửa CẢ đáp án và phương án nhiễu, không chỉ đề: học sinh không nên
-- gặp chữ tắt ở bất kỳ đâu.
--
-- Rà 1868 câu active → 301 câu cần sửa.
-- CHẠY: node packages/db/run-sql.mjs packages/db/drop-abbreviations.sql
-- ═══════════════════════════════════════════════════════════════════════

BEGIN;

UPDATE questions SET noi_dung = 'Cho bất phương trình x − y > 0 (có c = 0): a) Đường thẳng bờ x − y = 0 đi qua gốc O b) Có thể dùng O(0; 0) làm điểm thử c) Có thể dùng (1; 0) làm điểm thử d) Vẽ bờ bằng nét ĐỨT' WHERE id = '01f19a1c-7f8c-42cd-ba86-51a60ca500f9';
UPDATE questions SET noi_dung = 'Bài làm: ''Xác định miền nghiệm của bất phương trình 3x − y < 0. ① Vẽ bờ 3x − y = 0 nét ĐỨT, qua O(0;0) và (1;3). ✓ ② Chọn điểm thử O(0;0) (vì đây là điểm dễ tính nhất). ③ Thay vào: 3(0) − 0 = 0. Hỏi 0 < 0? ⇒ SAI. ④ Vì thử O ra SAI ⇒ tô nửa mặt phẳng KHÔNG CHỨA O.'' Tìm và sửa lỗi.', dap_an = 'Bước ① ĐÚNG (bờ chuẩn, nét đứt chuẩn — kiểm: 3(1) − 3 = 0 ✓). Bước ③ TÍNH ĐÚNG (0 < 0 quả thật SAI). LỖI CHÍ MẠNG Ở BƯỚC ② — DÙNG O LÀM ĐIỂM THỬ! Kiểm: thay O vào phương trình bờ 3x − y = 0 → 3(0) − 0 = 0 = 0 ✓ ⇒ O NẰM ĐÚNG TRÊN BỜ (chính bạn ấy đã vẽ bờ QUA O ở bước ①!) ⇒ O KHÔNG DÙNG ĐƯỢC! CÁCH ĐÚNG: ② đổi điểm thử sang (1;0). Kiểm: 3(1) − 0 = 3 ≠ 0 ✓ DÙNG ĐƯỢC. ③ thay (1;0) vào bất phương trình gốc: 3(1) − 0 = 3. Hỏi 3 < 0? SAI ✗ ④ ⇒ tô nửa mp KHÔNG CHỨA (1;0) (tức nửa phía trên đường y = 3x) ✓' WHERE id = '0230353b-9530-4d02-b1bd-216ea6cb3feb';
UPDATE questions SET loi_giai = 'Xét d₁: x + y = 0 và d₂: 2x + 2y - 4 = 0 (thực chất là x + y - 2 = 0). Nếu áp thẳng công thức mà không chuẩn hoá, ta có thể lấy |0 - (-4)|/√(1+1) = 4/√2 = 2√2 — SAI. Chuẩn hoá d₂ về x + y - 2 = 0 rồi tính: |0 - (-2)|/√2 = 2/√2 = √2 — ĐÚNG. Sai số gấp đôi! Lí do: nhân cả phương trình với k làm C nhân k nhưng cũng làm √(A²+B²) nhân |k|; nếu chỉ đổi C mà giữ nguyên mẫu của đường kia thì tỉ lệ bị phá vỡ.' WHERE id = '02537386-f4d1-4a2a-a234-89cce12bc5e6';
UPDATE questions SET distractors = '[{"phuong_an":"A","quan_niem_sai":"QUÊN x ≥ 0, y ≥ 0! (chỉ vẽ BPT① ⇒ nửa mp vô hạn) — bệnh A06! Bẫy PHỔ BIẾN NHẤT: x ≥ 0 và y ≥ 0 CŨNG LÀ bất phương trình phải vẽ!"},{"phuong_an":"C","quan_niem_sai":"Lấy HỢP (gộp cả 3 miền) hoặc bỏ qua BPT①"},{"phuong_an":"D","quan_niem_sai":"Nghĩ hệ vô nghiệm — sai! O(0;0) là nghiệm: 0 ≤ 4 ✓, 0 ≥ 0 ✓, 0 ≥ 0 ✓"}]'::jsonb WHERE id = '0294f497-b113-4b6d-ad40-20e7aecd944f';
UPDATE questions SET noi_dung = 'Viết phương trình tổng quát đường thẳng đi qua M(4; -1) và song song với trục Ox.' WHERE id = '03b0f6e1-c239-4105-b062-07618facd773';
UPDATE questions SET noi_dung = 'Viết phương trình chính tắc của elip có tâm sai e = 0,8 và tiêu cự bằng 8.', loi_giai = 'Tiêu cự 2c = 8 ⇒ c = 4. e = c/a = 0,8 ⇒ a = c/e = 4/0,8 = 5 ⇒ a² = 25. b² = a² - c² = 25 - 16 = 9. phương trình: x²/25 + y²/9 = 1. Kiểm e = 4/5 = 0,8 ✓.' WHERE id = '03d8cedb-2f8f-4b4f-80a7-9b455b32bd79';
UPDATE questions SET noi_dung = 'Hệ số BIẾN THIÊN được tính bằng ____ CHIA cho ____ (thường nhân thêm 100% để biểu diễn dưới dạng phần trăm).' WHERE id = '03dc5850-e432-406f-9471-87bd0983b91c';
UPDATE questions SET distractors = '[{"phuong_an":"u = (3; -4)","quan_niem_sai":"Lấy thẳng hệ số A, B làm vectơ chỉ phương — đó là vectơ pháp tuyến"},{"phuong_an":"u = (-4; 3)","quan_niem_sai":"Hoán vị nhưng đổi dấu sai vị trí"},{"phuong_an":"u = (3; 4)","quan_niem_sai":"Lấy hệ số nhưng bỏ dấu âm"}]'::jsonb, loi_giai = 'Từ phương trình tổng quát, vectơ pháp tuyến n = (3; -4). vectơ chỉ phương vuông góc với vectơ pháp tuyến: u = (4; 3) vì 3·4 + (-4)·3 = 0.' WHERE id = '04529c24-f00f-4b5a-ae85-f1f640add34d';
UPDATE questions SET noi_dung = 'So sánh CHIỀU CAO (trung bình=160cm, độ lệch chuẩn=5cm) và CÂN NẶNG (trung bình=55kg, độ lệch chuẩn=8kg) của MỘT nhóm học sinh. TÍNH hệ số biến thiên cho MỖI đại lượng, xem đại lượng NÀO ''TƯƠNG ĐỐI'' PHÂN TÁN NHIỀU HƠN. (Hỏi kèm độ tự tin 1–3)', dap_an = 'hệ số biến thiên(chiều cao)=5/160×100%≈3,1%; hệ số biến thiên(cân nặng)=8/55×100%≈14,5%; CÂN NẶNG ''TƯƠNG ĐỐI'' PHÂN TÁN NHIỀU HƠN.', distractors = '[{"phuong_an":"So SÁNH TRỰC TIẾP độ LỆCH CHUẨN (5cm so với 8kg) để KẾT LUẬN CÂN NẶNG phân TÁN NHIỀU HƠN, mà KHÔNG TÍNH hệ số biến thiên","quan_niem_sai":"SO SÁNH TRỰC TIẾP HAI ĐỘ LỆCH CHUẨN có ĐƠN VỊ KHÁC NHAU (cm so với kg), một PHÉP so SÁNH KHÔNG CÓ Ý NGHĨA (giống như SO SÁNH ''TÁO với CAM''), CẦN CHUẨN HOÁ bằng hệ số biến thiên TRƯỚC KHI so SÁNH."}]'::jsonb, loi_giai = 'Vì CHIỀU CAO và CÂN NẶNG có ĐƠN VỊ và QUY MÔ KHÁC NHAU, CẦN dùng hệ số biến thiên (KHÔNG PHẢI so SÁNH TRỰC TIẾP ĐỘ LỆCH CHUẨN) để so SÁNH CÔNG BẰNG.' WHERE id = '05cf73e6-8d04-4cb9-abf9-e35dc9416d8b';
UPDATE questions SET loi_giai = 'Trục Ox có phương trình y = 0. d(I(a;b), Ox) = |b|/√(0+1) = |b| ⇒ R = |b|.' WHERE id = '06496c52-9e56-4761-8077-c56a36544373';
UPDATE questions SET noi_dung = 'Xác định miền nghiệm của bất phương trình x + y ≥ 3. B1 — VẼ BỜ: viết phương trình bờ, tìm 2 điểm, chọn nét. B2 — CHỌN ĐIỂM THỬ: chọn điểm nào? kiểm nó có nằm trên bờ không. B3 — THAY VÀO bất phương trình GỐC: đúng hay sai? B4 — TÔ MIỀN: tô nửa nào?' WHERE id = '0799bb09-e809-4970-863e-99f7c78cc049';
UPDATE questions SET distractors = '[{"phuong_an":"(Ax₀ + By₀ + C) / √(A² + B²)","quan_niem_sai":"Quên trị tuyệt đối ⇒ có thể ra khoảng cách âm"},{"phuong_an":"|Ax₀ + By₀ + C| / (A² + B²)","quan_niem_sai":"Quên khai căn ở mẫu"},{"phuong_an":"|Ax₀ + By₀ + C| / (A + B)","quan_niem_sai":"Mẫu số dùng tổng hệ số thay vì độ dài vectơ pháp tuyến"}]'::jsonb, loi_giai = 'Tử số có trị tuyệt đối (khoảng cách không âm), mẫu số là độ dài vectơ pháp tuyến.' WHERE id = '07bb3ddb-ff17-4355-9aae-53d8b8b221ea';
UPDATE questions SET noi_dung = 'Đường thẳng Δ đi qua M(2; 1) và có vectơ pháp tuyến n = (3; -4). Tính khoảng cách từ gốc toạ độ O đến Δ.', distractors = '[{"phuong_an":"-2/5","quan_niem_sai":"Quên trị tuyệt đối ở tử"},{"phuong_an":"2/25","quan_niem_sai":"Quên khai căn ở mẫu (dùng 25 thay vì 5)"},{"phuong_an":"10/5 = 2","quan_niem_sai":"Khai triển sai phương trình tổng quát (ra 3x - 4y + 10 = 0 do sai dấu)"}]'::jsonb, loi_giai = 'phương trình tổng quát của Δ: 3(x-2) - 4(y-1) = 0 ⇔ 3x - 4y - 2 = 0. d(O, Δ) = |3·0 - 4·0 - 2| / √(9+16) = 2/5 = 0,4.' WHERE id = '07eb0ab0-0a12-4715-9203-db4cafeb0927';
UPDATE questions SET distractors = '[{"phuong_an":"Sai, vì còn có hai đường chéo nhau","quan_niem_sai":"Áp nhầm kiến thức không gian vào bài toán trong mặt phẳng Oxy"},{"phuong_an":"Sai, vì hai đường trùng nhau cũng không có điểm chung","quan_niem_sai":"Hiểu sai: trùng nhau có VÔ SỐ điểm chung"},{"phuong_an":"Không kết luận được nếu chưa biết vectơ pháp tuyến","quan_niem_sai":"Không nắm được phân loại vị trí tương đối trong mặt phẳng"}]'::jsonb WHERE id = '080034de-2529-4ab5-8b98-d547958d53d1';
UPDATE questions SET noi_dung = 'Chứng minh rằng phương trình x² + y² - 2ax - 2by + c = 0 luôn đưa được về dạng (x-a)² + (y-b)² = a² + b² - c, và nêu ý nghĩa của ba trường hợp dấu của a² + b² - c.' WHERE id = '083f94c1-089f-44df-afa8-824a549cbe7b';
UPDATE questions SET noi_dung = 'Học sinh viết tiếp tuyến của (x-2)² + y² = 4 tại M(2; 2) như sau: ''IM = (0; 2) nên phương trình tiếp tuyến là 0(x-2) + 2(y-2) = 0 ⇔ y = 2.'' Đúng hay sai?', dap_an = 'ĐÚNG. Tâm I(2; 0), IM = (0; 2) là vectơ pháp tuyến. phương trình: 2(y - 2) = 0 ⇔ y = 2. Kiểm: d(I, y=2) = |0 - 2|/1 = 2 = R ✓ tiếp xúc.', distractors = '[{"phuong_an":"Sai, vì vectơ pháp tuyến không được có thành phần bằng 0","quan_niem_sai":"Hiểu sai: vectơ pháp tuyến chỉ cần KHÁC vectơ-không, có thể có một thành phần 0"},{"phuong_an":"Sai, phương trình đúng phải là x = 2","quan_niem_sai":"Nhầm đường ngang với đường đứng"},{"phuong_an":"Sai, vì phải dùng IM làm vectơ chỉ phương","quan_niem_sai":"Nhầm vai trò vectơ pháp tuyến/vectơ chỉ phương của tiếp tuyến"}]'::jsonb, loi_giai = 'Kiểm tra M thuộc (C): (2-2)² + 2² = 4 ✓. vectơ pháp tuyến IM = (0; 2), phương trình tiếp tuyến: 0·(x-2) + 2·(y-2) = 0 ⇔ y = 2. Đây là đường nằm ngang, đúng là tiếp tuyến (chạm đường tròn tại đúng M). Lời giải của học sinh hoàn toàn đúng.' WHERE id = '08685f22-43fc-488b-a7c7-1f6776573616';
UPDATE questions SET noi_dung = 'Cho bất phương trình 3x + y ≥ 0. Điểm nào DÙNG ĐƯỢC làm điểm thử? Giải thích ngắn. A. O(0; 0) B. (1; 0) C. (1; −3) D. (−2; 6)' WHERE id = '088f7bbe-b129-4d1d-8ffd-4911c2455e2c';
UPDATE questions SET loi_giai = 'Từ phương trình: y² = b²(x²/a² - 1) ⇒ y = ±(b/a)·√(x² - a²) (nhánh dương). So với tiệm cận y = (b/a)x: hiệu = (b/a)[x - √(x² - a²)]. Nhân liên hợp: x - √(x²-a²) = a²/[x + √(x²-a²)]. Khi x → +∞, mẫu → ∞ ⇒ hiệu → 0 ⇒ hypebol tiến SÁT tiệm cận. Nhưng hiệu = (b/a)·a²/[x + √(x²-a²)] = ab/[x + √(x²-a²)] > 0 LUÔN dương với mọi x hữu hạn ⇒ KHÔNG BAO GIỜ bằng 0 ⇒ không chạm. Đó chính là bản chất của ''tiệm cận''.' WHERE id = '09bd7163-5860-4d5c-9315-58617ebb30a2';
UPDATE questions SET noi_dung = 'Xét tính đúng/sai: x² + y² = 9 là phương trình đường tròn tâm O(0; 0), bán kính 3.', distractors = '[{"phuong_an":"Sai, bán kính là 9","quan_niem_sai":"Quên khai căn R²"},{"phuong_an":"Sai, vì thiếu tâm","quan_niem_sai":"Không nhận ra a = b = 0 là tâm ở gốc"},{"phuong_an":"Sai, đây là phương trình đường thẳng","quan_niem_sai":"Không phân biệt phương trình bậc hai với bậc nhất"}]'::jsonb WHERE id = '09ca2ec1-a491-4937-af46-baf748f2a39a';
UPDATE questions SET distractors = '[{"phuong_an":"1","quan_niem_sai":"Chỉ tính O(0;0) — không tìm các giao điểm khác"},{"phuong_an":"0","quan_niem_sai":"Nghĩ miền vô hạn (không có đỉnh) — QUÊN x,y ≥ 0 (bệnh A06!)"},{"phuong_an":"4","quan_niem_sai":"Đếm nhầm — nghĩ ''3 bất phương trình thì 4 đỉnh''"}]'::jsonb, loi_giai = '3 bờ: x+y = 4, x = 0, y = 0 ⇒ có C(3,2) = 3 giao điểm. G₁ = x=0 ∩ y=0 → (0;0): 0 ≤ 4 ✓, 0 ≥ 0 ✓, 0 ≥ 0 ✓ ⇒ ĐỈNH ✓ | G₂ = y=0 ∩ x+y=4 → (4;0): 4 ≤ 4 ✓, 4 ≥ 0 ✓, 0 ≥ 0 ✓ ⇒ ĐỈNH ✓ | G₃ = x=0 ∩ x+y=4 → (0;4): 4 ≤ 4 ✓, 0 ≥ 0 ✓, 4 ≥ 0 ✓ ⇒ ĐỈNH ✓ → CẢ 3 đều là đỉnh ⇒ 3 đỉnh (miền = TAM GIÁC). LƯU Ý: với hệ 3 bất phương trình tạo tam giác, thường cả 3 giao điểm đều là đỉnh. NHƯNG với hệ 4 bất phương trình thì KHÁC HẲN (xem Q08!)' WHERE id = '0a995608-448a-4154-b860-ce03dac58011';
UPDATE questions SET loi_giai = 'Song song Oy ⇒ hệ số y = 0 và hệ số x ≠ 0: m - 2 = 0 ⇒ m = 2; nhưng khi m = 2 thì m² - 4 = 0, cả hai hệ số bằng 0 ⇒ phương trình thành 1 = 0, KHÔNG là đường thẳng. Vậy m = 2 bị loại. Kiểm tra m = -2: hệ số x = 0, hệ số y = -4 ≠ 0 ⇒ -4y + 1 = 0 ⇒ y = 1/4, song song Ox chứ không phải Oy. Kết luận: KHÔNG có giá trị m nào để d song song Oy.' WHERE id = '0b0002eb-87bd-49d7-b5a2-8511674260f7';
UPDATE questions SET noi_dung = 'Cho bất phương trình 2x + y ≤ 8. Xét từng cặp: a) (1; 3) là nghiệm b) (3; 1) là nghiệm c) (4; 0) là nghiệm d) (5; 2) là nghiệm' WHERE id = '0c392227-0629-4075-b9cc-71c79e41174e';
UPDATE questions SET noi_dung = 'Cho parabol y² = 12x. Tìm toạ độ tiêu điểm F và phương trình đường chuẩn.' WHERE id = '0e4444d2-25c3-4c21-a91e-39ea3c1552ae';
UPDATE questions SET noi_dung = 'Điền: d₁ // d₂ ⇔ hai vectơ pháp tuyến ______ VÀ hai đường thẳng ______.' WHERE id = '0e44eca2-3564-487f-af24-2af6221971dc';
UPDATE questions SET noi_dung = '(a) Khi HAI mẫu có ĐƠN VỊ HOẶC QUY MÔ RẤT KHÁC NHAU, nên dùng HỆ SỐ BIẾN THIÊN (= độ lệch chuẩn/trung bình) để SO SÁNH ĐỘ PHÂN TÁN một CÁCH CÔNG BẰNG. (b) ĐỘ LỆCH CHUẨN LỚN HƠN LUÔN có nghĩa dữ liệu ''TỆ HƠN'' về mặt CHẤT LƯỢNG. (c) Khi SO SÁNH ĐỘ PHÂN TÁN, CẦN xem xét CẢ THƯỚC ĐO XU THẾ TRUNG TÂM (để hiểu BỐI CẢNH). (d) VIỆC so SÁNH ĐỘ PHÂN TÁN CHỈ CÓ Ý NGHĨA khi HAI mẫu có CÙNG SỐ LƯỢNG giá trị (n).' WHERE id = '0e53c8a1-b603-4b87-b474-1f3a2ffbb562';
UPDATE questions SET noi_dung = 'Nếu x là SỐ QUYỂN VỞ mua được, ngoài bất phương trình về tiền, ta bắt buộc phải thêm điều kiện: x ___ 0' WHERE id = '0f2120d2-ac7c-4411-b969-56794bed45b9';
UPDATE questions SET noi_dung = 'Đưa bất phương trình 3x − 2 ≤ 5 − 2y về dạng chuẩn ax + by ≤ c, xác định a, b, c. B1: Chuyển ẩn sang trái, hằng số sang phải. B2: Xác định a, b, c. B3: Kiểm điều kiện — có phải bất phương trình bậc nhất hai ẩn không?', dap_an = 'B1: 3x + 2y ≤ 5 + 2 ⇒ 3x + 2y ≤ 7 | B2: a = 3 · b = 2 · c = 7 | B3: a = 3 ≠ 0 ✓, cả hai ẩn bậc 1 ✓ ⇒ ĐÚNG là bất phương trình bậc nhất hai ẩn', loi_giai = 'Chuyển −2y từ phải sang trái → đổi dấu thành +2y. Đây là phép CỘNG 2y vào cả hai vế — KHÔNG đổi chiều bất phương trình (chỉ nhân/chia số âm mới đổi chiều!).' WHERE id = '0f79f97d-836e-467a-a700-2547ae0f090c';
UPDATE questions SET noi_dung = 'Lập phương trình đường tròn đi qua A(1; 2), B(5; 2) và có tâm nằm trên đường thẳng d: x - y = 0.' WHERE id = '11972abf-9c43-48b0-b566-645c3fbedf69';
UPDATE questions SET dap_an = 'Sai. R CHỈ dựa vào HAI giá trị CỰC TRỊ (LỚN NHẤT, NHỎ NHẤT), KHÔNG PHẢN ÁNH được CÁCH các giá trị Ở GIỮA PHÂN BỐ; VÍ DỤ, mẫu A: 1,2,3,4,5,10 và mẫu B: 1,9,9,9,9,10 (CẢ HAI đều có R=9), NHƯNG mẫu A có các giá trị PHÂN BỐ TƯƠNG ĐỐI ĐỀU, trong khi mẫu B có PHẦN LỚN giá trị TẬP TRUNG GẦN 9 (chỉ HAI giá trị Ở HAI ĐẦU CỰC) — HAI mẫu này có ''CẤU TRÚC PHÂN BỐ'' RẤT KHÁC NHAU DÙ CÓ CÙNG R; điều này cho thấy R KHÔNG ĐỦ để MÔ TẢ ĐẦY ĐỦ ''ĐỘ PHÂN TÁN'' của dữ liệu, cần THÊM các THƯỚC ĐO KHÁC (như khoảng tứ phân vị, PHƯƠNG SAI, ĐỘ LỆCH CHUẨN) để có BỨC TRANH ĐẦY ĐỦ HƠN.' WHERE id = '122cb32b-54ad-41c4-a423-54c9d3e12dfd';
UPDATE questions SET noi_dung = 'Cho bất phương trình x + 2y ≤ 0. Đếm số điểm KHÔNG DÙNG ĐƯỢC làm điểm thử: O(0;0) · A(2;−1) · B(1;0) · C(−4;2) · D(0;1)' WHERE id = '129a738b-9c54-4b95-87e7-6fda8ad67a5f';
UPDATE questions SET noi_dung = 'Cho hệ: ⎧ x + y ≤ 4 · ⎨ x ≥ 0 · ⎩ y ≥ 0. (a) MÔ TẢ cách vẽ miền nghiệm (bờ, nét, điểm thử, hướng tô cho TỪNG bất phương trình). (b) Miền nghiệm là hình gì? Nêu toạ độ các đỉnh. (c) KIỂM CHỨNG bằng 2 điểm: một TRONG miền, một NGOÀI miền. (d) Nếu BỎ điều kiện x ≥ 0 và y ≥ 0 thì miền nghiệm thay đổi thế nào?' WHERE id = '13f88686-77ef-44c8-bdfc-94ed15136794';
UPDATE questions SET distractors = '[{"phuong_an":"4","quan_niem_sai":"Tính cả (0;0)! HS quen ''O luôn là nghiệm'' (từ A04) nên MẶC ĐỊNH tính nó vào. NHƯNG hệ này có x ≥ 1 (không phải x ≥ 0!) ⇒ O KHÔNG thuộc miền! BÀI HỌC: KHÔNG có điểm nào ''mặc định thuộc miền''!"},{"phuong_an":"5","quan_niem_sai":"Lấy HỢP: điểm nào thoả ít nhất một bất phương trình là tính"},{"phuong_an":"2","quan_niem_sai":"Loại nhầm điểm trên bờ (bệnh nét liền/đứt — A03!)"}]'::jsonb WHERE id = '1422818d-a4b7-4ccd-ae44-6a9048fc7555';
UPDATE questions SET noi_dung = 'Một bạn nói: ''khoảng tứ phân vị LUÔN BẰNG MỘT NỬA của khoảng biến thiên R.'' Chỉ ra lỗi. (Hỏi kèm độ tự tin 1–3)', dap_an = 'Sai. KHÔNG CÓ MỐI QUAN HỆ TOÁN HỌC CỐ ĐỊNH nào giữa khoảng tứ phân vị và R theo dạng ''khoảng tứ phân vị LUÔN BẰNG MỘT NỬA R''; khoảng tứ phân vị (đo 50% dữ liệu Ở GIỮA) và R (đo TOÀN BỘ phạm VI) là HAI THƯỚC ĐO KHÁC NHAU, TÍNH TOÁN DỰA trên các ĐIỂM DỮ LIỆU KHÁC NHAU (khoảng tứ phân vị dùng Q1,Q3; R dùng GIÁ TRỊ CỰC TRỊ) — MỐI QUAN HỆ GIỮA CHÚNG PHỤ THUỘC HOÀN TOÀN vào CÁCH PHÂN BỐ CỤ THỂ của dữ liệu, KHÔNG có MỘT TỈ LỆ CỐ ĐỊNH nào (''MỘT NỬA'') áp DỤNG cho MỌI trường HỢP.' WHERE id = '150d8b73-b0db-4911-9d02-c1cc7ccd6876';
UPDATE questions SET noi_dung = 'Vẽ bờ của bất phương trình 2x + 3y ≤ 6. B1: Viết phương trình đường thẳng bờ. B2: Tìm hai giao điểm với trục toạ độ. B3: Xác định kiểu nét vẽ, mô tả đường thẳng.', loi_giai = 'Bước B1 bị bỏ nhiều nhất — HS thấy bất phương trình ≤ rồi vẽ luôn, quên rằng bờ là một PHƯƠNG TRÌNH (dấu =).' WHERE id = '169cc0e0-ab9d-432d-9036-1a56f48d847c';
UPDATE questions SET loi_giai = 'QUY TRÌNH ĐÚNG 3 BƯỚC: ① Giải TẤT CẢ các cặp bờ ⇒ 6 giao điểm (bé làm rồi ✓) ② SÀNG LỌC! (bé QUÊN bước này!) — thay TỪNG giao điểm vào CẢ HỆ: thoả HẾT ⇒ LÀ ĐỈNH ✓ · hỏng dù chỉ 1 bất phương trình ⇒ LOẠI NGAY! ③ Đếm số điểm CÒN LẠI ⇒ đó mới là số đỉnh thật ✓ KẾT QUẢ: (0;0) thoả hết ⇒ ĐỈNH · (3;0) ⇒ ĐỈNH · (2;2) ⇒ ĐỈNH · (0;4) ⇒ ĐỈNH · (4;0) vượt rào② ⇒ LOẠI! · (0;6) vượt rào① ⇒ LOẠI! ⇒ CHỈ 4 ĐỈNH (miền = TỨ GIÁC) ✓ QUY LUẬT: 3 bất phương trình → 3 giao điểm → 3 đỉnh → loại 0 | 4 bất phương trình → 6 giao điểm → 4 đỉnh → LOẠI 2 | 5 bất phương trình → 10 giao điểm → 5 đỉnh → LOẠI 5 ⇒ Càng NHIỀU bất phương trình, càng NHIỀU giao điểm bị LOẠI! (Đừng bao giờ tin ''số giao điểm = số đỉnh''!) VÌ SAO PHẢI CẨN THẬN? Ở bài sau (B03), bé sẽ TÌM MAX/MIN bằng cách thay CÁC ĐỈNH vào hàm mục tiêu! ⇒ Lấy nhầm đỉnh (điểm ngoài miền) ⇒ max/min SAI HOÀN TOÀN! VD: nếu bé lấy nhầm (0;6), tính F = 3x + 2y = 0 + 12 = 12 — có vẻ LỚN NHẤT! NHƯNG điểm đó KHÔNG khả thi ⇒ đáp án SAI! Rubric: Chưa đạt (chỉ nói ''phải kiểm lại'') | Cần cố gắng (nêu phải sàng lọc nhưng không có ẩn dụ/ví dụ số) | Đạt (có ẩn dụ (hàng rào/vườn), ví dụ SỐ ((4;0) vượt bờ②), quy trình 3 bước) | Tốt (đủ ý trên VÀ nêu quy luật C(n,2) VÀ cảnh báo HẬU QUẢ ở B03 (lấy nhầm đỉnh ⇒ max/min SAI!) — HS không cảnh báo hậu quả là CHƯA ĐẠT vì đó là lí do quan trọng nhất phải sàng lọc!).' WHERE id = '171e64bb-9d62-42a7-a93b-9fa6b2d1baf6';
UPDATE questions SET distractors = '[{"phuong_an":"|C₁ + C₂| / √(A² + B²)","quan_niem_sai":"Cộng thay vì trừ hai hệ số tự do"},{"phuong_an":"|C₁ - C₂| / (A² + B²)","quan_niem_sai":"Quên khai căn ở mẫu"},{"phuong_an":"|C₁ - C₂| / (A + B)","quan_niem_sai":"Mẫu số lấy tổng hệ số thay vì độ dài vectơ pháp tuyến"}]'::jsonb, loi_giai = 'Điều kiện tiên quyết: phải chuẩn hoá để hai phương trình có CÙNG cặp hệ số A, B rồi mới áp dụng.' WHERE id = '1827ddb9-0e3d-442e-beea-d8b6e8769f3c';
UPDATE questions SET noi_dung = 'Viết phương trình tổng quát đường thẳng đi qua M(1; 2) và vuông góc với d: 3x - y + 4 = 0.', distractors = '[{"phuong_an":"3x - y - 1 = 0","quan_niem_sai":"Lấy nguyên vectơ pháp tuyến của d ⇒ ra đường SONG SONG với d"},{"phuong_an":"x + 3y + 7 = 0","quan_niem_sai":"Đúng vectơ pháp tuyến nhưng sai dấu hệ số tự do"},{"phuong_an":"3x + y - 5 = 0","quan_niem_sai":"Chỉ đổi dấu hệ số B, không hoán vị"}]'::jsonb, loi_giai = 'd có vectơ pháp tuyến (3; -1) ⇒ vectơ chỉ phương (1; 3). Đường vuông góc với d nhận vectơ chỉ phương của d làm vectơ pháp tuyến: n = (1; 3). phương trình tổng quát: 1(x-1) + 3(y-2) = 0 ⇔ x + 3y - 7 = 0. Kiểm tra M: 1 + 6 - 7 = 0 ✓. Kiểm vuông góc: 3·1 + (-1)·3 = 0 ✓.' WHERE id = '18a15322-4714-42f0-8413-ba6b63c239a5';
UPDATE questions SET noi_dung = 'Kiểm tra cặp (−1; 4) có là nghiệm của bất phương trình 2x + 3y ≥ 10 không. B1: Xác định x = ? và y = ? (chú ý THỨ TỰ!) B2: Thay vào vế trái, tính giá trị. B3: So sánh với vế phải, kết luận.' WHERE id = '198dfedb-fb85-4deb-8d43-c677f1c9d142';
UPDATE questions SET noi_dung = 'Viết phương trình tiếp tuyến của (C): (x-1)² + (y-2)² = 25 tại điểm M(4; 6).', distractors = '[{"phuong_an":"4x - 3y + 2 = 0","quan_niem_sai":"Lấy IM làm vectơ chỉ phương thay vì vectơ pháp tuyến (hoán vị đổi dấu)"},{"phuong_an":"3x + 4y + 36 = 0","quan_niem_sai":"Sai dấu hệ số tự do khi khai triển"},{"phuong_an":"3x + 4y - 11 = 0","quan_niem_sai":"Dùng toạ độ tâm I thay vì tiếp điểm M khi viết phương trình"}]'::jsonb, loi_giai = 'Tâm I(1; 2). Kiểm M thuộc (C): (4-1)² + (6-2)² = 9 + 16 = 25 ✓. vectơ pháp tuyến của tiếp tuyến = IM = (4-1; 6-2) = (3; 4). phương trình: 3(x-4) + 4(y-6) = 0 ⇔ 3x + 4y - 36 = 0. Kiểm M: 12 + 24 - 36 = 0 ✓.' WHERE id = '1abcbcab-793a-4ec6-9d58-b05866e8284b';
UPDATE questions SET noi_dung = 'Viết phương trình tổng quát của đường thẳng đi qua hai điểm A(2; 1) và B(4; 5).', distractors = '[{"phuong_an":"2x + 4y - 8 = 0","quan_niem_sai":"Lấy vectơ chỉ phương (2;4) làm vectơ pháp tuyến"},{"phuong_an":"2x - y + 3 = 0","quan_niem_sai":"Sai dấu hệ số tự do"},{"phuong_an":"x - 2y = 0","quan_niem_sai":"Đảo hai thành phần vectơ pháp tuyến"}]'::jsonb, loi_giai = 'AB = (2; 4) là vectơ chỉ phương ⇒ vectơ pháp tuyến n = (4; -2), rút gọn (2; -1). phương trình tổng quát: 2(x - 2) - 1(y - 1) = 0 ⇔ 2x - y - 3 = 0. Kiểm tra A: 4 - 1 - 3 = 0 ✓; B: 8 - 5 - 3 = 0 ✓.' WHERE id = '1af0786d-b8b6-4bc4-9769-864832285a91';
UPDATE questions SET noi_dung = 'Đếm số biểu thức LÀ bất phương trình bậc nhất hai ẩn: (1) x + y ≤ 3 · (2) x² + y ≥ 1 · (3) 2x − 5y > 0 · (4) xy < 4 · (5) 3y ≤ 6 · (6) x/y ≥ 2' WHERE id = '1b52ff9d-8167-4970-9f6f-912bb930875a';
UPDATE questions SET dap_an = 'Bé KHÔNG CẦN thử hết đâu! Chỉ cần thử VÀI ĐỈNH thôi! ẨN DỤ MẶT TRỜI LẶN TRÊN HÒN ĐẢO: miền nghiệm là một HÒN ĐẢO (hình đa giác). Ánh nắng chiếu XIÊN (theo hướng cố định — chính là hướng của hàm F). Mặt trời LẶN DẦN… bóng tối lan dần khắp đảo… Chỗ CUỐI CÙNG còn nắng là ở đâu? ⇒ Là MỎM ĐÁ NHÔ RA XA NHẤT — tức một ĐỈNH của đảo! ✓ KHÔNG BAO GIỜ là điểm ở GIỮA đảo (vì giữa đảo tối trước mỏm đá!) GIẢI THÍCH TOÁN HỌC: hàm F = ax + by = k (k = hằng) là một ĐƯỜNG THẲNG! Đổi k ⇒ đường thẳng TRƯỢT SONG SONG (giữ nguyên hướng). Trượt về phía này → k TĂNG · phía kia → k GIẢM ⇒ trượt đến khi SẮP RỜI KHỎI miền ⇒ điểm chạm cuối cùng = ĐỈNH! QUY TRÌNH 3 BƯỚC: ① TÌM CÁC ĐỈNH (giải các cặp bờ → giao điểm → SÀNG LỌC! thay vào cả hệ, chỉ giữ điểm THUỘC miền!) ② LẬP BẢNG tính F tại TỪNG đỉnh ③ SO SÁNH: số LỚN NHẤT = giá trị lớn nhất ✓ · số NHỎ NHẤT = giá trị nhỏ nhất ✓ ⇒ CHỈ 4 PHÉP TÍNH — XONG! (thay vì thử vô số điểm!)', loi_giai = 'VÍ DỤ BẢNG: đỉnh (0;0) → F = 3(0)+2(0) = 0 | (3;0) → 9+0 = 9 | (2;2) → 6+4 = 10 ⬅️ MAX | (0;4) → 0+8 = 8 ⇒ giá trị lớn nhất = 10 tại (2;2) · giá trị nhỏ nhất = 0 tại (0;0) ✓ BÉ KHÔNG TIN? THỬ KIỂM CHỨNG! Lấy vài điểm BÊN TRONG miền, tính F xem có vượt 10 không: (1;1) → 3+2 = 5 < 10 ✓ | (2;1) → 6+2 = 8 < 10 ✓ | (1;2) → 3+4 = 7 < 10 ✓ | (2,5;1) → 7,5+2 = 9,5 < 10 ✓ ⇒ KHÔNG điểm nào vượt được 10! ⇒ Định lí ĐÚNG — max ở ĐỈNH! ✓ HAI CẢNH BÁO: ⚠️CẢNH BÁO 1 — ĐỈNH PHẢI ĐÚNG! Nhớ SÀNG LỌC giao điểm (B05)! Lấy nhầm một điểm NGOÀI miền ⇒ F ở đó có thể CAO HƠN giá trị lớn nhất thật ⇒ BÉ SẼ CHỌN NHẦM! VD: điểm (4;0) (ngoài miền!) cho F = 12 > 10 — hấp dẫn nhưng SAI! ⚠️CẢNH BÁO 2 — MIỀN PHẢI HỮU HẠN! Nếu miền VÔ HẠN (quên x ≥ 0, y ≥ 0!) ⇒ KHÔNG CÓ ĐỈNH ⇒ KHÔNG tìm được max! VD: miền là cả góc phần tư I ⇒ F = x + y tăng mãi mãi → +∞ ⇒ KHÔNG CÓ giá trị lớn nhất! Rubric: Chưa đạt (chỉ nói ''tính tại đỉnh'', không giải thích vì sao không cần thử điểm khác) | Cần cố gắng (nêu quy trình nhưng không có ẩn dụ hoặc không kiểm chứng) | Đạt (có ẩn dụ (mặt trời lặn / đường mức trượt), quy trình 3 bước, bảng ví dụ) | Tốt (đủ ý trên VÀ dạy KIỂM CHỨNG (thử điểm trong miền → không vượt max) VÀ cảnh báo CẢ HAI điều (① đỉnh phải đúng — sàng lọc! ② miền phải hữu hạn — nếu vô hạn thì không có max!) — HS không cảnh báo là CHƯA ĐẠT).' WHERE id = '1dac28bd-7ec9-46d1-adcd-6399200ba2d1';
UPDATE questions SET noi_dung = 'Nối mỗi bất phương trình với cách vẽ bờ. Trả lời ''1-x, 2-y, 3-z, 4-w'': Cột A: 1) 2x+y ≤ 4 · 2) 2x+y < 4 · 3) 2x+y ≥ 4 · 4) 2x+y > 4 Cột B: a) Nét LIỀN (bờ THUỘC miền) · b) Nét ĐỨT (bờ KHÔNG thuộc)' WHERE id = '1e3f2b71-98ad-45ba-b98e-b5cab6efa38f';
UPDATE questions SET noi_dung = 'Cho tam giác ABC: A(1; 1), B(5; 3), C(3; 7). Viết phương trình tổng quát đường trung tuyến kẻ từ A.', distractors = '[{"phuong_an":"3x - y - 2 = 0","quan_niem_sai":"Tính sai vectơ pháp tuyến từ vectơ chỉ phương AM"},{"phuong_an":"3x + 4y - 7 = 0","quan_niem_sai":"Lấy vectơ chỉ phương AM = (3;4) làm vectơ pháp tuyến"},{"phuong_an":"Trung tuyến qua trung điểm AB","quan_niem_sai":"Nhầm: trung tuyến từ A phải qua trung điểm cạnh ĐỐI BC"}]'::jsonb, loi_giai = 'Trung điểm M của BC: M = ((5+3)/2 ; (3+7)/2) = (4; 5). vectơ chỉ phương AM = (3; 4) ⇒ vectơ pháp tuyến n = (4; -3). phương trình tổng quát: 4(x-1) - 3(y-1) = 0 ⇔ 4x - 3y - 1 = 0. Kiểm tra A(1;1): 4 - 3 - 1 = 0 ✓; M(4;5): 16 - 15 - 1 = 0 ✓.' WHERE id = '1e80d89f-d751-42ad-b620-6ec03a20cf79';
UPDATE questions SET loi_giai = 'Hai đường đứng song song. Dạng phương trình tổng quát: x - 1 = 0 và x - 5 = 0, cùng hệ số (1; 0). d = |-1 - (-5)|/√(1+0) = 4/1 = 4. (Trực quan: hiệu hoành độ.)' WHERE id = '1fee0416-dca3-479b-9a09-09dc11147472';
UPDATE questions SET noi_dung = 'Cho hypebol x²/16 - y²/9 = 1. Viết phương trình hai đường tiệm cận dưới dạng tổng quát.' WHERE id = '21f1ce94-ac28-45c3-916f-178238ee4a02';
UPDATE questions SET noi_dung = 'Điền: Đường thẳng qua M(x₀; y₀) có vectơ chỉ phương u = (a; b) có phương trình tham số là x = ______ , y = ______.', distractors = '[{"phuong_an":"x = a + x₀t ; y = b + y₀t","quan_niem_sai":"Đảo vai trò điểm và vectơ chỉ phương"},{"phuong_an":"x = x₀ - at ; y = y₀ - bt","quan_niem_sai":"Sai dấu hệ thống trong công thức chuẩn"},{"phuong_an":"x = x₀ + bt ; y = y₀ + at","quan_niem_sai":"Đảo hai thành phần của vectơ chỉ phương"}]'::jsonb WHERE id = '226b95d4-bc16-4e17-bfc5-3411e12cfbbb';
UPDATE questions SET noi_dung = 'Chuyển phương trình đường tròn (x - 1)² + (y + 2)² = 9 sang dạng khai triển.' WHERE id = '2445faf4-60c6-491e-93e5-c6b468d36847';
