UPDATE questions SET noi_dung = 'Cho A(2; 4), B(6; 2). Viết phương trình tổng quát đường trung trực của đoạn AB.', distractors = '[{"phuong_an":"2x - y - 6 = 0","quan_niem_sai":"Tính sai toạ độ trung điểm"},{"phuong_an":"4x - 2y = 0 (đi qua A)","quan_niem_sai":"Trung trực đi qua TRUNG ĐIỂM, không đi qua đỉnh A"},{"phuong_an":"x + 2y - 10 = 0","quan_niem_sai":"Lấy AB làm vectơ chỉ phương thay vì vectơ pháp tuyến của trung trực"}]'::jsonb, loi_giai = 'Trung điểm I của AB: I = ((2+6)/2 ; (4+2)/2) = (4; 3). AB = (4; -2) là vectơ pháp tuyến của trung trực. phương trình tổng quát: 4(x-4) - 2(y-3) = 0 ⇔ 4x - 2y - 10 = 0 ⇔ 2x - y - 5 = 0. Kiểm tra I(4;3): 8 - 3 - 5 = 0 ✓.' WHERE id = '280e5540-b811-42d4-8b9e-a69239b7de7d';
UPDATE questions SET noi_dung = 'Đường thẳng d: 2x - 3y + 1 = 0 có một vectơ pháp tuyến là:', distractors = '[{"phuong_an":"n = (2; 3)","quan_niem_sai":"Bỏ dấu âm của hệ số B"},{"phuong_an":"n = (3; 2)","quan_niem_sai":"Nhầm sang vectơ chỉ phương (hoán vị đổi dấu)"},{"phuong_an":"n = (1; 1)","quan_niem_sai":"Lấy hệ số tự do làm vectơ pháp tuyến"}]'::jsonb, loi_giai = 'Với phương trình tổng quát Ax + By + C = 0, vectơ pháp tuyến là n = (A; B) = (2; -3).' WHERE id = '2937d85d-4c0a-4b3e-9091-aa7b759dcff7';
UPDATE questions SET distractors = '[{"phuong_an":"u = (2; -1)","quan_niem_sai":"Lấy toạ độ điểm đi qua làm vectơ chỉ phương"},{"phuong_an":"u = (5; -3)","quan_niem_sai":"Hoán vị và đổi dấu — đó là vectơ pháp tuyến, không phải vectơ chỉ phương"},{"phuong_an":"u = (-3; -5)... (loại)","quan_niem_sai":"Chọn phương án phủ định không hợp lí do hiểu vectơ chỉ phương là duy nhất"}]'::jsonb, loi_giai = 'Trong phương trình tham số, hệ số của t chính là toạ độ vectơ chỉ phương: u = (3; 5).' WHERE id = '298df87e-930e-42dd-b2da-980007c2e320';
UPDATE questions SET noi_dung = 'a) bất phương trình x + y ≤ 3 ⇒ vẽ bờ bằng nét LIỀN b) x + y > 3 ⇒ vẽ bờ bằng nét LIỀN c) Điểm (1; 2) (thoả 1+2 = 3) THUỘC miền nghiệm của x + y ≤ 3 d) Điểm (1; 2) THUỘC miền nghiệm của x + y > 3' WHERE id = '29c8a545-d33c-4e6f-a048-8b7b347f5680';
