UPDATE questions SET noi_dung = 'bất phương trình 2x − 3y ≤ 0 có đường thẳng bờ 2x − 3y = 0. Đường thẳng này chắc chắn đi qua: A. Điểm (1; 0) B. Gốc toạ độ O(0; 0) C. Điểm (0; 1) D. Không đi qua điểm nào cố định' WHERE id = '364493b7-5b15-4917-88c2-bbf682d8fbf6';
UPDATE questions SET noi_dung = 'Cho hệ: ⎧ x + y ≤ 5 · ⎩ x − y ≥ 1. Xét từng ý: a) Cặp (3; 1) thoả bất phương trình thứ nhất b) Cặp (3; 1) thoả thứ hai c) Cặp (3; 1) là NGHIỆM CỦA HỆ d) Cặp (1; 3) là nghiệm của hệ (vì nó thoả bất phương trình thứ nhất)', distractors = '[{"phuong_an":"d) chọn Đúng","quan_niem_sai":"BỆNH CHÍNH! Thấy ''thoả bất phương trình thứ nhất'' rồi kết luận là nghiệm hệ ⇒ hiểu hệ là HỢP! Cặp (3;1) và (1;3) là ĐỐI CHỨNG: cả hai cùng thoả BPT① (đều cho tổng 4), nhưng chỉ (3;1) thoả BPT②"}]'::jsonb WHERE id = '370ca943-7ec3-4aee-9591-38ee1a1ad5ad';
UPDATE questions SET dap_an = 'Bé nói đúng — đề KHÔNG nói! Nhưng điều kiện đó đến từ THỰC TẾ, không phải từ đề! ẨN DỤ ĐI SIÊU THỊ: bé có 60 nghìn, mua bút (10 ng/cây) và vở (15 ng/quyển). bất phương trình tiền: 10x + 15y ≤ 60. Thử (x = −3; y = 6): 10(−3) + 15(6) = −30 + 90 = 60 ≤ 60 ✓ THOẢ bất phương trình! Về mặt TOÁN thì ĐÚNG. Nhưng bé ra quầy nói: ''Cô ơi, cho con mua ÂM BA cây bút và 6 quyển vở ạ!'' — cô thu ngân sẽ...?! ''Âm ba cây bút'' nghĩa là bé MANG 3 cây bút ĐẾN CHO cửa hàng?! Mà bé chưa từng mua 3 cây đó — lấy đâu ra để trả?! Rồi cửa hàng phải TRẢ TIỀN cho bé 30 nghìn?! ⇒ HOÀN TOÀN VÔ LÍ! BÀI HỌC — ''RÀNG BUỘC ẨN'': ① Ràng buộc HIỆN — ĐỀ BÀI nói rõ (vd ''có 60 nghìn'' → 10x + 15y ≤ 60). ② Ràng buộc ẨN — BẢN CHẤT THỰC TẾ, đề KHÔNG nói (vd ''số bút không thể âm'' → x ≥ 0). Ràng buộc ẨN không có trong đề vì nó QUÁ HIỂN NHIÊN với con người! NHƯNG toán học KHÔNG ''đương nhiên'' gì cả — nó chỉ biết những gì bé VIẾT RA!', loi_giai = 'MẸO NHẬN DIỆN — tự hỏi ''x là cái gì?'': số cây bút / số kg gạo / số giờ / số người → KHÔNG THỂ ÂM → CẦN x ≥ 0! Nhiệt độ / lãi-lỗ → CÓ THỂ ÂM → không cần. QUY TẮC VÀNG: ''x là SỐ LƯỢNG (đếm được) ⇒ BẮT BUỘC x ≥ 0!'' HẬU QUẢ NẾU QUÊN: miền nghiệm từ TAM GIÁC HỮU HẠN (góc phần tư I) → NỬA MẶT PHẲNG VÔ HẠN (chứa phương án vô lí như (−3;6), (−100;200)!) ⇒ KHÔNG DÙNG ĐƯỢC! Khác biệt SỐNG CÒN — miền vô hạn thì KHÔNG tìm được phương án tốt nhất! CHÚ Ý: đôi khi ràng buộc còn CHẶT HƠN ≥ 0! Nếu đề nói ''CLB có 8 nhóm, mỗi nhóm cần ít nhất 1 bộ'' ⇒ không phải x ≥ 0 mà là x ≥ 8! Rubric: Chưa đạt (chỉ nói ''vì số lượng không âm'', không chứng minh hậu quả) | Cần cố gắng (giải thích được vì sao cần nhưng không có ví dụ phương án âm thoả bất phương trình) | Đạt (có ẩn dụ, ví dụ SỐ, quy tắc nhận diện) | Tốt (đủ ý trên VÀ nêu hậu quả HÌNH HỌC (miền vô hạn → hữu hạn) VÀ cảnh báo ràng buộc có thể CHẶT HƠN ≥ 0 (vd x ≥ 8) — HS chỉ nói ''phải ghi vào'' mà không chứng minh vì sao quan trọng là CHƯA ĐẠT).' WHERE id = '3798127c-3bb6-44c4-b1af-17cfd34dddb2';
UPDATE questions SET noi_dung = 'Cho A(1; 3), B(5; 1). Tìm một vectơ pháp tuyến của đường thẳng AB.', distractors = '[{"phuong_an":"n = (4; -2)","quan_niem_sai":"Lấy vectơ chỉ phương làm vectơ pháp tuyến"},{"phuong_an":"n = (-4; 2)","quan_niem_sai":"Chỉ đổi dấu vectơ chỉ phương"},{"phuong_an":"n = (6; 4)","quan_niem_sai":"Cộng toạ độ hai điểm thay vì trừ"}]'::jsonb, loi_giai = 'AB = (4; -2) là vectơ chỉ phương ⇒ vectơ pháp tuyến n = (-2; -4) hoặc (2; 4), rút gọn (1; 2). Kiểm tra: 4·1 + (-2)·2 = 0 ✓.' WHERE id = '37cba9af-fb88-4d65-b8ca-ff23ddf3a7e4';
UPDATE questions SET noi_dung = '(a) máy tính cầm tay thường hiển thị kết quả với một số chữ số HỮU HẠN, dù bản thân giá trị THỰC (như \(\sqrt{2}\)) có VÔ HẠN chữ số thập phân. (b) Khi CỘNG/NHÂN nhiều số gần đúng, SAI SỐ có thể TÍCH LUỸ (cộng dồn) qua các phép tính. (c) Nên GIỮ NHIỀU chữ số trong các bước TÍNH TOÁN TRUNG GIAN, và chỉ QUY TRÒN ở bước CUỐI CÙNG. (d) Việc quy tròn SỚM (ở mỗi bước trung gian) LUÔN cho kết quả CHÍNH XÁC HƠN so với việc quy tròn ở CUỐI CÙNG.' WHERE id = '38115be5-fa49-452a-b651-5c52303a807b';
UPDATE questions SET noi_dung = 'Cho d: x = 1 + mt, y = 2 + 3t. Tìm m để d có phương trình tổng quát là 3x - 2y + 1 = 0.', distractors = '[{"phuong_an":"m = 3","quan_niem_sai":"Lấy m bằng hệ số của x trong phương trình tổng quát"},{"phuong_an":"m = -2","quan_niem_sai":"Sai dấu khi suy vectơ chỉ phương từ vectơ pháp tuyến"},{"phuong_an":"m = -3/2","quan_niem_sai":"Dùng điều kiện vuông góc thay vì cùng phương"}]'::jsonb, loi_giai = 'phương trình tổng quát 3x - 2y + 1 = 0 có vectơ pháp tuyến (3; -2) ⇒ vectơ chỉ phương (2; 3). phương trình tham số phải có vectơ chỉ phương cùng phương (2;3), tức (m; 3) // (2; 3) ⇒ m·3 - 3·2 = 0 ⇒ m = 2. Kiểm tra mốc (1;2): 3·1 - 2·2 + 1 = 0 ✓ (mốc thuộc d, hợp lệ).' WHERE id = '38c04ead-c268-44cf-aad3-bee8ae023032';
UPDATE questions SET noi_dung = 'Cho mẫu: 4, 7, 9, 12, 15, 18, 22, 25 (n=8). Bước 1: Tìm Q1 (trung vị nửa dưới: 4,7,9,12). Bước 2: Tìm Q3 (trung vị nửa trên: 15,18,22,25). Bước 3: Tính khoảng tứ phân vị.', dap_an = 'Bước 1: Q1=(7+9)/2=8. Bước 2: Q3=(18+22)/2=20. Bước 3: khoảng tứ phân vị=Q3−Q1=20−8=12.', distractors = '[{"phuong_an":"Bước 3 (lỗi cài sẵn): ''khoảng tứ phân vị=Q1−Q3=8−20=−12'' (đảo ngược thứ tự trừ, cho ra kết quả âm)","quan_niem_sai":"misc_dao_nguoc_thu_tu_tru_iqr — đảo ngược THỨ TỰ phép TRỪ (dùng Q1−Q3 thay vì ĐÚNG phải là Q3−Q1), dẫn đến kết quả ÂM, VI PHẠM tính chất khoảng tứ phân vị LUÔN KHÔNG ÂM."}]'::jsonb, loi_giai = 'Quy trình đầy đủ: tìm Q1, Q3 từ hai nửa, sau đó tính hiệu để có khoảng tứ phân vị.' WHERE id = '391613b1-abab-4c8b-a162-cbc29e43152d';
UPDATE questions SET loi_giai = 'n₁ = (1;2), n₂ = (2;4) = 2·n₁ ⇒ hai vectơ pháp tuyến cùng phương ⇒ d₁ // d₂ (hệ số tự do 0 và -1 không tỉ lệ nên không trùng). Học sinh hiểu ngược điều kiện vuông góc.' WHERE id = '39897ac6-66b1-4d3b-b43a-e676fcf5dc2f';
UPDATE questions SET noi_dung = 'Bài làm: ''Kiểm tra cặp (2; 5) có là nghiệm của bất phương trình 5x + 2y ≤ 20 không. Tôi thay vào: 5(5) + 2(2) = 25 + 4 = 29. Vì 29 ≤ 20 SAI, nên (2; 5) KHÔNG là nghiệm.'' Tìm và sửa lỗi.' WHERE id = '39e4ebe0-5d7b-48a1-a667-2ed6d75789ff';
UPDATE questions SET distractors = '[{"phuong_an":"Bước 1 sai, giao Ox thì x = 0","quan_niem_sai":"Nhầm trục Ox với trục Oy"},{"phuong_an":"Bước 3 sai, phải là x = 2t","quan_niem_sai":"Không đọc đúng phương trình tham số đã cho (x = t)"},{"phuong_an":"Không có bước nào sai","quan_niem_sai":"Không kiểm tra lại phép giải phương trình bậc nhất"}]'::jsonb WHERE id = '3a1a78c0-b82b-404d-adfa-fd4697ee6e09';
UPDATE questions SET noi_dung = 'Tìm m để x² + y² - 2mx + 4y + m² + 3 = 0 là phương trình đường tròn.', dap_an = 'Mọi m ∈ ℝ (phương trình luôn là đường tròn, R = 1)', loi_giai = 'a = m, b = -2, c = m² + 3. Điều kiện: a² + b² - c > 0 ⇔ m² + 4 - (m² + 3) > 0 ⇔ 1 > 0 — LUÔN ĐÚNG với mọi m. Vậy phương trình là đường tròn với MỌI m, tâm I(m; -2), R² = 1 ⇒ R = 1 (bán kính không đổi, tâm chạy trên đường y = -2).' WHERE id = '3b7c7594-fa2f-4584-86f0-318aea6da28d';
UPDATE questions SET noi_dung = '(a) bất phương trình x + y ≤ 4 có BAO NHIÊU nghiệm? Giải thích. (b) MÔ TẢ tập nghiệm trên mặt phẳng Oxy. (c) Cho 3 nghiệm cụ thể và 1 cặp KHÔNG là nghiệm.' WHERE id = '3c860e35-ec44-4cb4-aee9-68aeebb2c309';
UPDATE questions SET noi_dung = 'Cho bất phương trình 2x − y > 0. (a) Giải thích vì sao KHÔNG dùng được O(0;0) làm điểm thử. (b) Dùng (1;0) → xác định miền nghiệm. (c) Dùng (0;1) → xác định miền nghiệm. (d) So sánh (b) và (c). Kết quả có giống nhau không? Vì sao điều đó QUAN TRỌNG?', dap_an = '(a) Bờ 2x − y = 0. Thay O: 2(0) − 0 = 0 = 0 ✓ ⇒ O NẰM ĐÚNG TRÊN BỜ! Điểm thử có nhiệm vụ CHỈ RA miền ở nửa NÀO — nhưng O KHÔNG THUỘC NỬA NÀO CẢ (ở RANH GIỚI)! Thay O: 0 > 0? SAI — nhưng ''SAI'' này không nói được miền ở nửa nào, vì CẢ HAI nửa đều ''không chứa O''! ⇒ Thông tin BẰNG KHÔNG. (b) Kiểm (1;0): 2(1) − 0 = 2 ≠ 0 ✓ DÙNG ĐƯỢC. Thay vào bất phương trình: 2 > 0? ĐÚNG ✓ ⇒ tô nửa CHỨA (1;0) (nét ĐỨT vì dấu >). (c) Kiểm (0;1): 2(0) − 1 = −1 ≠ 0 ✓ DÙNG ĐƯỢC. Thay: −1 > 0? SAI ✗ ⇒ tô nửa KHÔNG CHỨA (0;1). (d) Về CHỮ nghe ''ngược nhau'' — NHƯNG CHỈ VÀO CÙNG MỘT NỬA! Vì (1;0) và (0;1) nằm ở HAI NỬA KHÁC NHAU: (1;0) cho 2 > 0 → nửa DƯỚI đường y = 2x · (0;1) cho −1 < 0 → nửa TRÊN. ⇒ ''tô nửa CHỨA (1;0)'' = ''tô nửa DƯỚI'' · ''tô nửa KHÔNG CHỨA (0;1)'' = ''tô nửa KHÔNG phải nửa TRÊN'' = ''tô nửa DƯỚI'' ⇒ TRÙNG KHỚP HOÀN TOÀN ✓' WHERE id = '3caef866-cbb7-4e79-a228-2d19a5ea4c49';
UPDATE questions SET noi_dung = 'Cho bất phương trình 3x + 2y ≤ 12. Đếm số cặp LÀ NGHIỆM trong: (0;0) · (2;3) · (4;1) · (1;5) · (3;2)' WHERE id = '3d36f9eb-9d30-452c-9906-fb192d9ab839';
UPDATE questions SET distractors = '[{"phuong_an":"Vì điểm ngoài đường tròn thì công thức vectơ pháp tuyến không dùng được","quan_niem_sai":"Đúng một phần nhưng không nói được lí do có 2 nghiệm"},{"phuong_an":"Vì từ điểm ngoài luôn kẻ được vô số tiếp tuyến","quan_niem_sai":"Sai: chỉ kẻ được đúng HAI tiếp tuyến"},{"phuong_an":"Vì tiếp tuyến qua điểm ngoài không vuông góc với bán kính","quan_niem_sai":"Sai: MỌI tiếp tuyến đều vuông góc bán kính tại tiếp điểm"}]'::jsonb, loi_giai = 'Khi M₀ nằm TRÊN (C): tiếp điểm chính là M₀ ⇒ vectơ pháp tuyến = IM₀ tính được ngay ⇒ phương trình xác định DUY NHẤT. Khi P nằm NGOÀI (C): P không phải tiếp điểm, ta chưa biết tiếp điểm ở đâu. Phải đặt tiếp tuyến dạng tổng quát qua P rồi áp điều kiện d(I, Δ) = R, dẫn tới phương trình bậc hai ⇒ thường có HAI nghiệm. Hình học: từ một điểm ngoài đường tròn kẻ được đúng HAI tiếp tuyến (đối xứng qua đường thẳng IP). Nếu P nằm TRONG (C) thì không kẻ được tiếp tuyến nào.' WHERE id = '3dd51c29-9827-489e-9b84-45ec4fb78063';
UPDATE questions SET noi_dung = 'Bé Na hỏi: ''Cô ơi, sao giải bất phương trình −2x ≥ 6 lại ra x ≤ −3 ạ? Em chia cho −2 thì phải ra x ≥ −3 chứ, sao dấu tự nhiên đổi chiều thế ạ?''' WHERE id = '3df82f5d-cd4c-4d23-966d-36a746dc6921';
UPDATE questions SET loi_giai = 'phương trình tổng quát x - 3 = 0 có A = 1, B = 0. Công thức k = -A/B đòi hỏi B ≠ 0 để chia được. Về hình học: đường thẳng đứng tạo góc 90° với Ox, mà tan 90° không xác định ⇒ không có hệ số góc. Đây là lí do trong SGK, dạng y = kx + m không mô tả được đường thẳng đứng, còn phương trình tổng quát thì mô tả được mọi đường thẳng.' WHERE id = '3f3b597d-9d9e-4bad-a4e6-fbeac1e45a9a';
UPDATE questions SET noi_dung = 'Viết phương trình tổng quát đường thẳng đi qua N(-2; 5) và song song với trục Oy.' WHERE id = '3f5e3f16-0efb-4b4a-8248-a88846f37dae';
UPDATE questions SET noi_dung = '(a) VÌ SAO hàm F = ax + by đạt max/min tại các ĐỈNH (mà không phải điểm giữa miền)? Giải thích trực quan. (b) Cho miền = TAM GIÁC O(0;0), (4;0), (0;4) và F = x + y. Tìm giá trị lớn nhất. Có gì ĐẶC BIỆT? (c) Nếu miền nghiệm KHÔNG BỊ CHẶN (vô hạn), có chắc tìm được giá trị lớn nhất không? Cho ví dụ.', dap_an = '(a) Ý tưởng ''ĐƯỜNG MỨC'': xét F = ax + by = k (k là hằng số) ⇒ đây là MỘT ĐƯỜNG THẲNG! Đổi k ⇒ ta được HỌ các đường thẳng SONG SONG (cùng hệ số góc!). TRỰC QUAN: tưởng tượng ta TRƯỢT đường thẳng F = k (giữ nguyên hướng) qua miền nghiệm — trượt về phía này thì k TĂNG, phía kia thì k GIẢM ⇒ đường mức trượt đến đâu thì ''chạm'' miền ở đó. Điểm CUỐI CÙNG mà đường mức còn chạm miền — chính là ĐỈNH! ✓ (Vì đa giác LỒI — khi trượt ra xa, đường mức ''rời'' miền tại một GÓC!) ẨN DỤ ''MẶT TRỜI LẶN'': miền nghiệm là hòn đảo. Ánh nắng chiếu XIÊN (theo hướng đường mức). Khi mặt trời LẶN DẦN, chỗ CUỐI CÙNG còn nắng chính là MỎM ĐÁ NHÔ RA XA NHẤT — đó là ĐỈNH! ⇒ Không cần thử vô số điểm — chỉ cần thử các ĐỈNH! (b) F(0;0) = 0 | F(4;0) = 4 ⬅️ | F(0;4) = 4 ⬅️ ⇒ giá trị lớn nhất = 4, đạt tại CẢ HAI đỉnh (4;0) VÀ (0;4)! ĐIỀU ĐẶC BIỆT: giá trị lớn nhất đạt tại HAI đỉnh ⇒ giá trị lớn nhất đạt tại MỌI ĐIỂM TRÊN CẠNH nối chúng! KIỂM CHỨNG: (2;2) (trung điểm cạnh): F = 2 + 2 = 4 ✓ BẰNG giá trị lớn nhất! | (1;3) (cũng trên cạnh): F = 1 + 3 = 4 ✓ CŨNG BẰNG 4! ⇒ MỌI điểm trên cạnh x+y = 4 đều cho F = 4! VÌ SAO? Vì cạnh đó nằm TRÊN đường thẳng x + y = 4 — CHÍNH LÀ đường mức của F! (hàm F = x+y và bờ x+y = 4 TRÙNG NHAU!) ⇒ Khi đường mức TRÙNG với một CẠNH ⇒ VÔ SỐ điểm tối ưu! (c) KHÔNG CHẮC! Miền vô hạn CÓ THỂ KHÔNG CÓ giá trị lớn nhất! VÍ DỤ: hệ ⎧ x ≥ 0 · ⎩ y ≥ 0 (chỉ 2 bất phương trình — miền = góc phần tư thứ nhất, VÔ HẠN!). Hàm F = x + y: F(1;1) = 2 | F(10;10) = 20 | F(100;100) = 200 | F(1000;1000) = 2000 | … → +∞ ⇒ F TĂNG VÔ HẠN ⇒ KHÔNG CÓ giá trị lớn nhất! (Nhưng CÓ giá trị nhỏ nhất = 0 tại O(0;0) ✓ — vì miền bị chặn phía dưới!)', loi_giai = 'BẢNG TỔNG HỢP: miền ĐA GIÁC (hữu hạn) → CÓ giá trị lớn nhất ✓ (tại đỉnh), CÓ giá trị nhỏ nhất ✓ | miền VÔ HẠN → CÓ THỂ KHÔNG có giá trị lớn nhất!, giá trị nhỏ nhất tuỳ hướng chặn | miền RỖNG → KHÔNG có gì cả! ✗ ĐÂY LÀ LÍ DO x ≥ 0, y ≥ 0 VÀ CÁC RÀNG BUỘC KHÁC SỐNG CÒN — chúng làm miền HỮU HẠN ⇒ ĐẢM BẢO CÓ max/min! ✓ (A06, B02!) Rubric: Chưa đạt (không giải thích được (a), chỉ nói ''vì định lí'') | Cần cố gắng (giải thích (a),(b) nhưng không trả lời được (c), hoặc nghĩ ''miền nào cũng có max'') | Đạt (đủ 3 phần, ở (b) nhận ra giá trị lớn nhất tại 2 đỉnh, ở (c) cho ví dụ miền vô hạn) | Tốt (đủ ý trên VÀ ở (a) giải thích bằng ĐƯỜNG MỨC (họ đường song song trượt qua miền) VÀ ở (b) chỉ ra VÔ SỐ điểm tối ưu trên cạnh (vì đường mức TRÙNG với bờ!) VÀ ở (c) rút ra bảng tổng hợp + liên hệ vai trò của x,y ≥ 0). Câu này CHỐT LẠI toàn bộ mạch chương II: x,y ≥ 0 (A06) → miền HỮU HẠN (B02) → CÓ ĐỈNH (B05) → CÓ max/min (B03)!' WHERE id = '3fc8ad42-2a29-42d6-8b47-0ea46ba964c4';
UPDATE questions SET noi_dung = 'Tính \(\dfrac{\sqrt{7}+2}{\sqrt{7}-2}\) bằng máy tính cầm tay (giữ 4 chữ số thập phân ở bước trung gian), sau đó quy tròn kết quả cuối cùng đến hàng phần chục. (Hỏi kèm độ tự tin 1–3)' WHERE id = '3fd56704-2c20-451c-b7d2-317e0b47457c';
UPDATE questions SET noi_dung = 'Biết Q1=12, Q3=28. Tính khoảng tứ phân vị. (Hỏi kèm độ tự tin 1–3)', distractors = '[{"phuong_an":"40 (cộng Q1 và Q3 thay vì trừ)","quan_niem_sai":"Thực hiện phép CỘNG (28+12=40) thay vì đúng phải là phép TRỪ."},{"phuong_an":"20 (tính TRUNG BÌNH CỘNG của Q1 và Q3 thay vì HIỆU của chúng)","quan_niem_sai":"NHẦM LẪN giữa YÊU CẦU ''tính khoảng tứ phân vị'' (HIỆU của Q3 và Q1) với ''TÍNH TRUNG BÌNH CỘNG'' của HAI giá trị, một PHÉP TÍNH KHÁC KHÔNG PHÙ HỢP."},{"phuong_an":"28 (chỉ lấy Q3, quên trừ Q1)","quan_niem_sai":"Chỉ LẤY GIÁ TRỊ Q3 (28) mà QUÊN TRỪ đi Q1 (12) để có khoảng tứ phân vị."}]'::jsonb, loi_giai = 'khoảng tứ phân vị=Q3−Q1=28−12=16.' WHERE id = '4071616d-e3af-417e-a09c-74069b833e37';
UPDATE questions SET noi_dung = 'Cho bất phương trình mx + 2y ≤ 10. Tìm giá trị LỚN NHẤT của m nguyên để cặp (3; 2) là nghiệm.' WHERE id = '40d1dede-dc7b-4607-b693-264cb13800f2';
UPDATE questions SET noi_dung = 'Bé Na hỏi: ''Cô ơi, em thử điểm O(0;0) vào bất phương trình rồi, ra kết quả SAI. Vậy em phải tô nửa nào ạ? Em quên mất rồi!''', dap_an = 'SUY LUẬN, không học thuộc! Hỏi: điểm O thử ra SAI nghĩa là gì? ⇒ O KHÔNG phải nghiệm! Hỏi tiếp: miền nghiệm chứa những điểm LÀ nghiệm. Vậy O có nằm trong miền không? ⇒ KHÔNG! ⇒ KẾT LUẬN: miền nghiệm ở PHÍA BÊN KIA — nửa mp KHÔNG CHỨA O ✓. QUY TẮC: ra ĐÚNG ✓ → tô nửa CHỨA điểm thử · ra SAI ✗ → tô nửa KHÔNG CHỨA. Nhớ: ''ĐÚNG thì Ở LẠI, SAI thì SANG BÊN KIA!'' ẨN DỤ CỔNG TRƯỜNG: bờ là cổng, bé đứng ở O. Bác bảo vệ hỏi ''có thẻ không?'' (= thay vào bất phương trình). CÓ ✓ → bé ĐANG Ở TRONG khu vực đúng → tô chỗ bé đứng! KHÔNG ✗ → bé đang ở NGOÀI → khu vực đúng ở BÊN KIA cổng!', loi_giai = 'THỬ NGAY: bất phương trình x + y ≥ 3, thử O: 0 + 0 = 0. Hỏi 0 ≥ 3? SAI ✗ ⇒ tô nửa KHÔNG CHỨA O ✓. KIỂM LẠI: lấy (5;0) ở nửa bên kia: 5 ≥ 3 ✓ ĐÚNG! ⇒ xác nhận ✓. CẢNH BÁO: trước khi thử O phải KIỂM ''O có nằm TRÊN BỜ không?'' — thay O vào phương trình bờ: ra 0 = c ⇒ nếu c = 0 thì O NẰM TRÊN BỜ ⇒ KHÔNG DÙNG ĐƯỢC! Lúc đó chọn (1;0) hoặc (0;1) ✓. Rubric: Chưa đạt (học thuộc quy tắc) | Cần cố gắng (nêu đúng quy tắc, có giải thích nhưng không ví dụ) | Đạt (giải thích bằng SUY LUẬN, có ẩn dụ và ví dụ số) | Tốt (đủ ý trên VÀ dạy cách KIỂM CHỨNG bằng điểm thứ hai VÀ CẢNH BÁO trường hợp O nằm trên bờ (c = 0) — HS không cảnh báo bẫy này là CHƯA ĐẠT vì đó là node A05 sắp tới!).' WHERE id = '4110d3cd-63dc-4e91-aec9-f4ce0d3ac8d4';
UPDATE questions SET noi_dung = 'ĐỈNH của miền nghiệm hệ bất phương trình là: A. Giao điểm của bất kỳ hai bờ nào B. Giao điểm của hai bờ, VÀ điểm đó phải THUỘC miền nghiệm C. Điểm bất kỳ trên bờ D. Gốc toạ độ O(0; 0)', loi_giai = 'Đỉnh phải thoả CẢ HAI điều kiện: ① là giao điểm của 2 bờ (nằm ở ''góc'') ② THUỘC miền nghiệm (thoả TẤT CẢ bất phương trình!)' WHERE id = '41b170e2-ddc3-4f3d-8c72-fcc837ea6c29';
UPDATE questions SET noi_dung = 'Cho tam giác ABC: A(1; 2), B(5; 2), C(3; 6). Viết phương trình tổng quát đường trung tuyến kẻ từ A.', distractors = '[{"phuong_an":"2x - 3y - 4 = 0","quan_niem_sai":"Sai dấu hệ số tự do khi khai triển"},{"phuong_an":"3x + 2y - 7 = 0","quan_niem_sai":"Lấy vectơ chỉ phương (3;2) làm vectơ pháp tuyến"},{"phuong_an":"Trung tuyến qua trung điểm AB thay vì BC","quan_niem_sai":"Nhầm trung tuyến từ A phải đi qua trung điểm cạnh ĐỐI DIỆN (BC)"}]'::jsonb, loi_giai = 'Trung điểm M của BC: M = ((5+3)/2 ; (2+6)/2) = (4; 4). vectơ chỉ phương AM = (3; 2) ⇒ vectơ pháp tuyến n = (2; -3). phương trình tổng quát: 2(x-1) - 3(y-2) = 0 ⇔ 2x - 3y + 4 = 0. Kiểm tra A(1;2): 2 - 6 + 4 = 0 ✓; M(4;4): 8 - 12 + 4 = 0 ✓.' WHERE id = '41f40224-6e7b-4d05-b3b9-44b91293272d';
UPDATE questions SET loi_giai = 'Cộng hai phương trình: 3x - 6 = 0 ⇒ x = 2. Thay vào d₂: 2 + y - 5 = 0 ⇒ y = 3. Kiểm tra d₁: 4 - 3 - 1 = 0 ✓.' WHERE id = '421402ca-f843-4a94-8fd0-e198231c84ee';
UPDATE questions SET noi_dung = '(a) khoảng tứ phân vị đo ĐỘ PHÂN TÁN của ''50% dữ liệu Ở GIỮA'' (từ Q1 đến Q3). (b) khoảng tứ phân vị ÍT BỊ ẢNH HƯỞNG bởi các giá trị NGOẠI LỆ hơn KHOẢNG BIẾN THIÊN R. (c) khoảng tứ phân vị LUÔN KHÔNG ÂM (vì Q3≥Q1). (d) khoảng tứ phân vị LUÔN LỚN HƠN R.', distractors = '[{"phuong_an":"(d) Đúng","quan_niem_sai":"Hiểu SAI MỐI QUAN HỆ giữa khoảng tứ phân vị và R; vì khoảng tứ phân vị chỉ đo MỘT PHẦN dữ liệu (50% Ở GIỮA) trong khi R đo TOÀN BỘ PHẠM VI, khoảng tứ phân vị THƯỜNG NHỎ HƠN (hoặc BẰNG) R, KHÔNG PHẢI LUÔN LỚN HƠN."}]'::jsonb, loi_giai = 'khoảng tứ phân vị (chỉ đo ''50% dữ liệu Ở GIỮA'') THƯỜNG NHỎ HƠN R (đo TOÀN BỘ phạm VI, từ giá trị NHỎ NHẤT đến LỚN NHẤT), KHÔNG PHẢI LUÔN LỚN HƠN.' WHERE id = '42f5b254-4ebd-4e97-962e-4cc0708fa581';
UPDATE questions SET noi_dung = 'Tìm điều kiện của m để x² + y² - 2(m+1)x + 4y + 8 = 0 là phương trình đường tròn.' WHERE id = '4316089e-d4f3-4769-82d9-74063421bdf4';
UPDATE questions SET noi_dung = 'Tổng kết: giải thích MỐI LIÊN HỆ giữa CÁC THƯỚC ĐO ĐỘ PHÂN TÁN đã HỌC (R, khoảng tứ phân vị, PHƯƠNG SAI/ĐỘ LỆCH CHUẨN, hệ số biến thiên) — MỖI thước ĐO PHÙ HỢP với NGỮ CẢNH NÀO, và TẠI SAO KHÔNG CÓ ''MỘT THƯỚC ĐO DUY NHẤT'' PHÙ HỢP cho MỌI TÌNH HUỐNG. (Hỏi kèm độ tự tin 1–3)', dap_an = 'MỖI thước ĐO ĐỘ PHÂN TÁN có ƯU/NHƯỢC ĐIỂM RIÊNG, PHÙ HỢP với NGỮ CẢNH KHÁC NHAU: R (khoảng BIẾN THIÊN) ĐƠN GIẢN, NHANH, nhưng CHỈ dựa vào HAI điểm CỰC TRỊ (dễ bị NGOẠI LỆ chi PHỐI) — PHÙ HỢP cho ''KIỂM TRA NHANH'' (như KIỂM SOÁT CHẤT LƯỢNG SẢN XUẤT); (khoảng TỨ PHÂN VỊ) ''BỀN VỮNG'' hơn với NGOẠI LỆ (dựa vào Q1, Q3), và LÀ NỀN TẢNG cho QUY TẮC PHÁT HIỆN BẤT THƯỜNG (1,5×khoảng tứ phân vị) — PHÙ HỢP khi CẦN THƯỚC ĐO ÍT BỊ ẢNH HƯỞNG bởi NGOẠI LỆ; PHƯƠNG SAI/ĐỘ LỆCH CHUẨN sử DỤNG TOÀN BỘ dữ liệu (thông TIN ĐẦY ĐỦ NHẤT), CÓ NHIỀU ỨNG DỤNG TOÁN HỌC/THỐNG KÊ SÂU HƠN (như trong TÀI CHÍNH, KHOA HỌC), nhưng NHẠY CẢM với NGOẠI LỆ (do PHÉP BÌNH PHƯƠNG); (hệ SỐ BIẾN THIÊN) CHUẨN HOÁ ĐỘ LỆCH CHUẨN theo TRUNG BÌNH, PHÙ HỢP khi CẦN so SÁNH ĐỘ PHÂN TÁN giữa CÁC đại LƯỢNG có ĐƠN VỊ/QUY MÔ KHÁC NHAU; KHÔNG CÓ ''MỘT thước ĐO DUY NHẤT'' PHÙ HỢP cho MỌI TÌNH HUỐNG vì MỖI THƯỚC ĐO được XÂY DỰNG với MỤC ĐÍCH và GIẢ ĐỊNH KHÁC NHAU — VIỆC LỰA CHỌN CẦN dựa TRÊN: (1) ĐẶC ĐIỂM dữ liệu (có NGOẠI LỆ hay không); (2) MỤC ĐÍCH so SÁNH (cùng đơn vị/QUY MÔ hay KHÔNG); (3) MỨC ĐỘ CHI TIẾT CẦN THIẾT.' WHERE id = '4684fdba-4c17-4120-b815-29ad878767c7';
UPDATE questions SET noi_dung = 'Bài làm: ''Đưa bất phương trình −2x + 4y ≥ 6 về dạng đơn giản. Tôi CHIA CẢ HAI VẾ CHO −2: x − 2y ≥ −3.'' Tìm và sửa lỗi.', dap_an = 'LỖI: chia cho số ÂM mà KHÔNG ĐỔI CHIỀU bất phương trình! Quy tắc: nhân/chia cả hai vế cho số ÂM ⇒ PHẢI ĐỔI CHIỀU. Sửa: −2x + 4y ≥ 6, chia cho −2 ⇒ x − 2y ≤ −3 ✓ (dấu ≥ ĐỔI THÀNH ≤).', loi_giai = 'KIỂM BẰNG CẶP SỐ: thử (0; 2). Vào bất phương trình gốc: −2(0) + 4(2) = 8 ≥ 6 ✓ ĐÚNG → là nghiệm. Vào bài làm SAI: 0 − 2(2) = −4 ≥ −3? SAI! ✗ (mâu thuẫn!). Vào bài sửa ĐÚNG: −4 ≤ −3 ✓ ĐÚNG ✓. ⇒ Bài gốc LOẠI MẤT NGHIỆM HỢP LỆ! GỐC BỆNH: quen thao tác với PHƯƠNG TRÌNH (chia số âm không đổi gì) rồi áp máy móc sang bất phương trình. Rubric: Chưa đạt | Đạt (sửa thành x − 2y ≤ −3, chỉ ra phải đổi chiều) | Tốt (sửa đúng VÀ dùng cặp số kiểm chứng VÀ nêu bảng so sánh phương trình vs bất phương trình).' WHERE id = '470aa675-315d-4098-a88f-f23ddd882dad';
UPDATE questions SET noi_dung = 'Hypebol có tiêu cự 10 và đi qua điểm M(3; 0). Viết phương trình chính tắc.', loi_giai = 'M(3; 0) là đỉnh ⇒ a = 3, a² = 9. Tiêu cự 2c = 10 ⇒ c = 5. b² = c² - a² = 25 - 9 = 16. phương trình: x²/9 - y²/16 = 1.' WHERE id = '477e34af-0917-4ac1-ab95-fec195e14d09';
UPDATE questions SET noi_dung = 'Cho hai đường thẳng song song d₁: x + y - 1 = 0 và d₂: x + y - 5 = 0. Tính khoảng cách giữa chúng, rồi tìm phương trình đường thẳng song song và CÁCH ĐỀU d₁, d₂.' WHERE id = '490982d5-fcfb-4fe8-9011-63cf14db026d';
UPDATE questions SET noi_dung = 'Chuyển chính tắc (x - 1)/2 = (y - 3)/(-1) sang phương trình tổng quát.', distractors = '[{"phuong_an":"x + 2y + 7 = 0","quan_niem_sai":"Sai dấu hệ số tự do khi nhân chéo"},{"phuong_an":"2x - y + 1 = 0","quan_niem_sai":"Lấy vectơ chỉ phương (2;-1) làm vectơ pháp tuyến"},{"phuong_an":"x - 2y + 5 = 0","quan_niem_sai":"Nhân chéo sai dấu ở vế phải"}]'::jsonb WHERE id = '49e0c7ac-9839-41e7-9638-8f2b9e93bc95';
UPDATE questions SET noi_dung = 'Một bạn nói: ''MỌI giá trị LỚN HƠN SỐ TRUNG BÌNH RẤT NHIỀU đều LÀ giá trị BẤT THƯỜNG, KHÔNG CẦN dùng đến khoảng tứ phân vị.'' Chỉ ra lỗi. (Hỏi kèm độ tự tin 1–3)', dap_an = 'Sai. KHÁI NIỆM ''RẤT NHIỀU'' (so với TRUNG BÌNH) là MỘT NHẬN ĐỊNH MƠ HỒ, KHÔNG CÓ TIÊU CHÍ ĐỊNH LƯỢNG RÕ RÀNG; QUY TẮC khoảng tứ phân vị (1,5×khoảng tứ phân vị) cung CẤP một TIÊU CHÍ KHÁCH QUAN, DỰA TRÊN ''SỰ PHÂN BỐ THỰC TẾ'' của dữ liệu (thông QUA Q1, Q3), KHÔNG PHỤ THUỘC vào CẢM TÍNH chủ QUAN của người PHÂN TÍCH; NGOÀI RA, SỐ TRUNG BÌNH BẢN THÂN NÓ có THỂ BỊ ''BÓP MÉO'' bởi CHÍNH các giá trị NGOẠI LỆ (như đã HỌC), nên DÙNG TRUNG BÌNH LÀM ''MỐC SO SÁNH'' để PHÁT HIỆN NGOẠI LỆ có THỂ dẫn đến MỘT VÒNG LUẨN QUẨN (dùng một THƯỚC ĐO ĐÃ BỊ ''NHIỄM'' bởi NGOẠI LỆ để PHÁT HIỆN CHÍNH NGOẠI LỆ đó); QUY TẮC khoảng tứ phân vị (dựa trên Q1, Q3 — CÁC THƯỚC ĐO ''BỀN VỮNG'' hơn) là một PHƯƠNG PHÁP KHÁCH QUAN và ĐÁNG TIN CẬY HƠN.' WHERE id = '4a01fd7a-eed3-45dd-8a5c-597a2cf9fa09';
UPDATE questions SET noi_dung = 'phương trình chính tắc của hypebol có dạng:' WHERE id = '4a643a78-d21b-4e2c-a989-191cd742b1c3';
UPDATE questions SET noi_dung = 'Xét tính đúng/sai: Tích vô hướng của một vectơ pháp tuyến và một vectơ chỉ phương của cùng một đường thẳng luôn bằng 0.', loi_giai = 'Vì vectơ pháp tuyến vuông góc với đường thẳng, còn vectơ chỉ phương cùng phương với đường thẳng, nên hai vectơ vuông góc ⇒ tích vô hướng bằng 0.' WHERE id = '4c4731ef-2bd5-4380-8092-b023c59cd60e';
UPDATE questions SET noi_dung = 'Cho đường thẳng d: x + y - 2 = 0 và điểm I(0; 0). Viết phương trình đường tròn tâm I tiếp xúc d, rồi tìm toạ độ tiếp điểm.', loi_giai = 'R = d(O, d) = |0 + 0 - 2|/√(1+1) = 2/√2 = √2 ⇒ R² = 2. phương trình: x² + y² = 2. Tiếp điểm là hình chiếu của O trên d: đường qua O vuông góc d nhận vectơ chỉ phương của d là (1;-1) làm vectơ pháp tuyến ⇒ phương trình: x - y = 0. Giao với d: x + y = 2 và x = y ⇒ x = y = 1 ⇒ M(1; 1). Kiểm M thuộc (C): 1 + 1 = 2 ✓; thuộc d: 1 + 1 - 2 = 0 ✓.' WHERE id = '4cf27705-cd56-484a-a485-d274045fb689';
UPDATE questions SET noi_dung = 'Viết phương trình tổng quát đường thẳng song song với d: 3x + 4y - 5 = 0 và cách d một khoảng bằng 2.', distractors = '[{"phuong_an":"Chỉ 3x + 4y + 5 = 0","quan_niem_sai":"Bỏ một nghiệm của phương trình trị tuyệt đối"},{"phuong_an":"3x + 4y + 10 = 0 hoặc 3x + 4y - 20 = 0","quan_niem_sai":"Quên chia cho 5 khi lập phương trình |C+5| = 2"},{"phuong_an":"4x - 3y + C = 0","quan_niem_sai":"Dùng vectơ pháp tuyến vuông góc ⇒ ra đường vuông góc, không song song"}]'::jsonb WHERE id = '4cfe4a53-f5eb-4b20-a0be-40f9d4f0ad84';
UPDATE questions SET noi_dung = 'Bài làm: ''Quán bán x ly trà sữa (35.000 đ/ly) và y ly cà phê (28.000 đ/ly). Khách mang theo 200 nghìn đồng. Lập bất phương trình. Tôi đặt: x = số ly trà sữa, y = số ly cà phê. Tiền trà sữa = 28x. Tiền cà phê = 35y. Vậy bất phương trình là: 28x + 35y ≤ 200'' Tìm và sửa lỗi.', dap_an = 'HAI LỖI! LỖI 1 — GHÉP NHẦM HỆ SỐ: đề ghi rõ trà sữa 35.000 đ/ly, cà phê 28.000 đ/ly. Nhưng bạn ấy viết NGƯỢC: tiền trà sữa = 28x (phải là 35x!) · tiền cà phê = 35y (phải là 28y!). LỖI 2 (CÒN NẶNG HƠN!) — NHẦM ĐƠN VỊ: đơn giá ghi bằng ĐỒNG (35.000 đ, 28.000 đ) nhưng vế phải lại ghi 200 (là 200 NGHÌN = 200.000 đ!) ⇒ TRỘN HAI ĐƠN VỊ trong cùng một bất phương trình! CÁCH SỬA — hai lựa chọn (đều đúng, miễn NHẤT QUÁN): Cách 1 (nghìn đồng, khuyến nghị): 35x + 28y ≤ 200 ✓ | Cách 2 (đồng): 35000x + 28000y ≤ 200000 ✓', loi_giai = 'KIỂM CHỨNG — hai cách CÙNG kết quả: thử (3;3) [3 ly trà sữa, 3 ly cà phê]. Cách 1: 35(3) + 28(3) = 105 + 84 = 189 ≤ 200 ✓ ĐỦ TIỀN! Cách 2: 105.000 + 84.000 = 189.000 ≤ 200.000 ✓ ĐỦ! ⇒ CÙNG KẾT LUẬN ✓. QUY TẮC VÀNG VỀ ĐƠN VỊ: ''MỌI SỐ trong cùng một bất phương trình phải CÙNG MỘT ĐƠN VỊ!'' Trước khi lập bất phương trình, CHỌN đơn vị (nghìn hay đồng?) rồi QUY ĐỔI HẾT về đơn vị đó! Đây là lỗi CHẾT NGƯỜI trong bài toán thực tế — kết quả có thể sai lệch 1000 lần! Rubric: Chưa đạt (chỉ tìm được 1 lỗi) | Cần cố gắng (tìm được lỗi ghép hệ số nhưng BỎ SÓT lỗi đơn vị) | Đạt (chỉ ra CẢ HAI lỗi, sửa đúng bất phương trình) | Tốt (đủ ý trên VÀ đưa CẢ HAI cách sửa (nghìn/đồng), kiểm chứng chúng cho cùng kết quả, VÀ phát biểu quy tắc vàng về đơn vị). CÂU QUAN TRỌNG NHẤT NODE — lỗi ĐƠN VỊ ít được dạy nhất nhưng hay gặp nhất và hậu quả nghiêm trọng nhất!' WHERE id = '4eae35e3-fd70-4a75-905d-49ef1f77da37';
UPDATE questions SET noi_dung = 'Điền: Đường thẳng qua M(x₀; y₀) có vectơ pháp tuyến n = (A; B) có phương trình tổng quát là ______ = 0.', distractors = '[{"phuong_an":"A(x + x₀) + B(y + y₀)","quan_niem_sai":"Nhầm dấu: phương trình tổng quát dùng (x − x₀), không phải (x + x₀)."},{"phuong_an":"A(x₀ - x) + B(y₀ - y)","quan_niem_sai":"Đảo chiều hiệu — đổi dấu cả vế, không còn dạng chuẩn."},{"phuong_an":"B(x - x₀) + A(y - y₀)","quan_niem_sai":"Hoán vị nhầm A với B: hệ số phải khớp đúng toạ độ vectơ pháp tuyến."}]'::jsonb WHERE id = '4fc06895-8d5d-4eaa-b2d8-1de4fc00aec4';
UPDATE questions SET noi_dung = 'Kiểm tra cặp (2; 1) có là nghiệm của hệ: ⎧ 3x + 2y ≤ 10 · ⎨ x − y ≥ 0 · ⎩ y ≥ 0. B1 — Kiểm bất phương trình ①. B2 — Kiểm ② (ĐỪNG DỪNG Ở B1!). B3 — Kiểm bất phương trình ③ và KẾT LUẬN.', dap_an = 'B1: 3(2) + 2(1) = 6 + 2 = 8. Hỏi 8 ≤ 10? ĐÚNG ✓ | B2: 2 − 1 = 1. Hỏi 1 ≥ 0? ĐÚNG ✓ | B3: y = 1 ≥ 0? ĐÚNG ✓ ⇒ Thoả CẢ BA bất phương trình ⇒ (2;1) LÀ NGHIỆM CỦA HỆ ✓', distractors = '[{"phuong_an":"B1 đảo x,y","quan_niem_sai":"3(1) + 2(2) = 7 — bệnh A02-①"},{"phuong_an":"Bỏ B2, B3 (dừng sau B1)","quan_niem_sai":"KIỂM THIẾU bất phương trình! Thấy ① đúng là kết luận luôn"},{"phuong_an":"B3 quên kiểm y ≥ 0","quan_niem_sai":"Coi điều kiện ẩn là ''thừa'' (bệnh A06)"}]'::jsonb, loi_giai = 'QUY TẮC DỪNG BẤT ĐỐI XỨNG: một bất phương trình ra SAI ✗ ⇒ ĐƯỢC DỪNG NGAY (chắc chắn không là nghiệm hệ)! Một bất phương trình ra ĐÚNG ✓ ⇒ KHÔNG được dừng, phải kiểm HẾT! Logic: để BÁC BỎ chỉ cần 1 phản ví dụ; để KHẲNG ĐỊNH phải kiểm TẤT CẢ. (Đúng tinh thần A09/B05 Chương I!) AI Tutor hỏi: ''Em kiểm mấy bất phương trình rồi? Hệ có mấy bất phương trình?''' WHERE id = '5029670c-24e8-4123-9320-08c50cdfed4f';
UPDATE questions SET noi_dung = 'Khi xác định miền nghiệm của bất phương trình ax + by ≤ c (với c ≠ 0), điểm thử ƯU TIÊN nên chọn là: A. Gốc toạ độ O(0; 0) (vì thay vào tính rất nhanh) B. Một điểm bất kì TRÊN đường thẳng bờ C. Điểm (1; 1) D. Giao điểm của bờ với trục Ox' WHERE id = '50483fa9-ec26-42ce-b678-6f99c49a68e6';
UPDATE questions SET noi_dung = 'Cho bất phương trình 3x ≥ 6 (coi là bậc nhất hai ẩn với b = 0). Đường thẳng bờ cắt trục Ox tại điểm có HOÀNH ĐỘ bằng bao nhiêu?', loi_giai = 'B1: bờ 3x = 6 ⇒ x = 2. B2: phương trình x = 2 (không có y!) ⇒ ĐƯỜNG THẲNG DỌC, song song trục Oy, gồm mọi điểm có hoành độ 2: (2;0), (2;1), (2;−3)… B3: trục Ox có y = 0 ⇒ giao điểm (2; 0) ⇒ hoành độ = 2 ✓. B4: dấu ≥ ⇒ NÉT LIỀN. BẪY TINH VI: bất phương trình 2y < 8 ⇒ bờ y = 4 — đường NGANG ⇒ KHÔNG BAO GIỜ cắt trục Ox (song song với Ox)!' WHERE id = '50939a55-86c8-437f-b9be-0f4b891b3fdb';
UPDATE questions SET noi_dung = 'Bé Na hỏi: ''Cô ơi, cho em cặp (2; 5) với bất phương trình 5x + 2y ≤ 20 — em cứ không biết thay số nào vào đâu! Có cách nào chắc chắn không nhầm không ạ?''' WHERE id = '50c949b8-913d-4375-a6bf-6b5288ecdaac';
UPDATE questions SET noi_dung = 'Miền nghiệm của HỆ bất phương trình là: A. Hợp (gộp tất cả) các miền nghiệm của từng bất phương trình B. Phần GIAO (phần CHUNG) của các miền nghiệm từng bất phương trình C. Miền nghiệm của bất phương trình đầu tiên D. Toàn bộ mặt phẳng', distractors = '[{"phuong_an":"A","quan_niem_sai":"LẤY HỢP! (MIS-C02-GH-01) Tái phát MIS-D01-D02-01 Chương I!"},{"phuong_an":"C","quan_niem_sai":"Bệnh B01-② — kiểm thiếu bất phương trình (chỉ xét bất phương trình đầu)"},{"phuong_an":"D","quan_niem_sai":"Không hiểu khái niệm miền nghiệm"}]'::jsonb, loi_giai = 'Nghiệm hệ phải thoả TẤT CẢ bất phương trình ⇒ điểm đó phải nằm trong MỌI miền ⇒ phần CHUNG!' WHERE id = '5160a55a-43fd-4355-933c-1404efd40f31';
UPDATE questions SET noi_dung = 'Giải thích vì sao khoảng tứ phân vị được coi là THƯỚC ĐO ĐỘ PHÂN TÁN ''BỀN VỮNG'' (ROBUST) hơn KHOẢNG BIẾN THIÊN R, liên hệ với việc khoảng tứ phân vị CHỈ dựa VÀO Q1, Q3 (thay VÌ GIÁ TRỊ CỰC TRỊ). (Hỏi kèm độ tự tin 1–3)', dap_an = 'KHOẢNG BIẾN THIÊN R dựa HOÀN TOÀN VÀO HAI giá TRỊ CỰC TRỊ (LỚN NHẤT, NHỎ NHẤT) — NẾU có MỘT giá TRỊ NGOẠI LỆ CỰC ĐOAN (RẤT LỚN hoặc RẤT NHỎ), R sẽ THAY ĐỔI RẤT NHIỀU (bị ''BÓP MÉO'' HOÀN TOÀN); NGƯỢC LẠI, khoảng tứ phân vị dựa VÀO Q1 và Q3 — HAI giá TRỊ này KHÔNG PHẢI là giá TRỊ CỰC TRỊ, mà là ''NGƯỠNG'' PHÂN CHIA 25% và 75% dữ liệu; MỘT giá TRỊ NGOẠI LỆ (RẤT LỚN hoặc RẤT NHỎ) THƯỜNG CHỈ ẢNH HƯỞNG đến CÁC giá TRỊ Ở HAI ĐẦU CỰC (bên NGOÀI khoảng Q1-Q3), KHÔNG LÀM THAY ĐỔI ĐÁNG KỂ VỊ TRÍ của CHÍNH Q1 và Q3 (vì CHÚNG được XÁC ĐỊNH bởi VỊ TRÍ TRONG DÃY, KHÔNG PHẢI GIÁ TRỊ CỤ THỂ của các điểm CỰC TRỊ) — đây CHÍNH LÀ lý do khoảng tứ phân vị ''BỀN VỮNG'' (ÍT BỊ ẢNH HƯỞNG) hơn R KHI có SỰ HIỆN DIỆN của các giá TRỊ NGOẠI LỆ.', distractors = '[{"phuong_an":"Vì khoảng tứ phân vị luôn có giá trị NHỎ HƠN R nên tự động BỀN VỮNG hơn","quan_niem_sai":"misc_ly_do_khong_dung_ban_chat — đưa ra lý do KHÔNG CHÍNH XÁC (''khoảng tứ phân vị luôn NHỎ HƠN R'' KHÔNG PHẢI lý do cho TÍNH BỀN VỮNG), thay VÌ lý do ĐÚNG ĐẮN là khoảng tứ phân vị dựa VÀO ''VỊ TRÍ'' (Q1, Q3) thay VÌ ''GIÁ TRỊ CỰC TRỊ'' (như R), nên ÍT bị ẢNH HƯỞNG bởi NGOẠI LỆ."}]'::jsonb WHERE id = '556f2d6b-9e11-4445-926d-a708e5a43f5e';
UPDATE questions SET distractors = '[{"phuong_an":"Không, vì t tìm từ x và từ y khác nhau","quan_niem_sai":"Giải sai phương trình -1 = 1 - t (ra t = -2)"},{"phuong_an":"Có, ứng với t = -2","quan_niem_sai":"Sai dấu khi giải -1 = 1 - t"},{"phuong_an":"Không xác định được nếu chưa chuyển sang phương trình tổng quát","quan_niem_sai":"Không biết cách kiểm tra trực tiếp bằng tham số"}]'::jsonb WHERE id = '564de222-4a8b-4b62-8e8b-2ff47cc817d0';
UPDATE questions SET loi_giai = 'ĐỘ LỆCH CHUẨN/PHƯƠNG SAI SỬ DỤNG TOÀN BỘ dữ liệu (không CHỈ vài điểm CỰC TRỊ như R hay khoảng tứ phân vị), nên THƯỜNG được coi là THƯỚC ĐO ''ĐẦY ĐỦ'' và ĐÁNG TIN CẬY NHẤT khi CÓ THỂ TÍNH được.' WHERE id = '56b5f2d2-320b-4f73-92e0-250cdbcd8e2f';
UPDATE questions SET noi_dung = 'Cho hệ 4 bất phương trình: ⎧ x + y ≤ 4 · ⎨ 2x + y ≤ 6 · ⎩ x ≥ 0, y ≥ 0. Trong 6 giao điểm của các cặp bờ, có bao nhiêu giao điểm BỊ LOẠI (không phải đỉnh)?' WHERE id = '582c8c5a-a2f0-4f74-aa79-02872cec6dc4';
UPDATE questions SET noi_dung = 'Khi dùng máy tính cầm tay để tính toán với các số gần đúng (ví dụ tính \(\sqrt{2}+\pi\)), bước QUAN TRỌNG cuối cùng cần làm là gì?', distractors = '[{"phuong_an":"Ghi lại TOÀN BỘ các chữ số mà máy tính hiển thị","quan_niem_sai":"Đây KHÔNG phải bước ĐÚNG, vì việc GHI LẠI TOÀN BỘ chữ số có thể tạo ra ''GIẢ CHÍNH XÁC'', không PHẢN ÁNH ĐÚNG độ chính xác THỰC SỰ của bài toán."},{"phuong_an":"Chuyển kết quả sang dạng PHÂN SỐ để chính xác hơn","quan_niem_sai":"KHÔNG PHẢI luôn CẦN THIẾT hay PHÙ HỢP; với các số CHỨA CĂN THỨC hoặc SỐ VÔ TỈ như \\(\\sqrt{2}\\), \\(\\pi\\), việc chuyển sang PHÂN SỐ KHÔNG GIÚP CHÍNH XÁC HƠN (vì bản thân chúng KHÔNG PHẢI số HỮU TỈ)."},{"phuong_an":"Không cần làm gì thêm, máy tính cầm tay luôn cho kết quả CHÍNH XÁC TUYỆT ĐỐI","quan_niem_sai":"SAI: máy tính cầm tay chỉ tính với một SỐ CHỮ SỐ HỮU HẠN (dù NHIỀU), KHÔNG THỂ cho ra kết quả ''CHÍNH XÁC TUYỆT ĐỐI'' với các SỐ VÔ TỈ như \\(\\sqrt{2}\\), \\(\\pi\\)."}]'::jsonb WHERE id = '586b823a-0397-4e07-9859-9effc069c5f9';
UPDATE questions SET noi_dung = 'Một bạn hỏi: ''Nếu máy tính cầm tay hiện đại đã có ĐỘ CHÍNH XÁC RẤT CAO (nhiều chữ số), tại sao chúng ta VẪN CẦN học về SỐ GẦN ĐÚNG và SAI SỐ một cách CẨN THẬN, thay vì chỉ TIN TƯỞNG HOÀN TOÀN vào KẾT QUẢ của máy tính?'' Giải thích cho bạn. (Hỏi kèm độ tự tin 1–3)', dap_an = 'MẶC DÙ máy tính cầm tay hiện đại có ĐỘ CHÍNH XÁC NỘI BỘ RẤT CAO, việc HIỂU về SỐ GẦN ĐÚNG và SAI SỐ VẪN CỰC KỲ QUAN TRỌNG vì NHIỀU LÝ DO: (1) DỮ LIỆU ĐẦU VÀO của bài toán (từ ĐO ĐẠC THỰC TẾ) THƯỜNG CÓ ĐỘ CHÍNH XÁC HẠN CHẾ HƠN NHIỀU so với KHẢ NĂNG TÍNH TOÁN của máy tính — MÁY TÍNH KHÔNG THỂ ''TỰ TẠO RA'' ĐỘ CHÍNH XÁC mà DỮ LIỆU BAN ĐẦU KHÔNG CÓ (nếu ĐO một VẬT chỉ CHÍNH XÁC đến 2 CHỮ SỐ CÓ NGHĨA, thì KẾT QUẢ TÍNH TOÁN CUỐI CÙNG — dù máy tính cầm tay hiển thị 10 CHỮ SỐ — CŨNG CHỈ ''ĐÁNG TIN CẬY'' đến 2 CHỮ SỐ CÓ NGHĨA tương ứng); (2) như đã thấy ở CÂU 9, một số PHÉP TÍNH (CHIA cho SỐ GẦN 0, TRỪ HAI SỐ GẦN NHAU) có thể ''KHUẾCH ĐẠI SAI SỐ'' NGHIÊM TRỌNG, VƯỢT QUÁ KHẢ NĂNG ''TỰ SỬA'' của MÁY TÍNH nếu NGƯỜI DÙNG không Ý THỨC về VẤN ĐỀ này; (3) hiểu về SAI SỐ giúp BIẾT KHI NÀO một KẾT QUẢ ''ĐỦ TỐT'' cho MỤC ĐÍCH SỬ DỤNG, và KHI NÀO CẦN THẬN TRỌNG HƠN (ví dụ trong các ỨNG DỤNG AN TOÀN như HÀNG KHÔNG, Y TẾ); MÁY TÍNH là CÔNG CỤ MẠNH MẼ, NHƯNG NGƯỜI SỬ DỤNG CẦN có KIẾN THỨC và TƯ DUY ĐÚNG ĐẮN về SAI SỐ để SỬ DỤNG kết quả MỘT CÁCH CÓ TRÁCH NHIỆM và CHÍNH XÁC.', loi_giai = 'Đây là một THÔNG ĐIỆP QUAN TRỌNG: CÔNG NGHỆ (như máy tính cầm tay) là CÔNG CỤ HỖ TRỢ MẠNH MẼ, NHƯNG KHÔNG THỂ THAY THẾ HOÀN TOÀN cho VIỆC HIỂU BIẾT và TƯ DUY ĐÚNG ĐẮN của NGƯỜI SỬ DỤNG về BẢN CHẤT của DỮ LIỆU và SAI SỐ.' WHERE id = '59b76ddc-2775-4f65-a281-0b8a637bf7d9';
UPDATE questions SET noi_dung = 'Tìm m để hai vectơ u = (m; 2) và v = (3; m-1) cùng phương (là hai vectơ chỉ phương của cùng một phương).' WHERE id = '59ea51d2-4dc5-4331-8252-c5b9dd2baf11';
UPDATE questions SET noi_dung = 'Xưởng may sản xuất x áo (cần 2 giờ/áo) và y quần (cần 3 giờ/quần). Xưởng có tối đa 120 giờ. bất phương trình ràng buộc là: A. 2x + 3y ≥ 120 B. 2x + 3y ≤ 120 C. 3x + 2y ≤ 120 D. x + y ≤ 120' WHERE id = '5b1ba0d2-8e14-40c9-b46c-c6b5f6fd9ac1';
UPDATE questions SET noi_dung = 'Viết phương trình tổng quát đường thẳng qua A(0; 3) và B(2; 0). Bước 1: AB = (2; -3). Bước 2: vectơ pháp tuyến n = (3; 2). Bước 3: phương trình tổng quát: 3x + 2y - 6 = 0. Kiểm tra và chỉ ra bước sai (nếu có).', distractors = '[{"phuong_an":"Bước 2 sai, vectơ pháp tuyến phải là (2; -3)","quan_niem_sai":"Đồng nhất vectơ chỉ phương với vectơ pháp tuyến"},{"phuong_an":"Bước 3 sai, phải là 3x + 2y + 6 = 0","quan_niem_sai":"Sai dấu hệ số tự do"},{"phuong_an":"Bước 1 sai, AB = (-2; 3)","quan_niem_sai":"Trừ ngược thứ tự"}]'::jsonb, loi_giai = 'Kiểm tra kĩ: vectơ pháp tuyến (3;2) có (3;2)·(2;-3) = 6 - 6 = 0 ✓. phương trình tổng quát qua A: 3(x-0) + 2(y-3) = 0 ⇔ 3x + 2y - 6 = 0 ✓. Lời giải hoàn toàn đúng.' WHERE id = '5b496a76-4ab5-494c-8c9d-a0f9123e63ee';
UPDATE questions SET noi_dung = 'Viết phương trình đường tròn có tâm I(3; 1) và đi qua điểm A(6; 5).', loi_giai = 'R = IA = √((6-3)² + (5-1)²) = √(9 + 16) = 5. phương trình: (x-3)² + (y-1)² = 25.' WHERE id = '5b700403-70de-47c1-a0a5-f35fa48ecb73';
UPDATE questions SET noi_dung = 'Viết phương trình tổng quát của đường thẳng đi qua M(-1; 2) và có vectơ pháp tuyến n = (3; 5).', distractors = '[{"phuong_an":"3x + 5y + 7 = 0","quan_niem_sai":"Sai dấu hệ số tự do khi khai triển"},{"phuong_an":"3x + 5y - 13 = 0","quan_niem_sai":"Sai dấu ở (x + 1): dùng (x - 1)"},{"phuong_an":"5x + 3y - 1 = 0","quan_niem_sai":"Đảo hai thành phần của vectơ pháp tuyến"}]'::jsonb WHERE id = '5d048f88-84ff-4e6a-9229-02af46aab6f2';
UPDATE questions SET noi_dung = 'Viết phương trình tham số của đường thẳng đi qua hai điểm A(1; 2) và B(4; 8).', distractors = '[{"phuong_an":"x = 1 - 3t ; y = 2 - 6t (coi là đáp án duy nhất sai khác)","quan_niem_sai":"Trừ ngược thứ tự khi tính AB"},{"phuong_an":"x = 3 + t ; y = 6 + 2t","quan_niem_sai":"Lấy vectơ chỉ phương làm điểm mốc"},{"phuong_an":"x = 1 + 5t ; y = 2 + 10t","quan_niem_sai":"Cộng toạ độ hai điểm thay vì trừ"}]'::jsonb, loi_giai = 'vectơ chỉ phương: AB = (4-1 ; 8-2) = (3; 6). Chọn mốc A(1;2): x = 1 + 3t, y = 2 + 6t. (Có thể rút gọn vectơ chỉ phương thành (1;2): x = 1 + t, y = 2 + 2t.)' WHERE id = '5d9ee878-2956-42eb-99e7-d67efae2ec39';
UPDATE questions SET dap_an = 'Bước ① và ③ ĐÚNG ✓ (hệ ràng buộc chuẩn, các đỉnh chuẩn). LỖI Ở BƯỚC ②: LẪN HÀM MỤC TIÊU VỚI RÀNG BUỘC! Bạn ấy lấy F = 5x + 2y — nhưng đó là SỐ GIỜ MÁY (ràng buộc!), KHÔNG PHẢI LÃI! ⇒ Bạn ấy đang tính ''tối đa hoá SỐ GIỜ'' — VÔ NGHĨA! (Xưởng nào lại muốn DÙNG NHIỀU GIỜ NHẤT?! Người ta muốn LÃI NHIỀU NHẤT!) HÀM MỤC TIÊU ĐÚNG: Lãi = tiền lãi bàn + tiền lãi ghế. Mỗi bàn lãi 500 nghìn ⇒ x bàn lãi 500x · Mỗi ghế lãi 200 nghìn ⇒ y ghế lãi 200y ⇒ F = 500x + 200y (nghìn đồng) ✓ PHÂN BIỆT RÕ: 5x + 2y = SỐ GIỜ máy (đơn vị: giờ) ⇒ RÀNG BUỘC (≤ 20) | 500x + 200y = LÃI (đơn vị: nghìn đồng) ⇒ HÀM MỤC TIÊU (tìm max!) — chúng khác nhau HOÀN TOÀN, cả về SỐ lẫn ĐƠN VỊ! TÍNH LẠI: F(0;0) = 0 | F(4;0) = 500(4) + 200(0) = 2000 ⬅️ MAX | F(0;10) = 500(0) + 200(10) = 2000 ⬅️ MAX ⇒ giá trị lớn nhất = 2000 nghìn = 2 triệu, đạt tại CẢ HAI đỉnh (4;0) [làm 4 bàn, 0 ghế] và (0;10) [làm 0 bàn, 10 ghế] ✓' WHERE id = '5e1e6e4e-db37-428a-b084-4215d5ef6154';
UPDATE questions SET noi_dung = 'Để lập phương trình đường tròn qua ba điểm không thẳng hàng, ta thường:', loi_giai = 'Mỗi điểm cho một phương trình bậc nhất theo a, b, c ⇒ hệ 3 3 ẩn, giải ra tâm và c.' WHERE id = '600cdd85-e054-45bc-bd81-e61ed8796f69';
UPDATE questions SET distractors = '[{"phuong_an":"Sai vì kết quả bằng 8","quan_niem_sai":"Cộng thay vì trừ hệ số tự do"},{"phuong_an":"Sai vì thay ngược x, y","quan_niem_sai":"Thay x = 1, y = 2 (sai thứ tự toạ độ)"},{"phuong_an":"Không kết luận được nếu chưa có phương trình tham số","quan_niem_sai":"Không biết cách kiểm tra trực tiếp bằng phương trình tổng quát"}]'::jsonb WHERE id = '6035878d-c5a0-4f27-a64a-96bb3d49e4fc';
UPDATE questions SET noi_dung = 'Xét tính đúng/sai: Hai đường thẳng có cùng vectơ pháp tuyến thì luôn song song với nhau.', distractors = '[{"phuong_an":"Đúng","quan_niem_sai":"Bỏ sót trường hợp trùng nhau — lỗi rất phổ biến"},{"phuong_an":"Đúng, nếu hệ số tự do bằng nhau","quan_niem_sai":"Ngược lại: hệ số tự do TỈ LỆ mới là trùng nhau"},{"phuong_an":"Sai, vì cùng vectơ pháp tuyến thì vuông góc","quan_niem_sai":"Nhầm hoàn toàn hai khái niệm"}]'::jsonb, loi_giai = 'Cùng vectơ pháp tuyến chỉ đảm bảo CÙNG PHƯƠNG. Nếu hệ số tự do cũng tỉ lệ thì hai đường TRÙNG nhau, không phải song song. Ví dụ x + y - 1 = 0 và 2x + 2y - 2 = 0 trùng nhau.' WHERE id = '61ac18d9-ed8a-4dbd-a7c2-61290df6d5f9';
UPDATE questions SET loi_giai = 'A(5;0) nằm trên Ox ⇒ đỉnh trục lớn ⇒ a = 5, a² = 25. Tiêu cự 2c = 8 ⇒ c = 4. Elip: b² = a² - c² = 25 - 16 = 9. phương trình: x²/25 + y²/9 = 1.' WHERE id = '624ced7e-4e08-4773-9160-02386838a1f0';
UPDATE questions SET noi_dung = 'a) Miền nghiệm hệ = phần chồng lấn của các miền nghiệm từng bất phương trình b) Miền nghiệm hệ LỚN HƠN miền nghiệm của mỗi bất phương trình riêng lẻ c) Miền nghiệm hệ có thể là TẬP RỖNG (hệ vô nghiệm) d) Có thể tô phần KHÔNG thuộc mỗi bất phương trình, rồi vùng TRẮNG còn lại là miền nghiệm' WHERE id = '6282e450-fa7d-4fb7-a9dc-6dffa1fdce88';
UPDATE questions SET distractors = '[{"phuong_an":"Sai, vì O không thuộc đường thẳng nào","quan_niem_sai":"Hiểu sai: gốc O vẫn là một điểm bình thường"},{"phuong_an":"Sai, vì thiếu hệ số tự do","quan_niem_sai":"Cho rằng phương trình phải có đủ ba hệ số A, B, C khác 0"},{"phuong_an":"Chỉ đúng nếu 5 = 3","quan_niem_sai":"Áp sai điều kiện, không thay số kiểm tra"}]'::jsonb WHERE id = '62d2ae39-2129-4c2b-814d-3a9171ceb67d';
UPDATE questions SET noi_dung = 'Cho mẫu điểm: 5, 6, 7, 7, 8, 8, 9, 25 (giá trị 25 NGHI NGỜ là bất thường). Biết Q1=6,5; Q3=8,5. Bước 1: Tính khoảng tứ phân vị. Bước 2: Tính CẬN DƯỚI, CẬN TRÊN. Bước 3: Kiểm tra xem 25 có phải BẤT THƯỜNG không.', dap_an = 'Bước 1: khoảng tứ phân vị=8,5−6,5=2. Bước 2: cận dưới=6,5−1,5×2=6,5−3=3,5; cận trên=8,5+1,5×2=8,5+3=11,5. Bước 3: vì 25>11,5 (cận trên), giá trị 25 LÀ BẤT THƯỜNG (outlier).', distractors = '[{"phuong_an":"Bước 3 (lỗi cài sẵn): ''vì 25>Q3=8,5 (không so với CẬN TRÊN=11,5), giá trị 25 LÀ BẤT THƯỜNG'' (so sánh SAI với Q3 thay vì CẬN TRÊN)","quan_niem_sai":"misc_so_sanh_voi_q3_thay_vi_can_tren — SO SÁNH giá trị NGHI NGỜ với Q3 (thay VÌ ĐÚNG phải SO SÁNH với CẬN TRÊN=Q3+1,5×khoảng tứ phân vị), một lỗi BỎ QUA HỆ SỐ 1,5×khoảng tứ phân vị TRONG QUY TẮC XÁC ĐỊNH BẤT THƯỜNG."}]'::jsonb, loi_giai = 'Áp dụng ĐẦY ĐỦ quy trình: tính khoảng tứ phân vị, tính CẬN, rồi SO SÁNH giá trị NGHI NGỜ với CẬN để KẾT LUẬN.' WHERE id = '62ee8de6-66f8-4ab7-8626-7923de17b4fe';
UPDATE questions SET noi_dung = 'Viết phương trình chính tắc của elip có một tiêu điểm F₂(3; 0) và đi qua điểm M(0; 4).' WHERE id = '638f6d23-3caa-41f5-9f3f-aa1dbac7c61c';
UPDATE questions SET noi_dung = 'Nông trại trồng x ha lúa (cần 12 công/ha) và y ha ngô (cần 8 công/ha). Có tối đa 240 công lao động. Lập bất phương trình rồi RÚT GỌN về dạng ax + by ≤ c với a, b, c nguyên dương NHỎ NHẤT có thể. Giá trị của c bằng bao nhiêu?', distractors = '[{"phuong_an":"240","quan_niem_sai":"KHÔNG rút gọn — giữ nguyên bất phương trình gốc (đề yêu cầu NHỎ NHẤT có thể!)"},{"phuong_an":"120","quan_niem_sai":"Chỉ chia cho 2 (không tìm ƯCLN đầy đủ — dừng ở ước chung, chưa phải LỚN NHẤT!). 6 và 4 vẫn còn ước chung 2!"},{"phuong_an":"20","quan_niem_sai":"Chia cho 12 (nhầm — chia cho HỆ SỐ ĐẦU thay vì ƯCLN! Khi đó 8÷12 KHÔNG nguyên!)"}]'::jsonb, loi_giai = 'B1: bất phương trình gốc: 12x + 8y ≤ 240. B2: tìm ƯCLN(12, 8, 240): 12 = 2²×3 · 8 = 2³ · 240 = 2⁴×3×5 ⇒ ƯCLN = 2² = 4 ✓. Chia cả 3 số cho 4 (số DƯƠNG → KHÔNG đổi chiều!): 12÷4 = 3 · 8÷4 = 2 · 240÷4 = 60 ⇒ 3x + 2y ≤ 60 ✓. B3: a = 3, b = 2, c = 60 ✓. KIỂM CHỨNG (10;15): bất phương trình gốc: 12(10)+8(15) = 240 ≤ 240 ✓ | bất phương trình rút gọn: 3(10)+2(15) = 60 ≤ 60 ✓ ⇒ CÙNG KẾT LUẬN ✓' WHERE id = '64affb2a-7dfd-4d13-a735-bca7c7489804';
UPDATE questions SET loi_giai = 'DẤU HIỆU NHẬN BIẾT: RÀNG BUỘC ⛓️ — CÓ dấu ≤/≥ ✓, viết ''2x + 3y ≤ 20'', ta VẼ MIỀN nghiệm, số lượng NHIỀU (cả hệ!) | HÀM MỤC TIÊU 🎯 — KHÔNG có dấu ✗, viết ''F = 50x + 40y'' (hết!), ta TÍNH GIÁ TRỊ tại đỉnh, CHỈ CÓ MỘT! ⇒ Nhớ: hàm mục tiêu chỉ có MỘT — còn ràng buộc thì NHIỀU (cả một hệ!) THỬ NGAY: ''Xưởng làm x bàn (lãi 500 nghìn, cần 5 giờ) và y ghế (lãi 200 nghìn, cần 2 giờ). Có tối đa 20 giờ.'' Bé thấy 2 biểu thức: 5x + 2y → hỏi ''đây là gì?'' → SỐ GIỜ dùng (giờ ⏰) ⇒ RÀNG BUỘC (≤ 20) | 500x + 200y → SỐ TIỀN LÃI (nghìn đ 💰) ⇒ HÀM MỤC TIÊU! ✓ ⇒ F = 500x + 200y — tìm MAX (vì muốn lãi nhiều!) ✓ HẬU QUẢ NẾU LẤY NHẦM! Nếu bé lấy F = 5x + 2y (số giờ!) rồi tìm MAX ⇒ bé đang tính ''Làm sao dùng NHIỀU GIỜ NHẤT?'' ⇒ XƯỞNG NÀO LẠI MUỐN THẾ?! (Người ta muốn LÃI NHIỀU, chứ ai muốn TỐN GIỜ NHIỀU?!) ⇒ Kết quả VÔ NGHĨA HOÀN TOÀN! QUY TRÌNH: ① ĐỌC ĐỀ — GẠCH CHÂN: gạch 1 gạch dưới các GIỚI HẠN (''tối đa'', ''không quá'', ''chỉ có'') ⛓️ · gạch 2 gạch dưới cái MUỐN TỐI ƯU (''lãi lớn nhất'', ''chi phí thấp nhất'') 🎯 ② LẬP HỆ từ các câu gạch 1 gạch (có dấu ≤, ≥!) ➕ ĐỪNG QUÊN x ≥ 0, y ≥ 0! ③ LẬP F từ câu gạch 2 gạch (KHÔNG có dấu!) ④ Vẽ miền → Tìm đỉnh (SÀNG LỌC!) → Tính F → So sánh ✓ Rubric: Chưa đạt (chỉ nói ''đọc kỹ đề'', không đưa được tiêu chí phân biệt) | Cần cố gắng (nêu ''ràng buộc có dấu, hàm mục tiêu không'' nhưng không có ẩn dụ/ví dụ) | Đạt (có tiêu chí rõ (dấu bất phương trình, đơn vị), có ẩn dụ, có ví dụ áp dụng) | Tốt (đủ ý trên VÀ nêu HẬU QUẢ nếu lấy nhầm (''tối đa hoá SỐ GIỜ'' — vô nghĩa!) VÀ dạy mẹo NHÌN ĐƠN VỊ (tiền 💰 = mục tiêu · giờ ⏰ = ràng buộc) VÀ nhắc hàm mục tiêu chỉ có MỘT, ràng buộc thì NHIỀU — HS không nêu hậu quả là CHƯA ĐẠT).' WHERE id = '6534d45f-0627-4e8e-8efd-2296674f96b0';
UPDATE questions SET noi_dung = 'Cho (C): x² + y² - 2x - 4y = 0. Viết phương trình tiếp tuyến của (C) tại gốc toạ độ O(0; 0).', distractors = '[{"phuong_an":"2x - y = 0","quan_niem_sai":"Lấy IO làm vectơ chỉ phương thay vì vectơ pháp tuyến"},{"phuong_an":"x + 2y - 5 = 0","quan_niem_sai":"Viết phương trình qua tâm I thay vì qua tiếp điểm O"},{"phuong_an":"-x - 2y + 5 = 0","quan_niem_sai":"Sai dấu và sai điểm đi qua"}]'::jsonb, loi_giai = 'Tâm I(1; 2) (từ -2a = -2 ⇒ a = 1; -2b = -4 ⇒ b = 2). Kiểm O thuộc (C): 0 + 0 - 0 - 0 = 0 ✓. vectơ pháp tuyến = IO = O - I = (-1; -2), hay lấy (1; 2). phương trình qua O: 1(x - 0) + 2(y - 0) = 0 ⇔ x + 2y = 0. Kiểm: d(I, Δ) = |1 + 4|/√5 = 5/√5 = √5; R = √(1+4-0) = √5 ✓ bằng nhau ⇒ tiếp xúc.' WHERE id = '665e3342-03d4-4a81-8cfd-15d245928c22';
UPDATE questions SET distractors = '[{"phuong_an":"Song song","quan_niem_sai":"Thấy hệ số tỉ lệ nhưng quên kiểm tra hệ số tự do cũng tỉ lệ"},{"phuong_an":"Cắt nhau tại một điểm","quan_niem_sai":"Không nhận ra hai phương trình tương đương"},{"phuong_an":"Vuông góc","quan_niem_sai":"Nhầm điều kiện: tính 1·2 + 1·2 = 4 ≠ 0 nhưng vẫn kết luận vuông góc"}]'::jsonb WHERE id = '66e4cd80-a10b-4408-b37b-60a3a7103cf4';
UPDATE questions SET noi_dung = 'Tìm m để đường thẳng d₁: mx + (m-1)y + 2 = 0 có vectơ pháp tuyến vuông góc với của d₂: 2x + y - 1 = 0.' WHERE id = '689b86c3-f4a6-42d4-8b1e-bdabdea48c9a';
UPDATE questions SET distractors = '[{"phuong_an":"18","quan_niem_sai":"Chọn đỉnh (2;2) — nghĩ ''đỉnh giữa thì tối ưu'' (SAI! phải TÍNH HẾT!)"},{"phuong_an":"0","quan_niem_sai":"Lấy giá trị nhỏ nhất thay vì giá trị lớn nhất"},{"phuong_an":"50","quan_niem_sai":"Cộng bừa các giá trị: 0+12+18+20 = 50"}]'::jsonb WHERE id = '69015e8f-51e7-4704-b105-c419bca563f2';
UPDATE questions SET loi_giai = 'ĐỔI SANG ĐIỂM NÀO? Chọn (1;0) hoặc (0;1) — vẫn rất dễ tính! VD bất phương trình 2x − y > 0: thay (1;0): 2(1) − 0 = 2. Hỏi 2 > 0? ĐÚNG ✓ ⇒ tô nửa CHỨA (1;0) ✓ (cũng chỉ mất 3 giây!). MẸO KIỂM CHỨNG: thử CẢ HAI điểm (1;0) và (0;1). Thử (1;0) → ĐÚNG ⇒ tô nửa chứa (1;0). Thử (0;1) → SAI ⇒ tô nửa không chứa (0;1). Hai câu nghe ''ngược nhau'' — nhưng CHỈ VÀO CÙNG MỘT NỬA (vì (1;0) và (0;1) ở hai bên bờ)! Cùng kết quả ⇒ bé làm ĐÚNG ✓ · Khác kết quả ⇒ bé tính SAI — kiểm lại! Rubric: Chưa đạt (chỉ nói ''vì c = 0 thì không dùng O'') | Cần cố gắng (giải thích O nằm trên bờ nhưng không nêu dấu hiệu nhận biết) | Đạt (có ẩn dụ, nêu dấu hiệu c = 0, chỉ ra điểm thử thay thế) | Tốt (đủ ý trên VÀ HOÀ GIẢI mâu thuẫn (lời cô đúng, chỉ thiếu điều kiện) VÀ dạy mẹo kiểm chứng bằng 2 điểm thử — HS nói ''cô dạy sai'' hoặc ''cứ nhớ là được'' là CHƯA ĐẠT). Cùng tinh thần C01-Q10 Chương I: ''anh trai không sai — anh nói về ℕ*, cô nói về ℕ''.' WHERE id = '6b4f12c3-aa39-4fe7-bb21-00b2cf737d50';
UPDATE questions SET noi_dung = 'Công thức tính góc giữa hai đường thẳng có vectơ pháp tuyến n₁, n₂ là:' WHERE id = '6d180403-882c-4f28-8de3-c505465dc4b8';
UPDATE questions SET noi_dung = 'a) Đỉnh miền nghiệm là giao điểm của hai bờ b) MỌI giao điểm của hai bờ đều là đỉnh của miền nghiệm c) Phải KIỂM giao điểm có thuộc miền nghiệm không (thay vào cả hệ) d) Hệ có 4 bất phương trình thì miền nghiệm luôn có 4 đỉnh', distractors = '[{"phuong_an":"b) chọn Đúng","quan_niem_sai":"BỆNH CHÍNH (lấy tất cả giao điểm). CẶP ĐỐI CHỨNG: HS trả lời b) Đúng (mọi giao điểm là đỉnh) rồi c) Đúng (phải kiểm) ⇒ TỰ MÂU THUẪN! Nếu MỌI giao điểm đều là đỉnh ⇒ KHÔNG cần kiểm làm gì!"},{"phuong_an":"d) chọn Đúng","quan_niem_sai":"Nhầm ''số bất phương trình = số đỉnh'' — KHÔNG có quy tắc đó!"}]'::jsonb, loi_giai = 'b) SAI! Nhiều giao điểm nằm NGOÀI miền ⇒ KHÔNG phải đỉnh! | d) SAI! Hệ 4 bất phương trình có C(4,2) = 6 giao điểm — nhưng chỉ MỘT SỐ là đỉnh! (có thể 3, 4, hoặc thậm chí 0 nếu vô nghiệm!)' WHERE id = '6ea4f4aa-8aed-420f-8dbe-99d63c3bf010';
UPDATE questions SET noi_dung = 'Điền: Đường thẳng qua M(x₀; y₀) có vectơ chỉ phương u = (a; b) với a, b ≠ 0 có phương trình chính tắc là ______.', distractors = '[{"phuong_an":"(x - x₀)/b = (y - y₀)/a","quan_niem_sai":"Đảo hai thành phần của vectơ chỉ phương"},{"phuong_an":"(x + x₀)/a = (y + y₀)/b","quan_niem_sai":"Sai dấu: cộng thay vì trừ"},{"phuong_an":"a(x - x₀) = b(y - y₀)","quan_niem_sai":"Nhầm thành dạng nhân chéo với vai trò a, b sai vị trí"}]'::jsonb, loi_giai = 'Suy từ phương trình tham số bằng cách rút t từ cả hai phương trình rồi cho bằng nhau.' WHERE id = '6f500108-2743-479b-892d-5bf552f151f3';
UPDATE questions SET distractors = '[{"phuong_an":"Sai kết quả, φ ≈ 8,13°","quan_niem_sai":"Nhầm lấy arcsin thay vì arccos"},{"phuong_an":"Sai vì phải dùng vectơ chỉ phương chứ không dùng vectơ pháp tuyến","quan_niem_sai":"Không biết công thức dùng được cho cả hai loại vectơ"},{"phuong_an":"Không có lỗi gì cả","quan_niem_sai":"Bỏ qua việc thiếu trị tuyệt đối — mầm mống lỗi nghiêm trọng"}]'::jsonb WHERE id = '6fccedbc-fbdc-4791-8288-f344379f1a4e';
UPDATE questions SET loi_giai = 'A = 0 nên phương trình trở thành 3y = 6 ⇔ y = 2 — đường nằm ngang, song song Ox.' WHERE id = '7092a607-6128-45c2-9a44-96b6fb2fd274';
UPDATE questions SET noi_dung = 'So sánh HAI cổ phiếu: A (lợi nhuận trung bình=10%, độ lệch chuẩn=4%); B (lợi nhuận trung bình=20%, độ lệch chuẩn=6%). Bước 1: Tính hệ số biến thiên của MỖI cổ phiếu. Bước 2: So sánh. Bước 3: Kết luận cổ phiếu NÀO ''RỦI RO TƯƠNG ĐỐI'' CAO HƠN (theo hệ số biến thiên).', dap_an = 'Bước 1: hệ số biến thiên(A)=4/10×100%=40%; hệ số biến thiên(B)=6/20×100%=30%. Bước 2: hệ số biến thiên(A)=40%>hệ số biến thiên(B)=30%. Bước 3: Cổ phiếu A có RỦI RO TƯƠNG ĐỐI CAO HƠN (dù ĐỘ LỆCH CHUẨN TUYỆT ĐỐI của A NHỎ HƠN B), vì SO với MỨC LỢI NHUẬN TRUNG BÌNH của NÓ, A có ĐỘ DAO ĐỘNG LỚN HƠN.', distractors = '[{"phuong_an":"Bước 3 (lỗi cài sẵn): ''vì ĐỘ LỆCH CHUẨN của B (6%) LỚN HƠN A (4%), cổ phiếu B RỦI RO CAO HƠN'' (so sánh TRỰC TIẾP độ lệch chuẩn TUYỆT ĐỐI, bỏ qua hệ số biến thiên)","quan_niem_sai":"misc_so_sanh_truc_tiep_do_lech_chuan_bo_qua_cv — SO SÁNH TRỰC TIẾP ĐỘ LỆCH CHUẨN TUYỆT ĐỐI (bỏ QUA sự KHÁC BIỆT về MỨC TRUNG BÌNH giữa HAI cổ phiếu), dẫn đến KẾT LUẬN NGƯỢC với KẾT QUẢ ĐÚNG khi dùng hệ số biến thiên (thước đo RỦI RO TƯƠNG ĐỐI phù hợp hơn trong trường hợp này)."}]'::jsonb, loi_giai = 'So sánh RỦI RO ''TƯƠNG ĐỐI'' (dùng hệ số biến thiên) thay VÌ chỉ SO SÁNH ĐỘ LỆCH CHUẨN TUYỆT ĐỐI, khi HAI đại LƯỢNG có MỨC TRUNG BÌNH KHÁC NHAU ĐÁNG KỂ.' WHERE id = '7273a5e5-d4d3-47fe-99b6-f17bc224668f';
UPDATE questions SET distractors = '[{"phuong_an":"a² = 9","quan_niem_sai":"Lấy a = b = 3 — bỏ qua điều kiện tâm sai"},{"phuong_an":"a² = 36","quan_niem_sai":"Giải sai phương trình 9 = 3a²/4"},{"phuong_an":"a² = 6","quan_niem_sai":"Dùng b² = a² + c² thay vì a² - c²"}]'::jsonb WHERE id = '7635f8e0-faf6-4125-94c8-4de3fe819fdd';
UPDATE questions SET noi_dung = 'Biết Q1=10, Q3=30 (khoảng tứ phân vị=20). Giá trị nào sau đây được coi là BẤT THƯỜNG? (Hỏi kèm độ tự tin 1–3)', loi_giai = 'Cận TRÊN=Q3+1,5×khoảng tứ phân vị=30+1,5×20=30+30=60; vì 65>60, giá trị 65 là BẤT THƯỜNG.' WHERE id = '7692d51f-a603-4063-b00e-9e2c2cfe621e';
UPDATE questions SET loi_giai = 'BƯỚC B1 — CẢNH BÁO: x ≥ 0 và y ≥ 0 CŨNG LÀ bất phương trình ⇒ chúng CŨNG CÓ BỜ (là HAI TRỤC TOẠ ĐỘ!). HS quên chúng ⇒ chỉ có 1 bờ ⇒ KHÔNG có giao điểm nào ⇒ KHÔNG tìm được đỉnh!' WHERE id = '76f068d3-501e-4915-afe3-2b147c9439e8';
UPDATE questions SET noi_dung = 'Đường thẳng d: (x - 1)/2 = (y + 3)/5. Điểm nào và vectơ chỉ phương nào tương ứng?', distractors = '[{"phuong_an":"M(-1; 3), u = (2; 5)","quan_niem_sai":"Đọc sai dấu điểm mốc (không đổi dấu)"},{"phuong_an":"M(1; -3), u = (5; 2)","quan_niem_sai":"Đảo hai thành phần vectơ chỉ phương"},{"phuong_an":"M(2; 5), u = (1; -3)","quan_niem_sai":"Đảo vai trò điểm và vectơ chỉ phương"}]'::jsonb, loi_giai = 'Đọc trực tiếp: tử số cho điểm mốc (đổi dấu hằng số), mẫu số cho vectơ chỉ phương.' WHERE id = '77003fca-fd5c-499c-af32-d3d75aa79034';
UPDATE questions SET noi_dung = 'Tính \(\sqrt{5}+\sqrt{3}\) bằng máy tính cầm tay, sau đó quy tròn đến hàng phần trăm. (Hỏi kèm độ tự tin 1–3)', loi_giai = 'máy tính cầm tay cho \(\sqrt{5}\approx2{,}236\), \(\sqrt{3}\approx1{,}732\); tổng \(\approx3{,}968\), quy tròn đến hàng phần trăm: 3,97.' WHERE id = '79b94512-9687-40b2-b561-6454071e4d07';
UPDATE questions SET noi_dung = 'Cho tam giác ABC: A(1; 2), B(5; 4), C(3; 8). Viết phương trình tổng quát đường cao kẻ từ A.', distractors = '[{"phuong_an":"2x + y - 4 = 0","quan_niem_sai":"Lấy BC làm vectơ chỉ phương thay vì vectơ pháp tuyến của đường cao"},{"phuong_an":"x - 2y - 3 = 0","quan_niem_sai":"Sai dấu hệ số tự do khi khai triển"},{"phuong_an":"2x + 4y - 10 = 0","quan_niem_sai":"Nhầm đường cao từ A vuông góc với AB"}]'::jsonb, loi_giai = 'Đường cao từ A vuông góc BC ⇒ nhận BC làm vectơ pháp tuyến. BC = (3-5; 8-4) = (-2; 4), rút gọn (-1; 2) hay (1; -2). phương trình tổng quát: 1(x-1) - 2(y-2) = 0 ⇔ x - 2y + 3 = 0. Kiểm tra A(1;2): 1 - 4 + 3 = 0 ✓.' WHERE id = '7e8ef164-ca2b-4838-8790-0e6316e2325b';
UPDATE questions SET noi_dung = 'Thay điểm thử vào bất phương trình, nếu được mệnh đề SAI thì ta tô nửa mặt phẳng ___ chứa điểm thử.', loi_giai = 'Logic: điểm thử làm bất phương trình SAI ⇒ nó KHÔNG là nghiệm ⇒ KHÔNG nằm trong miền nghiệm ⇒ miền nghiệm ở phía BÊN KIA!' WHERE id = '7e9f4b20-18db-4539-9005-9c5340a8269c';
UPDATE questions SET distractors = '[{"phuong_an":"A","quan_niem_sai":"ĐẢO x, y! (bệnh A02-①). Kiểm: 1 − 3 = −2 ≠ 2 ✗"},{"phuong_an":"C","quan_niem_sai":"Bẫy tinh vi: 2 + 2 = 4 ✓ nhưng 2 − 2 = 0 ≠ 2 ✗ — chỉ thoả 1/2 phương trình! Phải kiểm CẢ HAI!"},{"phuong_an":"D","quan_niem_sai":"4 + 2 = 6 ≠ 4 ✗"}]'::jsonb, loi_giai = 'Cộng hai phương trình: (x+y) + (x−y) = 4 + 2 ⇒ 2x = 6 ⇒ x = 3. Thay vào PT①: 3 + y = 4 ⇒ y = 1 ⇒ (3; 1) ✓ KIỂM: 3 + 1 = 4 ✓ · 3 − 1 = 2 ✓ (nằm trên CẢ HAI đường!)' WHERE id = '802833ae-9232-4635-a2e2-a04e25324281';
UPDATE questions SET noi_dung = 'Biểu diễn miền nghiệm của hệ: ⎧ x + y ≤ 4 · ⎨ x ≥ 0 · ⎩ y ≥ 0. B1 — VẼ MIỀN bất phương trình ①. B2 — VẼ MIỀN ②. B3 — VẼ MIỀN ③. B4 — LẤY PHẦN GIAO & KIỂM CHỨNG.', loi_giai = 'BƯỚC B4 CÓ KIỂM CHỨNG — VAN AN TOÀN! Lấy một điểm trong miền vừa vẽ, thay vào CẢ HỆ: thoả hết ⇒ miền ĐÚNG ✓ · có bất phương trình không thoả ⇒ miền SAI — vẽ lại! KIỂM CHỨNG NGƯỢC — điểm NGOÀI miền: (5;0): 5 + 0 = 5 ≤ 4? ✗ ⇒ không thuộc ✓ | (−1;1): −1 ≥ 0? ✗ ⇒ không thuộc ✓ ⇒ Cả hai đều ngoài miền — khớp hình vẽ ✓ LƯU Ý điểm thử ở B2, B3: bờ x=0 và y=0 ĐI QUA GỐC O ⇒ KHÔNG dùng được O làm điểm thử (A05!) ⇒ phải chọn (1;0) và (0;1) ✓' WHERE id = '80443dc5-e256-4fa4-aa86-4eabfe81bf3b';
UPDATE questions SET noi_dung = 'Viết phương trình chính tắc của hypebol có tiêu điểm F₂(5; 0) và đi qua điểm A(4; 0).', loi_giai = 'A(4; 0) nằm trên Ox và là ĐỈNH của hypebol ⇒ a = 4, a² = 16. F₂(5;0) ⇒ c = 5. Hypebol: b² = c² - a² = 25 - 16 = 9. phương trình: x²/16 - y²/9 = 1. Kiểm A(4;0): 16/16 - 0 = 1 ✓.' WHERE id = '81af610f-80eb-4050-96d7-c0868a37442e';
UPDATE questions SET noi_dung = 'Cho vectơ chỉ phương u = (2; -5). Vectơ nào sau đây là vectơ pháp tuyến của cùng đường thẳng?', distractors = '[{"phuong_an":"n = (2; -5)","quan_niem_sai":"Đồng nhất vectơ pháp tuyến với vectơ chỉ phương"},{"phuong_an":"n = (-2; 5)","quan_niem_sai":"Chỉ đổi dấu, vẫn cùng phương với u nên không vuông góc"},{"phuong_an":"n = (5; -2)","quan_niem_sai":"Hoán vị nhưng đổi dấu sai vị trí: (2)(5)+(-5)(-2) = 20 ≠ 0"}]'::jsonb WHERE id = '8296c0db-5308-48db-92e2-c83916c55b82';
UPDATE questions SET noi_dung = 'Viết phương trình tham số của đường thẳng đi qua A(3; -2) và có vectơ chỉ phương u = (1; 4).', distractors = '[{"phuong_an":"x = 1 + 3t ; y = 4 - 2t","quan_niem_sai":"Đảo vai trò điểm và vectơ chỉ phương"},{"phuong_an":"x = 3 + 4t ; y = -2 + t","quan_niem_sai":"Đảo hai thành phần của vectơ chỉ phương"},{"phuong_an":"x = 3 - t ; y = -2 - 4t và cho rằng đây là phương trình khác","quan_niem_sai":"Cho rằng đổi dấu vectơ chỉ phương tạo ra đường thẳng khác"}]'::jsonb WHERE id = '8425a098-4e9d-454f-8e79-4651b94ae46d';
UPDATE questions SET distractors = '[{"phuong_an":"55 KHÔNG phải bất thường vì nó VẪN là một SỐ HỢP LỆ trong dữ liệu (không tính CẬN TRÊN)","quan_niem_sai":"KHÔNG THỰC HIỆN đúng QUY TRÌNH tính CẬN TRÊN (dựa trên khoảng tứ phân vị) để XÁC ĐỊNH TÍNH BẤT THƯỜNG, chỉ dựa vào NHẬN ĐỊNH CHỦ QUAN rằng ''nó VẪN là một SỐ HỢP LỆ'' mà KHÔNG áp DỤNG TIÊU CHÍ ĐỊNH LƯỢNG cụ THỂ."}]'::jsonb, loi_giai = 'khoảng tứ phân vị=31−24,5=6,5; cận trên=31+1,5×6,5=31+9,75=40,75; vì 55>40,75, giá trị 55 LÀ BẤT THƯỜNG. VỀ VIỆC LOẠI BỎ: KHÔNG NÊN tự động LOẠI BỎ mà KHÔNG XEM XÉT NGUYÊN NHÂN (có THỂ là LỖI NHẬP LIỆU, hoặc một TRƯỜNG HỢP THỰC SỰ ĐẶC BIỆT CẦN được GHI NHẬN) — cần TÌM HIỂU BỐI CẢNH trước khi QUYẾT ĐỊNH.' WHERE id = '848dba1d-5f90-4e98-80b9-53c40d38d045';
UPDATE questions SET distractors = '[{"phuong_an":"Lớp B (nhầm rằng ĐỘ LỆCH CHUẨN NHỎ HƠN nghĩa là PHÂN TÁN NHIỀU HƠN)","quan_niem_sai":"ĐẢO NGƯỢC Ý NGHĨA của ĐỘ LỆCH CHUẨN, cho rằng GIÁ TRỊ NHỎ HƠN (0,8) tương ứng với PHÂN TÁN NHIỀU HƠN, trong khi THỰC CHẤT NGƯỢC LẠI."},{"phuong_an":"Không thể xác định vì cần TÍNH THÊM HỆ SỐ BIẾN THIÊN","quan_niem_sai":"KHÔNG CẦN THIẾT trong TRƯỜNG HỢP này: vì HAI lớp CÓ CÙNG TRUNG BÌNH (=7), có THỂ SO SÁNH TRỰC TIẾP ĐỘ LỆCH CHUẨN mà KHÔNG CẦN tính hệ số biến thiên (hệ số biến thiên CHỈ CẦN THIẾT khi TRUNG BÌNH KHÁC NHAU ĐÁNG KỂ)."},{"phuong_an":"Cả hai lớp PHÂN TÁN NHƯ NHAU vì CÓ CÙNG TRUNG BÌNH","quan_niem_sai":"SAI: TRUNG BÌNH GIỐNG NHAU KHÔNG có nghĩa ĐỘ PHÂN TÁN GIỐNG NHAU; CẦN so SÁNH RIÊNG ĐỘ LỆCH CHUẨN (hai THÔNG SỐ ĐỘC LẬP với nhau)."}]'::jsonb WHERE id = '8640bb49-f306-43f5-ad43-3f4830c42926';
UPDATE questions SET noi_dung = 'Để tìm miền nghiệm của hệ, ta vẽ miền nghiệm từng bất phương trình rồi lấy phần ___ của chúng.' WHERE id = '87d9c33a-078f-4176-b2fd-fc945c527241';
UPDATE questions SET noi_dung = 'Cho mẫu (đã tính): Q1=5, Q2=8, Q3=13. Tính khoảng tứ phân vị và cho biết có liên quan gì đến Q2. (Hỏi kèm độ tự tin 1–3)', dap_an = 'khoảng tứ phân vị=8; khoảng tứ phân vị KHÔNG trực tiếp dùng Q2 trong công thức (dù Q2 nằm giữa Q1 và Q3)', distractors = '[{"phuong_an":"khoảng tứ phân vị=8; nhưng NHẦM cho rằng Q2 CŨNG cần được CỘNG/TRỪ vào công thức khoảng tứ phân vị","quan_niem_sai":"NHẦM LẪN rằng Q2 (TRUNG VỊ) CẦN được ĐƯA vào CÔNG THỨC TÍNH khoảng tứ phân vị, trong khi CÔNG THỨC CHUẨN CHỈ sử dụng Q3 và Q1, KHÔNG BAO GỒM Q2."}]'::jsonb, loi_giai = 'khoảng tứ phân vị=Q3−Q1=13−5=8; công thức khoảng tứ phân vị CHỈ SỬ DỤNG Q1 và Q3, KHÔNG BAO GỒM Q2 trực tiếp trong PHÉP TÍNH.' WHERE id = '895f77f2-3212-4228-9490-eabfbdd917a7';
UPDATE questions SET noi_dung = 'Cho bất phương trình 2x − y > 0. Thay điểm thử (1; 0) vào VẾ TRÁI, ta được giá trị bằng bao nhiêu?', loi_giai = '2x − y với x = 1, y = 0: 2(1) − 0 = 2 ✓. Kết luận tiếp: 2 > 0? ĐÚNG ✓ ⇒ (1;0) LÀ nghiệm ⇒ tô nửa CHỨA (1;0). BẰNG CHỨNG QUAN TRỌNG: cùng bất phương trình này, thử (0;1) → 2(0) − 1 = −1, hỏi −1 > 0? SAI ✗ ⇒ tô nửa KHÔNG chứa (0;1). Hai kết luận ''ngược nhau'' về CHỮ nhưng CÙNG CHỈ MỘT NỬA (vì (1;0) và (0;1) ở hai nửa khác nhau)!' WHERE id = '8a6f8d82-6aff-403e-a5fa-5deffdf9677c';
UPDATE questions SET noi_dung = 'Viết phương trình chính tắc của đường thẳng đi qua A(1; 2) và B(4; 8).', distractors = '[{"phuong_an":"(x - 1)/6 = (y - 2)/3","quan_niem_sai":"Đảo hai thành phần vectơ chỉ phương"},{"phuong_an":"(x - 4)/(-3) = (y - 8)/(-6) và cho là sai","quan_niem_sai":"Không nhận ra đây là cùng một đường thẳng (chọn mốc B)"},{"phuong_an":"(x - 1)/5 = (y - 2)/10","quan_niem_sai":"Cộng toạ độ hai điểm thay vì trừ"}]'::jsonb, loi_giai = 'AB = (3; 6) là vectơ chỉ phương; cả hai thành phần khác 0 nên viết được phương trình chính tắc: (x-1)/3 = (y-2)/6.' WHERE id = '8a892c2b-84cf-4726-9c7d-4876ddce5b0e';
UPDATE questions SET noi_dung = 'Trong các phương trình sau, nào là hypebol: (I) x²/4 - y²/9 = 1; (II) x² + y² = 4; (III) y²/9 - x²/4 = 1?' WHERE id = '8c602770-7838-4d3d-9aac-45072e3f3bee';
UPDATE questions SET dap_an = 'Bước ① và ② ĐÚNG HẾT! (Đặc biệt bước ② xử lí RẤT TỐT trường hợp c = 0 — nhận ra bờ QUA GỐC O nên ĐỔI điểm thử sang (1;0) — A05! ✓) LỖI Ở BƯỚC ③: LẤY HỢP THAY VÌ GIAO! Bạn ấy viết ''miền nghiệm = TẤT CẢ các vùng đã tô — GỘP cả hai'' ⇒ ĐÓ LÀ PHÉP HỢP ∪! Nhưng nghiệm hệ phải thoả CẢ HAI bất phương trình ⇒ phải lấy PHẦN CHUNG = phép GIAO ∩! CÁCH ĐÚNG Ở BƯỚC ③: lấy PHẦN CHỒNG LẤN (vùng được tô bởi CẢ HAI)! Miền nghiệm hệ: nằm DƯỚI đường x + y = 4 (từ BPT①) VÀ nằm dưới-phải đường y = x (từ BPT②) ⇒ là một GÓC.' WHERE id = '8cecb5e4-4ccc-45d8-a2ca-2b57fe40da6c';
UPDATE questions SET noi_dung = 'Tính chu vi hình chữ nhật với chiều dài \(a=\sqrt{50}\)cm và chiều rộng \(b=\sqrt{18}\)cm. Bước 1: Tính \(a, b\) bằng máy tính cầm tay (giữ NHIỀU chữ số). Bước 2: Tính chu vi \(P=2(a+b)\) (dùng giá trị CHƯA làm tròn). Bước 3: Quy tròn kết quả cuối cùng đến hàng phần trăm.' WHERE id = '90514827-2d93-43a7-9230-21b3280ec716';
UPDATE questions SET noi_dung = 'Viết phương trình chính tắc của elip có bán trục lớn a = 5, bán trục nhỏ b = 4.' WHERE id = '91841791-dfe7-42b7-8374-f6ed68dfeaad';
UPDATE questions SET noi_dung = 'Tìm m để x² + y² + 2mx - 2(m-1)y + 2m² - 2m + 1 = 0 là phương trình đường tròn.', dap_an = 'Không có m nào (phương trình luôn suy biến thành một điểm)' WHERE id = '92ca1b15-2bca-4d0f-b75f-d73aaf27deb4';
UPDATE questions SET noi_dung = 'Điền: Đường tròn tâm I(a; b), bán kính R có phương trình chính tắc là ______.' WHERE id = '93122256-afb8-4f25-b2ed-1e2d7bcb18a1';
UPDATE questions SET distractors = '[{"phuong_an":"5","quan_niem_sai":"CHỈ KIỂM BPT①! (CẢ 5 cặp đều thoả BPT① — thiết kế có chủ ý!) ⇒ BỆNH kiểm thiếu bất phương trình phơi bày!"},{"phuong_an":"2","quan_niem_sai":"Loại nhầm các cặp nằm trên bờ (bệnh nét liền/đứt!)"},{"phuong_an":"3","quan_niem_sai":"Bỏ sót một cặp"}]'::jsonb WHERE id = '949d15f1-0062-496f-8842-85c2bdc496a8';
UPDATE questions SET dap_an = '(a) Thay O vào ax + by cho a(0)+b(0) = 0 — tính nhẩm ngay, chỉ cần so 0 với c. VD: 5x − 7y ≤ 3 → thay O: 0 ≤ 3? ĐÚNG ✓ → tô nửa chứa O. Xong trong 2 giây! (b) KHÔNG dùng được khi bờ ĐI QUA GỐC O — tức khi c = 0! VD: 2x − y > 0. Bờ 2x − y = 0, thay O: 2(0)−0 = 0 = 0 ✓ ⇒ O NẰM TRÊN BỜ! Thay O vào bất phương trình: 0 > 0? SAI — nhưng KHÔNG phải vì O ở nửa bên kia, mà vì O ở NGAY TRÊN VẠCH ⇒ KHÔNG phân biệt được nửa nào! XỬ LÍ: chọn điểm thử KHÁC — lấy (1;0): 2(1)−0 = 2. Hỏi 2 > 0? ĐÚNG ✓ ⇒ tô nửa CHỨA (1;0) ✓. (Hoặc (0;1): 2(0)−1 = −1 > 0? SAI ✗ ⇒ tô nửa KHÔNG chứa (0;1) — CÙNG kết quả!) (c) Điểm thử phải KHÔNG nằm trên đường thẳng bờ. Cách kiểm: thay vào phương trình bờ ax+by = c. Ra = c ⇒ TRÊN BỜ ⇒ LOẠI! Ra ≠ c ⇒ DÙNG ĐƯỢC ✓' WHERE id = '9550d9db-91ad-4642-9ff8-381e544da342';
UPDATE questions SET noi_dung = 'Từ định nghĩa parabol (cách đều F và đường chuẩn Δ), hãy chứng minh phương trình chính tắc có dạng y² = 2px.', distractors = '[{"phuong_an":"Đặt F(p; 0) và Δ: x = -p rồi làm tương tự","quan_niem_sai":"Sai vị trí F và Δ ⇒ ra y² = 4px, không phải dạng chuẩn"},{"phuong_an":"Dùng MF = 2·d(M, Δ) theo định nghĩa","quan_niem_sai":"Sai định nghĩa: parabol có tỉ số bằng 1 (cách ĐỀU)"},{"phuong_an":"Không chứng minh được, phải công nhận công thức","quan_niem_sai":"Tin rằng phương trình chính tắc parabol phải công nhận; không thấy suy được từ định nghĩa MF = d(M, Δ)"}]'::jsonb WHERE id = '97a36540-30ab-431c-8f76-27654659949c';
UPDATE questions SET distractors = '[{"phuong_an":"Không sai, 4√2 là đúng","quan_niem_sai":"Tin rằng trừ được hai hệ số tự do khi hai phương trình chưa cùng thang đo (chưa chuẩn hoá)"},{"phuong_an":"Sai ở mẫu số, phải là √(9+9)","quan_niem_sai":"Chuẩn hoá nhầm chiều: hạ d₁ theo d₂ nhưng tính mẫu sai"},{"phuong_an":"Sai vì hai đường này cắt nhau","quan_niem_sai":"Không nhận ra (1;1) và (3;3) cùng phương ⇒ song song"}]'::jsonb WHERE id = '98a5dbea-1b1b-423d-8da6-cff874039cd6';
UPDATE questions SET noi_dung = 'Có phải bất phương trình bậc nhất hai ẩn không? a) 2x + 3y ≤ 6 b) x² + y > 1 c) xy ≤ 4 d) x − 5y ≥ 0' WHERE id = '99e33080-4dcb-4fee-87e8-d5d09134d436';
UPDATE questions SET noi_dung = 'Bạn nói: ''Chỉ cần a² + b² - c > 0 là phương trình x² + y² - 2ax - 2by + c = 0 chắc chắn là đường tròn, không cần kiểm tra gì thêm.'' Nhận xét.', dap_an = 'Đúng — với ĐIỀU KIỆN phương trình đã ở đúng dạng chuẩn (hệ số x², y² đều bằng 1, không có xy).', distractors = '[{"phuong_an":"Sai hoàn toàn, luôn phải kiểm tra thêm","quan_niem_sai":"Không phân biệt phương trình đã chuẩn hoá và chưa chuẩn hoá"},{"phuong_an":"Đúng trong mọi trường hợp, không có cạm bẫy nào","quan_niem_sai":"Bỏ qua các phương trình chưa ở dạng chuẩn"},{"phuong_an":"Sai, vì còn cần c > 0","quan_niem_sai":"Thêm điều kiện không có thật"}]'::jsonb, loi_giai = 'Nếu phương trình ĐÃ ở dạng x² + y² - 2ax - 2by + c = 0 thì hình thức đã đảm bảo (hệ số x², y² đều là 1, không có xy), nên a² + b² - c > 0 là đủ. NHƯNG cạm bẫy nằm ở chỗ: nhiều bài cho phương trình dạng 3x² + 3y² - 6x + 1 = 0 hoặc x² + 2y² - 4x = 0 — chưa ở dạng chuẩn. Khi đó phải CHUẨN HOÁ (chia hệ số) hoặc LOẠI (nếu hệ số x², y² khác nhau) TRƯỚC. Vậy khẳng định đúng nhưng dễ bị áp dụng sai.' WHERE id = '9a1ed330-7572-467c-8f98-1fc40f63adcc';
UPDATE questions SET noi_dung = 'Điền: Nếu đường thẳng có vectơ chỉ phương u = (a; b) thì một vectơ pháp tuyến của nó là n = ______.', distractors = '[{"phuong_an":"n = (a; b)","quan_niem_sai":"Đồng nhất vectơ chỉ phương với vectơ pháp tuyến"},{"phuong_an":"n = (-a; -b)","quan_niem_sai":"Chỉ đổi dấu, không hoán vị nên vẫn cùng phương với u"},{"phuong_an":"n = (b; a)","quan_niem_sai":"Hoán vị nhưng quên đổi dấu ⇒ tích vô hướng ≠ 0"}]'::jsonb, loi_giai = 'vectơ pháp tuyến vuông góc vectơ chỉ phương: (a;b)·(b;-a) = ab - ab = 0 ✓.' WHERE id = '9ab18bd7-cb85-4336-a917-0c31f0a966fe';
UPDATE questions SET noi_dung = 'Xét tính đúng/sai: Đường thẳng d có phương trình tham số x = 2 + t, y = -1 + 3t thì d đi qua điểm M(2; -1).', distractors = '[{"phuong_an":"Sai vì d qua (1; 3)","quan_niem_sai":"Lấy vectơ chỉ phương làm điểm đi qua"},{"phuong_an":"Sai vì d qua (-2; 1)","quan_niem_sai":"Đổi dấu toạ độ điểm mốc một cách vô căn cứ"},{"phuong_an":"Sai vì phải kiểm tra bằng phương trình tổng quát mới kết luận được","quan_niem_sai":"Không nhận ra t = 0 cho ngay điểm mốc"}]'::jsonb, loi_giai = 'Cho t = 0 ta được (x; y) = (2; -1). Điểm này chính là điểm mốc trong phương trình tham số.' WHERE id = '9bd685be-a56a-461b-87a3-b7415988fabc';
UPDATE questions SET dap_an = 'TỨ PHÂN VỊ CHIA dữ liệu (đã SẮP XẾP) THÀNH BỐN PHẦN BẰNG NHAU về SỐ LƯỢNG (mỗi PHẦN chứa KHOẢNG 25% dữ liệu); Ý NGHĨA CỤ THỂ: KHOẢNG 25% dữ liệu CÓ GIÁ TRỊ NHỎ HƠN HOẶC BẰNG Q1 (PHẦN TỨ THẤP NHẤT); KHOẢNG 50% dữ liệu NHỎ HƠN HOẶC BẰNG Q2 (=TRUNG VỊ, một NỬA dữ liệu); KHOẢNG 75% dữ liệu NHỎ HƠN HOẶC BẰNG Q3 (PHẦN TỨ CAO NHẤT CHỈ chiếm 25% CÒN LẠI); TỨ PHÂN VỊ CUNG CẤP một ''BỨC TRANH CHI TIẾT HƠN'' về SỰ PHÂN BỐ của dữ liệu so với CHỈ BIẾT TRUNG VỊ (Q2) MỘT MÌNH — ví dụ, GIÚP BIẾT được dữ liệu có ''TẬP TRUNG'' HAY ''PHÂN TÁN'' Ở PHẦN NÀO, và LÀ NỀN TẢNG cho việc TÍNH ''KHOẢNG TỨ PHÂN VỊ'' (=Q3−Q1, sẽ học Ở NODE tiếp theo) — một THƯỚC ĐO ĐỘ PHÂN TÁN QUAN TRỌNG.' WHERE id = '9c1ab7c5-8e3c-479f-be92-24103e97ce40';
UPDATE questions SET loi_giai = 'Hai vectơ pháp tuyến không cùng phương ⇔ định thức A₁B₂ - A₂B₁ ≠ 0 ⇔ hệ có nghiệm duy nhất ⇔ cắt nhau.' WHERE id = '9d567699-0340-4394-bbcf-c1a978b86aad';
UPDATE questions SET noi_dung = 'Viết phương trình đường tròn tâm I(-1; 2), bán kính R = 4.' WHERE id = 'a125d488-991d-4cf7-87a7-00d392201f8b';
UPDATE questions SET noi_dung = 'Điền: Nhìn phương trình chính tắc, ta phân biệt: elip có dấu ______, hypebol có dấu ______, parabol chỉ có ______ biến bậc hai.' WHERE id = 'a3339ba3-e900-443d-a4c9-bf5fc68322ac';
UPDATE questions SET distractors = '[{"phuong_an":"A","quan_niem_sai":"LẤY NHẦM RÀNG BUỘC! 4x + 2y là SỐ GIỜ, không phải doanh thu!"},{"phuong_an":"C","quan_niem_sai":"Hàm mục tiêu KHÔNG CÓ DẤU bất phương trình! (đó là RÀNG BUỘC!) F chỉ là BIỂU THỨC — ta TÍNH GIÁ TRỊ của nó tại các đỉnh, không ''giải'' nó!"},{"phuong_an":"D","quan_niem_sai":"GHÉP NHẦM HỆ SỐ (bệnh A07-②) — gán 300 cho bàn, 800 cho ghế"}]'::jsonb WHERE id = 'a3cc200e-8864-44d4-b23e-5026f7a97e9a';
UPDATE questions SET noi_dung = 'Cho d₁: 2x - y + 1 = 0. Viết phương trình đường thẳng d₂ đi qua gốc O và tạo với d₁ một góc 45°.', distractors = '[{"phuong_an":"Chỉ 3x + y = 0","quan_niem_sai":"Giải phương trình bậc hai nhưng bỏ một nghiệm"},{"phuong_an":"y = x và y = -x","quan_niem_sai":"Chỉ nghĩ tới đường phân giác 45° của hệ trục, không tính với d₁"},{"phuong_an":"2x - y = 0","quan_niem_sai":"Lấy đường song song d₁ qua O (góc 0°, không phải 45°)"}]'::jsonb, loi_giai = 'd₂ qua O: ax + by = 0, vectơ pháp tuyến (a;b). cos45° = √2/2 = |2a - b|/(√5·√(a²+b²)) ⇒ 2(2a-b)² = 5(a²+b²)... Chi tiết: bình phương hai vế: 1/2 = (2a-b)²/(5(a²+b²)) ⇒ 5(a²+b²) = 2(2a-b)² = 2(4a² - 4ab + b²) = 8a² - 8ab + 2b² ⇒ 3a² - 8ab - 3b² = 0. Chia b² (b≠0), đặt k=a/b: 3k² - 8k - 3 = 0 ⇒ k = 3 hoặc k = -1/3. k=3 ⇒ (a;b)=(3;1) ⇒ d₂: 3x + y = 0. k=-1/3 ⇒ (a;b)=(1;-3) ⇒ d₂: x - 3y = 0. Kiểm tra d₂: 3x+y=0, n=(3;1): cos = |6-1|/(√5·√10) = 5/√50 = √2/2 ✓.' WHERE id = 'a43b13ce-e076-42b2-83fc-058bcf468031';
UPDATE questions SET noi_dung = 'Viết phương trình chính tắc của đường thẳng qua A(2; -1) với vectơ chỉ phương u = (3; 4).', distractors = '[{"phuong_an":"(x - 2)/4 = (y + 1)/3","quan_niem_sai":"Đảo hai thành phần vectơ chỉ phương"},{"phuong_an":"(x - 2)/3 = (y - 1)/4","quan_niem_sai":"Sai dấu tung độ (quên đổi dấu -1)"},{"phuong_an":"(x + 2)/3 = (y - 1)/4","quan_niem_sai":"Sai dấu cả hai toạ độ"}]'::jsonb WHERE id = 'a5cb3acd-289c-4783-8c4d-bfa0e0c2e7d5';
UPDATE questions SET noi_dung = 'Cho A(1; 2), B(3; 6). Viết phương trình trung trực của AB. Bước 1: Trung điểm I = (2; 4). Bước 2: AB = (2; 4) là vectơ pháp tuyến. Bước 3: phương trình: 2(x-1) + 4(y-2) = 0. Chỉ ra bước sai.', distractors = '[{"phuong_an":"Bước 2 sai, AB phải là vectơ chỉ phương","quan_niem_sai":"Nhầm vai trò: AB là vectơ pháp tuyến của trung trực"},{"phuong_an":"Bước 1 sai, trung điểm là (4; 8)","quan_niem_sai":"Cộng toạ độ mà quên chia 2"},{"phuong_an":"Không có bước nào sai","quan_niem_sai":"Tin rằng trung trực đi qua đầu mút A; không nắm trung trực đi qua TRUNG ĐIỂM của đoạn"}]'::jsonb, loi_giai = 'Bước 1 và 2 đúng (I là trung điểm, AB là vectơ pháp tuyến của trung trực). Nhưng bước 3 thay toạ độ A vào công thức thay vì I. phương trình đúng: 2(x-2) + 4(y-4) = 0 ⇔ x + 2y - 10 = 0. Kiểm tra I(2;4): 2 + 8 - 10 = 0 ✓.' WHERE id = 'a62264b4-2cd2-4b03-b2ed-0c7bc5f29436';
UPDATE questions SET distractors = '[{"phuong_an":"H(2; 0); AH = √10","quan_niem_sai":"Giải sai hệ giao điểm"},{"phuong_an":"H(1; 1); AH = 4","quan_niem_sai":"Tính khoảng cách bằng |3+3-2| mà quên chia cho √2"},{"phuong_an":"H(3; -1); AH = 4","quan_niem_sai":"Lấy vectơ pháp tuyến của d làm vectơ pháp tuyến của AH (nhầm vuông góc thành song song)"}]'::jsonb, loi_giai = 'Đường thẳng AH qua A(3;3), vuông góc d ⇒ nhận vectơ chỉ phương của d là (1;-1) làm vectơ pháp tuyến: 1(x-3) - 1(y-3) = 0 ⇔ x - y = 0. Giao với d: x + y = 2 và x = y ⇒ 2x = 2 ⇒ x = y = 1 ⇒ H(1; 1). AH = √((3-1)² + (3-1)²) = √8 = 2√2. Công thức: d(A,d) = |3 + 3 - 2|/√2 = 4/√2 = 2√2 ✓ khớp nhau.' WHERE id = 'a66c14cc-8e5c-4ba6-8537-a62c6f3a6f43';
UPDATE questions SET distractors = '[{"phuong_an":"4x + 6y - 2 = 0","quan_niem_sai":"Nhân đôi toàn bộ d ⇒ TRÙNG với d, không phải song song"},{"phuong_an":"3x - 2y + 1 = 0","quan_niem_sai":"vectơ pháp tuyến (3;-2) vuông góc với (2;3) ⇒ đây là đường VUÔNG GÓC"},{"phuong_an":"2x - 3y + 5 = 0","quan_niem_sai":"Đổi dấu hệ số B ⇒ vectơ pháp tuyến không cùng phương ⇒ cắt nhau"}]'::jsonb, loi_giai = 'Cùng vectơ pháp tuyến (2; 3) nhưng hệ số tự do khác (-1 ≠ 5) ⇒ song song (không trùng).' WHERE id = 'a72b67dd-77bc-4d01-9e37-d0b4e25a9e02';
UPDATE questions SET noi_dung = 'Điền vào chỗ trống: Nếu u = (a; b) là một vectơ chỉ phương của Δ thì mọi vectơ dạng k·u với k ______ cũng là vectơ chỉ phương của Δ.', distractors = '[{"phuong_an":"k > 0","quan_niem_sai":"Cho rằng vectơ chỉ phương phải cùng hướng, thực ra chỉ cần cùng phương"},{"phuong_an":"k bất kì","quan_niem_sai":"Quên loại k = 0 (cho ra vectơ-không)"},{"phuong_an":"k = 1","quan_niem_sai":"Cho rằng vectơ chỉ phương là duy nhất"}]'::jsonb, loi_giai = 'Mọi vectơ cùng phương và khác 0 đều là vectơ chỉ phương; k·u ≠ 0 ⇔ k ≠ 0.' WHERE id = 'a8aa1336-ce6e-4e29-85af-e00f69d55d78';
UPDATE questions SET noi_dung = 'Đường thẳng Δ vuông góc với d: 2x - y + 3 = 0. Một vectơ pháp tuyến của Δ là:', distractors = '[{"phuong_an":"n_Δ = (2; -1)","quan_niem_sai":"Lấy nguyên vectơ pháp tuyến của d (đó là song song, không phải vuông góc)"},{"phuong_an":"n_Δ = (-2; 1)","quan_niem_sai":"Đổi dấu vectơ pháp tuyến của d — vẫn cùng phương, vẫn là song song"},{"phuong_an":"n_Δ = (2; 1)","quan_niem_sai":"Hoán vị thiếu dấu: 2·2 + (-1)·1 = 3 ≠ 0"}]'::jsonb, loi_giai = 'n_d = (2; -1). Δ ⊥ d ⇒ vectơ pháp tuyến của Δ cùng phương với vectơ chỉ phương của d. vectơ chỉ phương của d là (1; 2) ⇒ n_Δ = (1; 2). Kiểm tra: n_Δ · n_d = 2 - 2 = 0 ✓ (đúng, vectơ pháp tuyến hai đường vuông góc thì vuông góc nhau).' WHERE id = 'a956d7c6-f3f5-4ba9-91e5-9b9cea41e8de';
UPDATE questions SET noi_dung = 'Cho bất phương trình x − 2y > 3. Cặp số nào KHÔNG là nghiệm? Giải thích ngắn. A. (5; 0) B. (4; 0) C. (1; 2) D. (7; 1)' WHERE id = 'a9b229ec-57b4-4712-94ad-d424ef0a36ae';
UPDATE questions SET noi_dung = 'phương trình 2x² + 2y² - 8x + 4y - 6 = 0 có phải đường tròn không? Nếu có, tìm tâm và bán kính.' WHERE id = 'a9ff5e2a-fdb7-4d54-971c-8d6c7f4330d3';
UPDATE questions SET noi_dung = 'Cho phương trình (m+1)x² + (m+1)y² - 4x + 2y - 1 = 0. Tìm m để đây là phương trình đường tròn.' WHERE id = 'aaa7e1c0-5976-4e11-907c-1d388f853e09';
UPDATE questions SET distractors = '[{"phuong_an":"x/(-2) + y/4 = 1","quan_niem_sai":"Đảo vai trò a và b"},{"phuong_an":"x/4 + y/2 = 1","quan_niem_sai":"Bỏ dấu âm của b"},{"phuong_an":"4x - 2y = 1","quan_niem_sai":"Nhầm dạng đoạn chắn với phương trình tổng quát (đặt a, b làm hệ số)"}]'::jsonb WHERE id = 'aba93deb-9c1a-4502-91d5-4a4442d4b0fb';
UPDATE questions SET noi_dung = 'Một bạn hỏi: ''khoảng tứ phân vị có mối LIÊN HỆ gì với việc PHÁT HIỆN GIÁ TRỊ BẤT THƯỜNG (outlier) trong DỮ LIỆU, một CHỦ ĐỀ sẽ HỌC Ở NODE tiếp theo?'' Giải thích cho bạn (dựa trên HIỂU BIẾT SƠ BỘ, không CẦN CHI TIẾT). (Hỏi kèm độ tự tin 1–3)', dap_an = 'khoảng tứ phân vị (đo ''ĐỘ RỘNG'' của 50% dữ liệu Ở GIỮA, PHẦN ''ĐIỂN HÌNH'' NHẤT của dữ liệu) THƯỜNG được sử DỤNG như một ''THƯỚC ĐO CHUẨN'' để XÁC ĐỊNH GIỚI HẠN ''HỢP LÝ'' cho dữ liệu; một QUY TẮC PHỔ BIẾN (sẽ HỌC CHI TIẾT Ở NODE tiếp theo) là: bất KỲ giá TRỊ NÀO ''CÁCH XA'' Q1 hoặc Q3 một KHOẢNG LỚN HƠN MỘT SỐ LẦN khoảng tứ phân vị NHẤT ĐỊNH (THƯỜNG là 1,5 lần khoảng tứ phân vị) có THỂ được XEM là ''GIÁ TRỊ BẤT THƯỜNG'' (outlier) — Ý TƯỞNG CƠ BẢN: nếu MỘT giá TRỊ ''CÁCH XA'' quá NHIỀU so với ''VÙNG ĐIỂN HÌNH'' (khoảng Q1 đến Q3) của dữ liệu, nó CÓ THỂ là một TRƯỜNG HỢP ''KHÔNG BÌNH THƯỜNG'' (do LỖI ĐO ĐẠC, hoặc THỰC SỰ là một TRƯỜNG HỢP ĐẶC BIỆT CẦN CHÚ Ý); khoảng tứ phân vị CUNG CẤP ''THƯỚC ĐO CHUẨN'' (dựa trên chính DỮ LIỆU đang XÉT, KHÔNG PHẢI một NGƯỠNG CỐ ĐỊNH TÙY Ý) để XÁC ĐỊNH ''THẾ NÀO là QUÁ XA'' MỘT CÁCH KHÁCH QUAN.', loi_giai = 'Đây là một GIỚI THIỆU NGẮN GỌN về ỨNG DỤNG QUAN TRỌNG của khoảng tứ phân vị trong việc PHÁT HIỆN GIÁ TRỊ BẤT THƯỜNG, một chủ đề sẽ được KHAI THÁC CHI TIẾT Ở NODE TIẾP THEO (C05), cho THẤY khoảng tứ phân vị KHÔNG CHỈ là MỘT THƯỚC ĐO ĐỘ PHÂN TÁN ĐƠN THUẦN, mà CÒN là CÔNG CỤ NỀN TẢNG cho MỘT KỸ THUẬT PHÂN TÍCH DỮ LIỆU QUAN TRỌNG KHÁC.' WHERE id = 'ac163432-5a3e-4586-b38d-7f08aab2508b';
UPDATE questions SET noi_dung = 'Viết phương trình đường tròn tiếp xúc với CẢ HAI trục toạ độ và đi qua điểm A(2; 1).', distractors = '[{"phuong_an":"Chỉ (x - 1)² + (y - 1)² = 1","quan_niem_sai":"Giải phương trình bậc hai nhưng bỏ một nghiệm"},{"phuong_an":"(x - 2)² + (y - 1)² = 4","quan_niem_sai":"Lấy luôn điểm A làm tâm"},{"phuong_an":"(x - 3)² + (y - 3)² = 9","quan_niem_sai":"Giải sai phương trình bậc hai theo R"}]'::jsonb WHERE id = 'ae0766ab-a3fa-4e6c-8059-7fcd91017de5';
UPDATE questions SET noi_dung = 'Bài làm: ''Cho hệ ⎧ x + y ≤ 4 · ⎨ 2x + y ≤ 6 · ⎩ x ≥ 0, y ≥ 0. Tìm giá trị lớn nhất của F = 3x + 2y. Tôi giải các cặp bờ, được 6 giao điểm: (0;0), (4;0), (0;4), (3;0), (0;6), (2;2). Tính F tại cả 6 điểm: F(0;0) = 0 · F(4;0) = 12 · F(0;4) = 8 · F(3;0) = 9 · F(0;6) = 12 · F(2;2) = 10. Kết luận: giá trị lớn nhất = 12, đạt tại (4; 0) hoặc (0; 6).'' Tìm và sửa lỗi.', dap_an = 'Phần tính F ĐÚNG HẾT! ✓ (6 giá trị đều chính xác). LỖI: DÙNG ĐỈNH SAI — KHÔNG SÀNG LỌC! (bệnh B05-① quay lại!) Bạn ấy lấy CẢ 6 giao điểm làm đỉnh — NHƯNG chỉ 4 điểm THUỘC miền nghiệm! SÀNG LỌC: (0;0) ✓ ĐỈNH | (4;0): 4 ≤ 4 ✓ NHƯNG 2(4)+0 = 8 ≤ 6? SAI! ✗ ⇒ LOẠI! | (0;4): 4 ≤ 4 ✓, 4 ≤ 6 ✓ ⇒ ĐỈNH | (3;0): 3 ≤ 4 ✓, 6 ≤ 6 ✓ ⇒ ĐỈNH | (0;6): 0+6 = 6 ≤ 4? SAI! ✗ ⇒ LOẠI! | (2;2): 4 ≤ 4 ✓, 6 ≤ 6 ✓ ⇒ ĐỈNH. TAI HOẠ: CẢ HAI ĐIỂM BỊ LOẠI ĐỀU CHO F = 12 — ĐÚNG LÀ ''giá trị lớn nhất'' MÀ BẠN ẤY CHỌN! ⇒ Bạn ấy lấy giá trị lớn nhất từ HAI ĐIỂM KHÔNG KHẢ THI! ⇒ Đáp án SAI HOÀN TOÀN! TÍNH LẠI — chỉ với 4 ĐỈNH THẬT: F(0;0) = 0 | F(3;0) = 3(3) + 2(0) = 9 | F(2;2) = 3(2) + 2(2) = 6 + 4 = 10 ⬅️ LỚN NHẤT! | F(0;4) = 3(0) + 2(4) = 8 ⇒ giá trị lớn nhất = 10, đạt tại đỉnh (2; 2) — KHÔNG PHẢI 12! ✓ (giá trị nhỏ nhất = 0 tại O(0;0))', loi_giai = 'HẬU QUẢ NGHIÊM TRỌNG — nếu đây là bài toán THỰC TẾ: giả sử F = lợi nhuận (triệu đồng), các bất phương trình = ràng buộc nguyên liệu. Bài làm SAI → phương án (4;0), lợi nhuận ''dự kiến'' 12 triệu ⇒ NHƯNG PHƯƠNG ÁN NÀY KHÔNG KHẢ THI (thiếu nguyên liệu!) ⇒ KHÔNG BAO GIỜ đạt được! | Cách đúng → phương án (2;2), lợi nhuận THẬT 10 triệu ✓ ⇒ Doanh nghiệp lập kế hoạch theo phương án BẤT KHẢ THI ⇒ PHÁ SẢN! QUY TẮC VÀNG: ''TÍNH F TẠI ĐỈNH — nhưng phải là ĐỈNH THẬT!'' Trước khi tính F, BẮT BUỘC SÀNG LỌC giao điểm! (B05-③) Rubric: Chưa đạt (không thấy sai vì phép tính F đều đúng!) | Cần cố gắng (nói ''phải sàng lọc'' nhưng không chỉ ra được điểm nào bị loại) | Đạt (sàng lọc đúng, loại (4;0) và (0;6), tính lại giá trị lớn nhất = 10 tại (2;2)) | Tốt (đủ ý trên VÀ chỉ ra TAI HOẠ (cả hai điểm bị loại đều cho F = 12 — chính là ''giá trị lớn nhất'' sai!) VÀ nêu hậu quả thực tế (lập kế hoạch theo phương án BẤT KHẢ THI!) VÀ gọi tên gốc bệnh B05-①). CÂU QUAN TRỌNG NHẤT NODE — và là câu ''BÁO THÙ'' của B05! Thiết kế tàn nhẫn: cả HAI điểm bị loại đều cho F = 12 — CAO HƠN giá trị lớn nhất thật (10)! ⇒ HS không sàng lọc sẽ CHẮC CHẮN ra đáp án sai!' WHERE id = 'aeda1201-2268-4400-9042-437c25549943';
UPDATE questions SET noi_dung = 'Đường cao của tam giác kẻ từ đỉnh A nhận vectơ nào làm vectơ pháp tuyến?', distractors = '[{"phuong_an":"Vectơ AB","quan_niem_sai":"AB là một cạnh kề, không vuông góc với đường cao từ A"},{"phuong_an":"Vectơ AC","quan_niem_sai":"AC cũng là cạnh kề, không phải cạnh đối"},{"phuong_an":"Vectơ BC nhưng làm vectơ chỉ phương","quan_niem_sai":"Nhầm vai trò: BC là vectơ pháp tuyến chứ không phải vectơ chỉ phương của đường cao"}]'::jsonb, loi_giai = 'Đường cao từ A vuông góc với cạnh đối BC ⇒ BC chính là vectơ pháp tuyến của đường cao đó.' WHERE id = 'b10ae571-40da-4b64-9951-d3146e22497d';
UPDATE questions SET dap_an = 'CÓ VẤN ĐỀ khi HAI mẫu có MỨC TRUNG BÌNH RẤT KHÁC NHAU (như VÍ DỤ ở CÂU 6, hai cổ PHIẾU có LỢI NHUẬN TRUNG BÌNH KHÁC BIỆT LỚN); trong TRƯỜNG HỢP này, SO SÁNH TRỰC TIẾP ĐỘ LỆCH CHUẨN ''TUYỆT ĐỐI'' có THỂ dẫn đến KẾT LUẬN ''SAI LỆCH'' về RỦI RO/PHÂN TÁN TƯƠNG ĐỐI; CẦN dùng THÊM HỆ SỐ BIẾN THIÊN (CHUẨN HOÁ độ LỆCH CHUẨN theo TRUNG BÌNH) để có SO SÁNH CÔNG BẰNG và Ý NGHĨA HƠN trong NHỮNG TÌNH HUỐNG này; ĐỘ LỆCH CHUẨN ''TUYỆT ĐỐI'' PHÙ HỢP HƠN khi HAI mẫu CÓ TRUNG BÌNH TƯƠNG TỰ NHAU (như VÍ DỤ ở CÂU 4), nhưng KHÔNG PHẢI LUÔN ''TỐT NHẤT'' trong MỌI TRƯỜNG HỢP.', loi_giai = 'Đây là lỗi KHÁI QUÁT HOÁ QUÁ MỨC (''LUÔN TỐT NHẤT''), bỏ QUA VAI TRÒ QUAN TRỌNG của việc XEM XÉT TRUNG BÌNH khi QUYẾT ĐỊNH nên dùng ĐỘ LỆCH CHUẨN ''TUYỆT ĐỐI'' hay HỆ SỐ BIẾN THIÊN để SO SÁNH.' WHERE id = 'b27e8515-20b2-4b69-abe2-c70e993b425a';
UPDATE questions SET loi_giai = 'VÌ SAO? Xét x + y ≤ 4, lấy (4;0) TRÊN BỜ (vì 4+0 = 4). Thay vào: 4 ≤ 4? ĐÚNG ✓ ⇒ điểm trên bờ LÀ nghiệm ⇒ bờ thuộc miền ⇒ NÉT LIỀN! Đổi thành x + y < 4: 4 < 4? SAI ✗ ⇒ bờ không thuộc ⇒ NÉT ĐỨT! CÁCH KIỂM TỰ THÂN (không cần nhớ mẹo): ① lấy MỘT ĐIỂM trên bờ (vd giao với Ox) ② thay vào bất phương trình gốc ③ ra ĐÚNG → nét LIỀN · ra SAI → nét ĐỨT ✓. Rubric: Chưa đạt (chỉ học thuộc ''≤ thì liền'') | Đạt (nêu quy tắc VÀ giải thích bờ thuộc/không thuộc miền, có mẹo nhớ) | Tốt (đủ ý trên VÀ dạy CÁCH KIỂM TỰ THÂN bằng thử một điểm trên bờ — HS chỉ dạy mẹo mà không dạy cách tự kiểm là CHƯA ĐẠT, vì mẹo có thể quên nhưng cách kiểm thì LUÔN dùng được).' WHERE id = 'b44df56b-2aaa-450f-9ff7-ff58d10cbc33';
UPDATE questions SET noi_dung = 'phương trình chính tắc của elip có dạng:' WHERE id = 'b67e81bb-68b0-419f-90ff-ea1a21c9bcff';
UPDATE questions SET distractors = '[{"phuong_an":"Đúng, vectơ chỉ phương là duy nhất","quan_niem_sai":"Nhầm ''phương duy nhất'' với ''vectơ duy nhất''"},{"phuong_an":"Sai, vì có đúng hai vectơ chỉ phương ngược hướng","quan_niem_sai":"Chỉ nghĩ tới k = 1 và k = -1, bỏ sót mọi k khác"},{"phuong_an":"Sai, vì vectơ chỉ phương của đường thẳng là vectơ pháp tuyến","quan_niem_sai":"Đồng nhất hai khái niệm khác nhau"}]'::jsonb, loi_giai = 'Nếu u là vectơ chỉ phương của Δ thì mọi vectơ k·u (k ≠ 0) đều có giá song song/trùng với Δ, nên cũng là vectơ chỉ phương. Ví dụ Δ có vectơ chỉ phương (1;2) thì (2;4), (-1;-2), (0,5;1)... đều là vectơ chỉ phương. Điều duy nhất được xác định là PHƯƠNG, không phải một vectơ cụ thể.' WHERE id = 'b689e963-bfb2-4ead-b819-d4d1ad50799f';
UPDATE questions SET noi_dung = '(a) Dịch 4 câu sau thành bất phương trình (x = số sản phẩm A, y = số sản phẩm B): ① ''Sản xuất KHÔNG QUÁ 100 sản phẩm tổng cộng'' ② ''Sản xuất DƯỚI 100 sản phẩm tổng cộng'' ③ ''Số sản phẩm A ÍT NHẤT GẤP ĐÔI số sản phẩm B'' ④ ''Số sản phẩm A NHIỀU HƠN số sản phẩm B ít nhất 10 cái'' (b) Giải thích KHÁC BIỆT giữa ① và ② (cho ví dụ số cụ thể).' WHERE id = 'b79c4fc0-b4db-4d72-a73c-f9abf15efa12';
UPDATE questions SET noi_dung = 'Nghiệm của bất phương trình bậc nhất HAI ẩn ax + by ≤ c là: A. Một số thực x B. Một CẶP SỐ (x₀; y₀) làm cho bất phương trình trở thành mệnh đề ĐÚNG C. Một cặp số bất kì D. Giá trị của c', distractors = '[{"phuong_an":"A","quan_niem_sai":"Nhầm với bất phương trình MỘT ẩn (nghiệm là một số)"},{"phuong_an":"C","quan_niem_sai":"Thiếu điều kiện ''làm bất phương trình ĐÚNG'' — không phải cặp nào cũng là nghiệm!"},{"phuong_an":"D","quan_niem_sai":"Không hiểu khái niệm nghiệm"}]'::jsonb, loi_giai = 'Nghiệm là CẶP SỐ (x₀; y₀) làm bất phương trình thành mệnh đề ĐÚNG.' WHERE id = 'bb028fdf-d5dc-4792-a6cc-10c29e5aa2e2';
UPDATE questions SET noi_dung = 'Miền nghiệm là TAM GIÁC có 3 đỉnh: O(0; 0), (4; 0), (0; 3). Cho hàm mục tiêu F = 2x + 5y. Tìm giá trị lớn nhất của F trên miền.', distractors = '[{"phuong_an":"8","quan_niem_sai":"Nhầm, chọn giá trị tại (4;0) (có lẽ nghĩ ''x lớn hơn thì F lớn hơn'')"},{"phuong_an":"0","quan_niem_sai":"Lấy giá trị nhỏ nhất thay vì giá trị lớn nhất! (đọc nhầm đề!)"},{"phuong_an":"23","quan_niem_sai":"Cộng bừa các giá trị: 0 + 8 + 15 = 23"}]'::jsonb, loi_giai = 'BẢNG TÍNH F TẠI TỪNG ĐỈNH: O(0;0): 2(0) + 5(0) = 0 | (4;0): 2(4) + 5(0) = 8 | (0;3): 2(0) + 5(3) = 15 ⬅️ LỚN NHẤT! ⇒ giá trị lớn nhất = 15, đạt tại đỉnh (0; 3) ✓ (giá trị nhỏ nhất = 0 tại O(0;0)). BÀI HỌC: cùng một miền, đổi hàm F ⇒ đỉnh tối ưu ĐỔI! (F = 5x+2y → max = 20 tại (4;0) · F = x+y → max = 4 tại (4;0)) ⇒ KHÔNG có đỉnh nào ''luôn luôn tốt nhất'' — phải TÍNH HẾT!' WHERE id = 'bc5be05e-e47a-40ab-9e4d-aa814c4b131e';
UPDATE questions SET distractors = '[{"phuong_an":"Có khác, vì vectơ pháp tuyến ngược hướng cho góc bù nhau","quan_niem_sai":"Quên trị tuyệt đối trong công thức"},{"phuong_an":"Có khác, phải luôn chọn vectơ pháp tuyến có thành phần đầu dương","quan_niem_sai":"Đặt ra quy tắc thừa, không có trong SGK"},{"phuong_an":"Không khác, vì góc luôn bằng 90°","quan_niem_sai":"Kết luận đúng nhưng lí do hoàn toàn sai"}]'::jsonb, loi_giai = 'Giả sử đường thứ hai có vectơ pháp tuyến m. Nếu dùng n = (1;1): cos φ = |n·m|/(|n||m|). Nếu dùng n'' = (-1;-1) = -n: n''·m = -(n·m), nhưng |n''·m| = |n·m| và |n''| = |n|. Vậy giá trị cos φ KHÔNG đổi. Chính trị tuyệt đối đảm bảo kết quả không phụ thuộc cách chọn hướng vectơ pháp tuyến — và đó cũng là lí do góc giữa hai đường thẳng luôn thuộc [0°; 90°], khác với góc giữa hai vectơ.' WHERE id = 'be124ca0-604b-496e-a1cb-aa157e660d08';
UPDATE questions SET noi_dung = 'Để tìm giá trị lớn nhất/giá trị nhỏ nhất của F = ax + by, ta tính giá trị của F tại các ___ của miền nghiệm.' WHERE id = 'bee9e646-ab45-4d34-bdd2-33fbac3c2cbc';
UPDATE questions SET loi_giai = 'VÌ SAO (4;0) VÀ (0;6) BỊ LOẠI? Chúng nằm TRÊN BỜ NÀY nhưng VƯỢT RA NGOÀI BỜ KIA! (4;0): nằm trên bờ x+y = 4 ✓ NHƯNG 2(4) + 0 = 8 > 6 ⇒ VƯỢT bờ 2x+y = 6! ⇒ nằm NGOÀI miền! | (0;6): nằm trên bờ 2x+y = 6 ✓ NHƯNG 0 + 6 = 6 > 4 ⇒ VƯỢT bờ x+y = 4! ⇒ NGOÀI miền! HÌNH HỌC: miền nghiệm = TỨ GIÁC có 4 đỉnh (ngược chiều kim đồng hồ): O(0;0) → (3;0) → (2;2) → (0;4) → về O. Đỉnh (2;2) là giao của HAI BỜ NGHIÊNG — ''góc gãy'' của miền! KIỂM CHỨNG: (1;1) trong miền: 1+1 = 2 ≤ 4 ✓, 2(1)+1 = 3 ≤ 6 ✓, ✓, ✓ ⇒ THOẢ CẢ 4 ✓ QUY TẮC VÀNG: ''Giao điểm ≠ Đỉnh! Phải SÀNG LỌC — thay vào CẢ HỆ!'' Số bờ 3 → C(3,2) = 3 giao điểm → thường 3 đỉnh | 4 → C(4,2) = 6 → thường 4 đỉnh (loại 2!) | 5 → C(5,2) = 10 → thường 5 đỉnh (loại 5!). Càng nhiều bất phương trình, càng nhiều giao điểm BỊ LOẠI! Rubric: Chưa đạt (nghĩ 6 giao điểm = 6 đỉnh) | Cần cố gắng (nói ''phải kiểm'' nhưng không sàng lọc đủ 6 điểm) | Đạt (sàng lọc đủ 6 giao điểm, loại đúng (4;0) và (0;6), kết luận 4 đỉnh) | Tốt (đủ ý trên VÀ giải thích VÌ SAO 2 điểm đó bị loại (nằm trên bờ này nhưng VƯỢT bờ kia) VÀ nêu quy tắc C(n,2) giao điểm nhưng chỉ MỘT SỐ là đỉnh VÀ mô tả miền là TỨ GIÁC với thứ tự đỉnh). CÂU QUAN TRỌNG NHẤT NODE — bài làm đúng 100% phần đại số nhưng SAI Ở TƯ DUY (quên bước sàng lọc)! Dạy: ''Tính đúng chưa đủ — phải HIỂU mình đang tìm gì!''' WHERE id = 'befc64f2-823b-4e4e-bd01-86dba87b35c5';
UPDATE questions SET noi_dung = 'Học sinh viết: ''Đường thẳng d: 2x + 5y - 1 = 0 có vectơ chỉ phương là u = (2; 5).'' Hãy tìm lỗi và sửa.', dap_an = 'Sai. (2; 5) là vectơ pháp tuyến của d, không phải vectơ chỉ phương. vectơ chỉ phương đúng là u = (5; -2) (hoặc (-5; 2)).', distractors = '[{"phuong_an":"Không sai, u = (2; 5) đúng","quan_niem_sai":"Đồng nhất vectơ chỉ phương với vectơ pháp tuyến"},{"phuong_an":"Sai, vectơ chỉ phương đúng là (-2; -5)","quan_niem_sai":"Chỉ đổi dấu mà không hoán vị"},{"phuong_an":"Sai, vectơ chỉ phương đúng là (2; -5)","quan_niem_sai":"Đổi dấu một thành phần nhưng không hoán vị"}]'::jsonb, loi_giai = 'Với phương trình tổng quát Ax+By+C=0, n=(A;B) là vectơ pháp tuyến. vectơ chỉ phương phải vuông góc với n: u = (B; -A) = (5; -2). Kiểm tra: 2·5 + 5·(-2) = 0 ✓.' WHERE id = 'bf2dc1d0-5b7d-43ec-b5b0-5d5a931e3892';
UPDATE questions SET noi_dung = 'Quy tắc PHỔ BIẾN để xác định GIÁ TRỊ BẤT THƯỜNG (outlier) dựa trên khoảng tứ phân vị là gì?', dap_an = 'Một giá trị x được coi là BẤT THƯỜNG nếu \(x<Q1-1{,}5\times khoảng tứ phân vị\) hoặc \(x>Q3+1{,}5\times khoảng tứ phân vị\).', distractors = '[{"phuong_an":"Một giá trị x BẤT THƯỜNG nếu x LỚN HƠN Q3 (không cần thêm HỆ SỐ)","quan_niem_sai":"THIẾU HỆ SỐ 1,5×khoảng tứ phân vị trong CÔNG THỨC; CHỈ đơn GIẢN ''LỚN HƠN Q3'' sẽ COI 25% dữ liệu (PHẦN TỨ CAO NHẤT) là ''BẤT THƯỜNG'', một ĐỊNH NGHĨA KHÔNG HỢP LÝ."},{"phuong_an":"Một giá trị x BẤT THƯỜNG nếu x nằm NGOÀI khoảng [giá trị NHỎ NHẤT, giá trị LỚN NHẤT]","quan_niem_sai":"KHÔNG CÓ giá trị NÀO có THỂ nằm NGOÀI khoảng [NHỎ NHẤT, LỚN NHẤT] của CHÍNH mẫu đó (theo ĐỊNH NGHĨA), nên ĐÂY KHÔNG PHẢI một QUY TẮC CÓ Ý NGHĨA để PHÁT HIỆN BẤT THƯỜNG."},{"phuong_an":"Một giá trị x BẤT THƯỜNG nếu KHÁC với SỐ TRUNG BÌNH","quan_niem_sai":"QUÁ MƠ HỒ và KHÔNG CÓ TIÊU CHÍ ĐỊNH LƯỢNG RÕ RÀNG; HẦU HẾT MỌI giá trị (TRỪ chính SỐ TRUNG BÌNH) đều ''KHÁC'' với TRUNG BÌNH Ở MỘT MỨC ĐỘ NÀO ĐÓ, đây KHÔNG PHẢI một TIÊU CHÍ HỢP LÝ."}]'::jsonb, loi_giai = 'Đây là QUY TẮC CHUẨN (1,5×khoảng tứ phân vị) được sử DỤNG RỘNG RÃI trong THỐNG KÊ để XÁC ĐỊNH các giá trị NẰM ''QUÁ XA'' so với PHẦN ''ĐIỂN HÌNH'' của dữ liệu.' WHERE id = 'c059ee93-0dae-4231-ae44-f7c2732e7c0c';
UPDATE questions SET noi_dung = 'Một bạn tính \(\sqrt{2}\times\sqrt{8}\) bằng cách: BẤM máy tính cầm tay để có \(\sqrt{2}\approx1{,}41421\) và \(\sqrt{8}\approx2{,}82843\), rồi NHÂN HAI GIÁ TRỊ ĐÃ LÀM TRÒN này lại để được KẾT QUẢ CUỐI CÙNG. Đánh giá cách làm này, so sánh với việc TÍNH TRỰC TIẾP \(\sqrt{2}\times\sqrt{8}=\sqrt{16}=4\) (một SỐ NGUYÊN, KHÔNG CẦN xấp xỉ). (Hỏi kèm độ tự tin 1–3)', dap_an = 'Cách làm của bạn CÓ THỂ cho ra kết quả GẦN ĐÚNG (ví dụ \(1{,}41421\times2{,}82843\approx3{,}99999\), rất GẦN với 4 nhưng KHÔNG HOÀN TOÀN CHÍNH XÁC do LÀM TRÒN TRUNG GIAN), trong khi PHƯƠNG PHÁP TỐT HƠN là NHẬN RA (bằng KIẾN THỨC ĐẠI SỐ về CĂN THỨC: \(\sqrt{a}\times\sqrt{b}=\sqrt{ab}\)) rằng \(\sqrt{2}\times\sqrt{8}=\sqrt{2\times8}=\sqrt{16}=4\) — một GIÁ TRỊ CHÍNH XÁC TUYỆT ĐỐI (số NGUYÊN), KHÔNG CẦN dùng đến GIÁ TRỊ GẦN ĐÚNG của \(\sqrt{2}\) và \(\sqrt{8}\) RIÊNG LẺ; đây là một VÍ DỤ cho thấy đôi khi việc ÁP DỤNG KIẾN THỨC ĐẠI SỐ (rút gọn TRƯỚC KHI tính SỐ) giúp có được KẾT QUẢ CHÍNH XÁC HƠN (và ĐƠN GIẢN HƠN) so với việc DÙNG máy tính cầm tay tính TỪNG PHẦN riêng lẻ rồi NHÂN các GIÁ TRỊ GẦN ĐÚNG lại.', loi_giai = 'Đây là một BÀI HỌC QUAN TRỌNG: TRƯỚC KHI dùng máy tính cầm tay để tính TOÁN với các SỐ VÔ TỈ (như căn thức), NÊN kiểm tra xem có thể RÚT GỌN BẰNG ĐẠI SỐ TRƯỚC (có thể cho ra KẾT QUẢ CHÍNH XÁC, ĐƠN GIẢN hơn) thay vì VỘI VÀNG dùng máy tính cầm tay tính từng phần rồi NHÂN các giá trị GẦN ĐÚNG.' WHERE id = 'c1953763-4f6b-4b25-a7b5-9c28ae8d7696';
UPDATE questions SET distractors = '[{"phuong_an":"Sai, đường thẳng đứng x = m không viết được","quan_niem_sai":"Không nhận ra x - m = 0 là phương trình tổng quát với B = 0"},{"phuong_an":"Sai, chỉ đường thẳng có hệ số góc mới viết được","quan_niem_sai":"Nhầm phương trình tổng quát với dạng y = kx + m"},{"phuong_an":"Sai, cần thêm điều kiện C ≠ 0","quan_niem_sai":"Thêm điều kiện không cần thiết"}]'::jsonb, loi_giai = 'Mọi đường thẳng trong mặt phẳng đều có vectơ pháp tuyến n = (A;B) ≠ 0, nên luôn viết được phương trình tổng quát.' WHERE id = 'c1bbb544-79d1-48b0-a4e7-b493ed0f9662';
UPDATE questions SET noi_dung = 'Đường thẳng Δ đi qua A(1; 2) và song song với đường thẳng d: x - 3y + 5 = 0. Tìm một vectơ chỉ phương của Δ.', distractors = '[{"phuong_an":"u = (1; -3)","quan_niem_sai":"Lấy hệ số phương trình tổng quát làm vectơ chỉ phương (thực ra là vectơ pháp tuyến)"},{"phuong_an":"u = (1; 3)","quan_niem_sai":"Bỏ dấu âm rồi lấy làm vectơ chỉ phương"},{"phuong_an":"u = (1; 2)","quan_niem_sai":"Lấy toạ độ điểm A làm vectơ chỉ phương"}]'::jsonb, loi_giai = 'Δ // d nên Δ và d có cùng phương. vectơ pháp tuyến của d là n = (1; -3) ⇒ vectơ chỉ phương của d (và của Δ) là u = (-3; -1), rút gọn u = (3; 1). Kiểm tra: 1·3 + (-3)·1 = 0 ✓.' WHERE id = 'c1e8aeef-7f80-4515-9984-65b058a24008';
UPDATE questions SET noi_dung = 'Cho tam giác ABC với A(1; 1), B(5; 3), C(3; 7). Tìm vectơ pháp tuyến của đường cao kẻ từ A và viết phương trình tổng quát đường cao đó.', dap_an = 'n = BC = (-2; 4); phương trình tổng quát: -2(x-1) + 4(y-1) = 0 ⇔ -x + 2y - 1 = 0 ⇔ x - 2y + 1 = 0.', distractors = '[{"phuong_an":"n = BC = (-2; 4), phương trình tổng quát: 4x + 2y - 6 = 0","quan_niem_sai":"Dùng BC làm vectơ chỉ phương thay vì vectơ pháp tuyến của đường cao"},{"phuong_an":"n = AB = (4; 2), phương trình tổng quát: 4x + 2y - 6 = 0","quan_niem_sai":"Nhầm đường cao từ A vuông góc với AB"},{"phuong_an":"n = BC = (2; -4), phương trình tổng quát: x - 2y - 1 = 0","quan_niem_sai":"Đúng vectơ pháp tuyến nhưng sai dấu hệ số tự do khi khai triển"}]'::jsonb, loi_giai = 'Đường cao từ A vuông góc BC nên nhận BC làm vectơ pháp tuyến. BC = (3-5; 7-3) = (-2; 4). phương trình tổng quát: -2(x-1) + 4(y-1) = 0 ⇔ -2x + 4y - 2 = 0 ⇔ x - 2y + 1 = 0. Kiểm tra A(1;1): 1 - 2 + 1 = 0 ✓.' WHERE id = 'c21222a8-ecbd-4488-b9dd-49816640972e';
UPDATE questions SET noi_dung = 'Viết phương trình chính tắc của hypebol có tiêu điểm F(5; 0) và một tiệm cận y = (3/4)x.', loi_giai = 'c = 5 ⇒ c² = 25 = a² + b². Tiệm cận: b/a = 3/4 ⇒ b = (3/4)a ⇒ b² = (9/16)a². Thay: a² + (9/16)a² = 25 ⇔ (25/16)a² = 25 ⇔ a² = 16 ⇒ a = 4, b² = 9. phương trình: x²/16 - y²/9 = 1. Kiểm: b/a = 3/4 ✓; c² = 16 + 9 = 25 ✓.' WHERE id = 'c2255f30-389b-4e1d-bb62-8d6a6623b9e1';
UPDATE questions SET noi_dung = 'Khi vẽ bờ của bất phương trình 2x + y < 5, ta vẽ đường thẳng 2x + y = 5 bằng: A. Nét ĐỨT (vì bờ KHÔNG thuộc miền nghiệm) B. Nét liền C. Nét liền, tô đậm D. Không cần vẽ đường thẳng' WHERE id = 'c23b7e2a-7646-4d2c-8486-c8b32436d95e';
UPDATE questions SET noi_dung = 'Cửa hàng bán x kg gạo (20 nghìn/kg) và y kg đường (25 nghìn/kg). Khách có 200 nghìn. Biểu diễn miền các phương án mua hàng khả thi. B1 — ĐẶT ẨN & NÊU ĐƠN VỊ. B2 — LẬP bất phương trình ràng buộc. B3 — THÊM ĐIỀU KIỆN ẨN. B4 — BIỂU DIỄN MIỀN.' WHERE id = 'c2aed290-d72c-49e2-9dce-ef5c757dc483';
UPDATE questions SET noi_dung = 'Tìm m để vectơ n = (m; 3) là vectơ pháp tuyến của đường thẳng có vectơ chỉ phương u = (6; -4).', distractors = '[{"phuong_an":"m = -2","quan_niem_sai":"Sai dấu khi chuyển vế"},{"phuong_an":"m = 6","quan_niem_sai":"Cho rằng vectơ pháp tuyến cùng phương vectơ chỉ phương"},{"phuong_an":"m = 1/2","quan_niem_sai":"Nhầm điều kiện thành m/6 = 3/4"}]'::jsonb WHERE id = 'c330ece0-b9dc-4777-8928-309c1d03ff1a';
UPDATE questions SET loi_giai = 'Điều kiện để là đường tròn: a² + b² - c > 0. Ở đây = -5 < 0 ⇒ phương trình vô nghiệm (không có điểm nào thoả). Học sinh vẫn cố tính √(-5) mà không dừng lại kiểm tra điều kiện — đó là lỗi.' WHERE id = 'c3b68ba8-b186-40bb-b715-2a43ca2fa14d';
UPDATE questions SET noi_dung = 'Viết phương trình tổng quát đường thẳng song song với d: x - 2y + 3 = 0 và đi qua giao điểm của d₁: x + y - 4 = 0 với d₂: 2x - y + 1 = 0.', distractors = '[{"phuong_an":"x - 2y + 3 = 0","quan_niem_sai":"Chép nguyên d — nhưng I(1;3) không thuộc d (1-6+3 = -2 ≠ 0)"},{"phuong_an":"2x + y - 5 = 0","quan_niem_sai":"Dùng vectơ pháp tuyến vuông góc ⇒ ra đường vuông góc với d"},{"phuong_an":"x - 2y - 5 = 0","quan_niem_sai":"Sai dấu hệ số tự do khi khai triển"}]'::jsonb, loi_giai = 'Giao điểm d₁ ∩ d₂: cộng hai phương trình ⇒ 3x - 3 = 0 ⇒ x = 1; từ d₁: y = 3 ⇒ I(1; 3). Đường cần tìm song song d nên nhận vectơ pháp tuyến (1; -2): 1(x-1) - 2(y-3) = 0 ⇔ x - 2y + 5 = 0. Kiểm tra I(1;3): 1 - 6 + 5 = 0 ✓. Hệ số tự do 5 ≠ 3 nên không trùng d ✓.' WHERE id = 'c403ac36-4f0b-46fe-8ac8-bd4dac60eade';
UPDATE questions SET noi_dung = 'Lập phương trình đường tròn ngoại tiếp tam giác có ba đỉnh A(0; 0), B(6; 0), C(0; 8).' WHERE id = 'c54453a2-bd9a-47aa-977d-543a53891541';
UPDATE questions SET noi_dung = 'Tính diện tích hình tròn bán kính \(r=4{,}5\)cm (dùng \(\pi\) trên máy tính cầm tay, không làm tròn \(\pi\) trước), sau đó quy tròn kết quả đến hàng phần chục. (Hỏi kèm độ tự tin 1–3)', distractors = '[{"phuong_an":"63,585 cm² (dùng \\(\\pi\\approx3{,}14\\) làm tròn TRƯỚC khi tính, thay vì dùng giá trị chính xác của máy tính cầm tay)","quan_niem_sai":"Sử dụng giá trị \\(\\pi\\) ĐÃ LÀM TRÒN SỚM (3,14) thay vì GIÁ TRỊ CHÍNH XÁC HƠN mà máy tính cầm tay cung cấp, dẫn đến kết quả CUỐI CÙNG có thể SAI LỆCH so với việc GIỮ nguyên độ chính xác của \\(\\pi\\) đến bước cuối."}]'::jsonb WHERE id = 'c5ac6d26-5fd0-4fbd-9eb3-ed67f0d60581';
UPDATE questions SET noi_dung = 'Cho (C): (x-1)² + (y-1)² = 4. Viết phương trình các tiếp tuyến của (C) song song với đường thẳng d: 3x + 4y - 1 = 0.', distractors = '[{"phuong_an":"Chỉ 3x + 4y - 17 = 0","quan_niem_sai":"Bỏ một nghiệm của phương trình trị tuyệt đối"},{"phuong_an":"4x - 3y + C = 0","quan_niem_sai":"Dùng vectơ pháp tuyến vuông góc ⇒ ra tiếp tuyến vuông góc d, không song song"},{"phuong_an":"3x + 4y + 10 = 0 hoặc 3x + 4y - 10 = 0","quan_niem_sai":"Quên cộng 7 (giá trị tại tâm) khi lập phương trình trị tuyệt đối"}]'::jsonb WHERE id = 'c5e13494-2fa1-4ac3-91bf-1a47968ae877';
UPDATE questions SET distractors = '[{"phuong_an":"A","quan_niem_sai":"Có x² → BẬC HAI, không phải bậc nhất"},{"phuong_an":"C","quan_niem_sai":"Dấu ''='' → đó là PHƯƠNG TRÌNH, không phải bất phương trình"},{"phuong_an":"D","quan_niem_sai":"Chỉ có một ẩn x → bất phương trình bậc nhất MỘT ẩn"}]'::jsonb WHERE id = 'c6794cad-5cff-443a-8dd6-bf71b06de194';
UPDATE questions SET noi_dung = 'Bài làm: ''Kiểm tra cặp (1; 4) có là nghiệm của hệ: ⎧ x + y ≤ 6 ⎨ 2x + 3y ≤ 12 ⎩ x ≥ 0 Tôi kiểm bất phương trình đầu tiên: 1 + 4 = 5. Hỏi 5 ≤ 6? ⇒ ĐÚNG! Vậy (1; 4) LÀ NGHIỆM của hệ.'' Tìm và sửa lỗi.', dap_an = 'LỖI: KIỂM THIẾU bất phương trình — DỪNG QUÁ SỚM! Bạn ấy chỉ kiểm BPT① rồi kết luận luôn, trong khi hệ có BA bất phương trình! KIỂM ĐẦY ĐỦ: ① x + y ≤ 6: 1 + 4 = 5 ≤ 6 ✓ ĐÚNG | ② 2x + 3y ≤ 12: 2(1) + 3(4) = 2 + 12 = 14. Hỏi 14 ≤ 12? SAI! ✗ | ③ x ≥ 0: 1 ≥ 0 ✓ ĐÚNG. ⇒ BPT② KHÔNG THOẢ (14 > 12) ⇒ (1; 4) KHÔNG PHẢI nghiệm của hệ! ✗ — NGƯỢC HOÀN TOÀN với kết luận của bạn ấy! CÁCH ĐÚNG: ① 5 ≤ 6 ✓ ② 14 ≤ 12? SAI ⇒ DỪNG NGAY ĐƯỢC! ⇒ KẾT LUẬN: (1;4) KHÔNG là nghiệm ✗', loi_giai = 'QUY TẮC DỪNG — bạn ấy dừng SAI CHỖ: kiểm ra SAI ✗ ⇒ DỪNG NGAY ĐƯỢC (chỉ cần 1 bất phương trình sai ⇒ chắc chắn không phải nghiệm hệ) | kiểm ra ĐÚNG ✓ ⇒ KHÔNG ĐƯỢC DỪNG (phải kiểm HẾT — biết đâu bất phương trình sau lại sai!). Bạn ấy dừng khi ra ĐÚNG ⇒ SAI QUY TẮC! GỐC BỆNH: đây là MIS-D01-D02-01 của Chương I quay lại — hiểu hệ là phép HỢP ∪ (''thoả ít nhất một bất phương trình là được'') thay vì phép GIAO ∩ (''thoả CẢ các bất phương trình''). NEO NHỚ (từ D01-Q10): dấu ⎧ (ngoặc nhọn) = MÁI NHÀ ⌂ = phép GIAO ∩ = CHE BỚT, chỉ giữ phần CHUNG! ĐỐI CHỨNG: thử (2;2): ① 4 ≤ 6 ✓ ② 4 + 6 = 10 ≤ 12 ✓ ③ 2 ≥ 0 ✓ ⇒ THOẢ CẢ BA ⇒ LÀ NGHIỆM ✓. Rubric: Chưa đạt (không thấy sai vì BPT① quả thật thoả) | Cần cố gắng (nói ''phải kiểm hết'' nhưng không tính ra BPT② sai) | Đạt (kiểm đủ 3 bất phương trình, chỉ ra BPT② KHÔNG thoả (14 > 12), kết luận KHÔNG phải nghiệm) | Tốt (đủ ý trên VÀ phát biểu QUY TẮC DỪNG (ra SAI → dừng được · ra ĐÚNG → phải kiểm tiếp) VÀ gọi tên gốc bệnh — hiểu hệ là HỢP thay vì GIAO, liên hệ MIS-D01-D02-01 Chương I). CÂU QUAN TRỌNG NHẤT NODE — dạy QUY TẮC DỪNG BẤT ĐỐI XỨNG, một trong những tư duy logic sâu nhất!' WHERE id = 'c7ca660e-6b3d-48d2-b20f-2b4db69d21d1';
UPDATE questions SET noi_dung = 'Bé Na hỏi: ''Cô ơi, em đọc đề bài hiểu hết, nhưng đến lúc VIẾT THÀNH bất phương trình thì em tắc tịt! Có cách nào làm từng bước cho chắc không ạ?''', loi_giai = 'TỪ ĐIỂN DỊCH — HỌC THUỘC: ''tối đa/không quá/nhiều nhất/chỉ có'' → ≤ (số đó CÓ được) · ''ít nhất/tối thiểu/từ...trở lên'' → ≥ (CÓ) · ''dưới/ít hơn/chưa đến'' → < (KHÔNG được) · ''trên/hơn/vượt quá'' → > (KHÔNG). BA CÁI BẪY: ⚠️BẪY 1 — GHÉP NHẦM SỐ (đề ghi ''táo 40, cam 25'' mà viết 25x + 40y → NGƯỢC!). Cách tránh: VẼ BẢNG ở bước 2! ⚠️BẪY 2 — ĐẢO CHIỀU DẤU (''không quá'' mà viết ≥ → NGƯỢC HOÀN TOÀN!). Cách tránh: TRA TỪ ĐIỂN, đừng đoán! ⚠️BẪY 3 — TRỘN ĐƠN VỊ (nguy hiểm nhất!): đơn giá 35.000 đ mà tiền ghi 200 nghìn → trộn ''đồng'' với ''nghìn''! Cách tránh: CHỌN MỘT đơn vị rồi QUY HẾT về đó (35x + 28y ≤ 200 HOẶC 35000x + 28000y ≤ 200000 — cả hai đúng miễn NHẤT QUÁN!). MẸO KIỂM CHỨNG: thử một phương án cụ thể — mua 3kg táo, 4kg cam. Tính bằng ĐẦU: 3×40 + 4×25 = 220 nghìn ≤ 300 ✓ ĐỦ! Tính bằng bất phương trình: 40(3) + 25(4) = 220 ≤ 300 ✓ ⇒ KHỚP ⇒ bất phương trình ĐÚNG ✓ (Nếu KHÔNG khớp ⇒ lập bất phương trình SAI — kiểm lại bảng bước 2!). Rubric: Chưa đạt (chỉ nói ''đọc đề rồi viết'') | Cần cố gắng (nêu quy trình nhưng thiếu từ điển dịch hoặc thiếu cảnh báo bẫy) | Đạt (quy trình 4 bước rõ, có từ điển dịch, cảnh báo ≥ 2 bẫy, có ví dụ) | Tốt (đủ ý trên VÀ cảnh báo CẢ 3 bẫy (đặc biệt bẫy ĐƠN VỊ!) VÀ dạy mẹo KIỂM CHỨNG — HS không nhắc bẫy đơn vị là CHƯA ĐẠT vì đó là lỗi nguy hiểm nhất!).' WHERE id = 'c93cd4c0-dc74-41ff-a2f7-9a2aa115299a';
UPDATE questions SET distractors = '[{"phuong_an":"u = (4; -2)","quan_niem_sai":"Trừ sai với số âm: 1 - 3 thay vì 1 - (-3)"},{"phuong_an":"u = (4; -4)","quan_niem_sai":"Hoán vị đổi dấu — đây là vectơ pháp tuyến chứ không phải vectơ chỉ phương"},{"phuong_an":"u = (8; -2)","quan_niem_sai":"Cộng toạ độ hai điểm thay vì trừ"}]'::jsonb, loi_giai = 'AB = (6-2 ; 1-(-3)) = (4; 4). Đây là vectơ chỉ phương; rút gọn được u = (1; 1).' WHERE id = 'c9d58b7f-64dc-441f-98f2-e1029c4a0cb2';
UPDATE questions SET noi_dung = 'Bài làm: ''Xác định miền nghiệm của bất phương trình 3x + 2y < 6. ① Vẽ bờ 3x + 2y = 6 nét ĐỨT (vì dấu <), qua (2;0) và (0;3). ✓ ② Chọn điểm thử O(0;0). ✓ ③ Thay vào: 3(0) + 2(0) = 0. Hỏi 0 < 6? ⇒ SAI. ✓ ④ Vì thử O ra kết quả, nên tôi tô nửa mặt phẳng CHỨA O.'' Tìm và sửa lỗi.', loi_giai = 'Kết luận cuối (tô nửa chứa O) lại ĐÚNG — nhưng ĐÚNG NHỜ MAY, hai cái sai TRIỆT TIÊU nhau! NGUY HIỂM: nếu gặp bất phương trình mà O thật sự cho SAI (vd 3x+2y > 6), bạn ấy VẪN tô nửa chứa O ⇒ TÔ NGƯỢC HOÀN TOÀN! Rubric: Chưa đạt (nghĩ bài làm hoàn toàn đúng) | Cần cố gắng (chỉ thấy lỗi quy tắc tô) | Đạt (chỉ ra CẢ HAI lỗi, phát biểu quy tắc đúng) | Tốt (đủ ý trên VÀ nhận ra ĐÚNG NHỜ MAY VÀ đưa ví dụ bất phương trình khác (3x+2y > 6) chứng minh quy tắc sai sẽ gây hoạ). CÂU HAY NHẤT CỤM A — dạy: kết quả đúng KHÔNG có nghĩa lí luận đúng.' WHERE id = 'ca052c0f-6424-4e00-83bb-52cb30feca2e';
UPDATE questions SET loi_giai = 'KẾT LUẬN: Đỉnh = giao điểm VÀ thuộc miền nghiệm (thoả TẤT CẢ bất phương trình!) ⇒ BẮT BUỘC SÀNG LỌC — thay vào CẢ HỆ! QUY LUẬT SỐ LƯỢNG: 3 bất phương trình → 3 giao điểm → 3 đỉnh → loại 0 | 4 bất phương trình → 6 giao điểm → 4 đỉnh → LOẠI 2 | 5 bất phương trình → 10 giao điểm → 5 đỉnh → LOẠI 5 ⇒ Càng nhiều bất phương trình, càng nhiều giao điểm BỊ LOẠI! Rubric: Chưa đạt (không tính đúng số giao điểm hoặc không sàng lọc) | Cần cố gắng (liệt kê đủ 6 giao điểm nhưng sàng lọc sai) | Đạt (đúng cả 4 phần, sàng lọc chính xác, nêu 4 đỉnh và tứ giác) | Tốt (đủ ý trên VÀ ở (d) giải thích bằng HÌNH HỌC (bờ kéo dài vô hạn, có thể cắt nhau NGOÀI miền — bị bờ thứ ba CẮT NGANG!) VÀ nêu quy luật C(n,2)).' WHERE id = 'caa93a85-9d3a-40a0-875f-b64c10927e17';
UPDATE questions SET noi_dung = 'Cho hệ: ⎧ x + y ≤ 4 · ⎨ 2x + y ≤ 6 · ⎩ x ≥ 0, y ≥ 0. Tìm giá trị lớn nhất của F = 3x + 2y trên miền nghiệm.', distractors = '[{"phuong_an":"12","quan_niem_sai":"KHÔNG SÀNG LỌC! (dùng đỉnh giả (4;0) hoặc (0;6) — cả hai cho F = 12!). BẪY CHÍ MẠNG: 12 > 10 nên HS nghĩ ''chắc 12 mới đúng!'' ⇒ SẬP BẪY! (bệnh B05-①)"},{"phuong_an":"0","quan_niem_sai":"Lấy giá trị nhỏ nhất thay vì giá trị lớn nhất (đọc nhầm đề!)"},{"phuong_an":"9","quan_niem_sai":"Bỏ sót đỉnh (2;2) — giao HAI BỜ NGHIÊNG (khó nhất!) (bệnh B05-②)"}]'::jsonb, loi_giai = 'Bước 1 — Các ĐỈNH (đã sàng lọc!): O(0;0), (3;0), (2;2), (0;4) — miền là TỨ GIÁC (B05-Q08). Bước 2 — Bảng tính F: F(0;0) = 3(0)+2(0) = 0 ⬅️ NHỎ NHẤT | F(3;0) = 3(3)+2(0) = 9 | F(2;2) = 3(2)+2(2) = 6+4 = 10 ⬅️ LỚN NHẤT! ✓ | F(0;4) = 3(0)+2(4) = 8 ⇒ giá trị lớn nhất = 10 tại (2; 2) ✓ · giá trị nhỏ nhất = 0 tại O(0;0). KIỂM CHỨNG — thử điểm trong miền: (1;2): kiểm hệ 1+2 = 3 ≤ 4 ✓, 2(1)+2 = 4 ≤ 6 ✓ ⇒ trong miền ✓. F(1;2) = 3(1)+2(2) = 3+4 = 7 ⇒ 7 < 10 ✓ KHÔNG vượt giá trị lớn nhất ✓' WHERE id = 'cbc632f8-d0df-4bfb-9b7d-f7462d7693dd';
UPDATE questions SET noi_dung = 'Khoảng tứ phân vị = ____ trừ ____ (hai tứ phân vị).' WHERE id = 'cc1c5637-c7a4-46ec-8d77-50d79c3038a0';
UPDATE questions SET noi_dung = 'Xác định miền nghiệm của bất phương trình x − 2y ≥ 0. B1 — VẼ BỜ: bờ là x − 2y = 0. Tìm 2 điểm để vẽ. B2 — CHỌN ĐIỂM THỬ: kiểm O có dùng được không? B3 — THAY vào bất phương trình GỐC. B4 — TÔ MIỀN.' WHERE id = 'cc658802-7b43-432b-ae5f-5cbaf8edddee';
UPDATE questions SET loi_giai = 'khoảng tứ phân vị=50−20=30; cận dưới=20−1,5×30=20−45=−25; cận trên=50+1,5×30=50+45=95.' WHERE id = 'd05151c2-2cdf-4a1f-9dfd-1d9b3ee010ea';
UPDATE questions SET noi_dung = 'Giải thích cho bạn: vì sao từ một phương trình tổng quát ta viết được VÔ SỐ phương trình tham số khác nhau, nhưng chúng vẫn mô tả cùng một đường thẳng?', dap_an = 'Vì phương trình tham số phụ thuộc vào lựa chọn điểm mốc và vectơ chỉ phương, mà cả hai đều không duy nhất.', distractors = '[{"phuong_an":"Vì mỗi phương trình tham số ứng với một đường thẳng khác nhau","quan_niem_sai":"Hiểu sai: khác hình thức ≠ khác tập điểm"},{"phuong_an":"Vì tham số t có thể âm hoặc dương","quan_niem_sai":"Giải thích lệch trọng tâm, không nói được về mốc và vectơ chỉ phương"},{"phuong_an":"Vì phương trình tổng quát không xác định được vectơ pháp tuyến duy nhất","quan_niem_sai":"Nhầm chiều lập luận: vectơ pháp tuyến cũng chỉ khác nhau hằng số"}]'::jsonb, loi_giai = 'Một đường thẳng chứa vô số điểm ⇒ chọn mốc nào cũng được. vectơ chỉ phương cũng không duy nhất: mọi k·u (k≠0) đều dùng được. Mỗi cặp (mốc, vectơ chỉ phương) cho một phương trình tham số khác nhau về hình thức, nhưng tập hợp điểm sinh ra khi t chạy khắp R là như nhau — chính là đường thẳng đó. Ngược lại phương trình tổng quát (sau khi chuẩn hoá) là duy nhất vì nó mô tả trực tiếp tập nghiệm.' WHERE id = 'd080c2b4-bf14-47d6-8a98-d21acd52566a';
UPDATE questions SET noi_dung = 'Điền: phương trình bậc hai hai ẩn là đường tròn cần: hệ số x² và y² ______, KHÔNG có số hạng ______, và a² + b² - c ______.' WHERE id = 'd100ec4a-64db-45cb-b028-276f1ccb699e';
UPDATE questions SET noi_dung = 'Cho biểu thức (m − 2)x + 3y ≤ 7. Đếm số giá trị m NGUYÊN trong khoảng −1 ≤ m ≤ 5 để biểu thức LÀ bất phương trình bậc nhất hai ẩn.', loi_giai = 'Điều kiện: a, b KHÔNG ĐỒNG THỜI bằng 0. Ở đây a = m − 2, b = 3. ĐIỂM MẤU CHỐT: b = 3 ≠ 0 với MỌI m! ⇒ điều kiện LUÔN THOẢ ⇒ MỌI m đều được (kể cả m = 2 → bất phương trình thành 3y ≤ 7, vẫn hợp lệ). Đếm m nguyên trong [−1; 5]: {−1;0;1;2;3;4;5} → 7 giá trị.' WHERE id = 'd2dc300b-066b-4c61-a9be-1abbefd44710';
UPDATE questions SET noi_dung = 'Bé Na hỏi: ''Cô ơi, hệ có 4 bất phương trình thì em phải tô 4 lần! Hình vẽ rối tung hết, em không biết đâu là miền nghiệm nữa! Có mẹo gì không ạ?''', dap_an = 'Có chứ! Bí quyết: ĐỪNG TÔ PHẦN THUỘC — HÃY GẠCH BỎ PHẦN KHÔNG THUỘC! MẸO ''GẠCH BỎ'' (SGK khuyến nghị): Cách CŨ (rối!): tô phần THUỘC mỗi bất phương trình ⇒ 4 bất phương trình = 4 lớp màu chồng lên nhau ⇒ KHÔNG BIẾT chỗ nào chồng đủ 4 lớp! Cách MỚI (rõ!): GẠCH CHÉO ✖ phần KHÔNG THUỘC mỗi bất phương trình ⇒ vùng nào CÒN TRẮNG (không bị gạch bởi BẤT KỲ bất phương trình nào) = MIỀN NGHIỆM! ✓ QUY TRÌNH 3 BƯỚC: ① Với TỪNG bất phương trình: vẽ bờ (nét liền/đứt), chọn điểm thử, xác định nửa nào THUỘC, rồi ✖ GẠCH CHÉO nửa KHÔNG THUỘC! ② Làm với TẤT CẢ bất phương trình (gạch chồng lên nhau thoải mái!). ③ Nhìn vùng TRẮNG còn lại = MIỀN NGHIỆM ✓ VÌ SAO HAY? Logic: điểm bị gạch DÙ CHỈ 1 LẦN ⇒ nó vi phạm ít nhất 1 bất phương trình ⇒ KHÔNG phải nghiệm! Điểm KHÔNG bị gạch lần nào ⇒ thoả TẤT CẢ bất phương trình ⇒ LÀ NGHIỆM! ⇒ Chỉ cần nhìn ''chỗ nào TRẮNG'' — không cần đếm lớp màu!', loi_giai = 'THỬ NGAY — hệ ⎧ x+y ≤ 4 · ⎨ x ≥ 0 · ⎩ y ≥ 0: ① x+y ≤ 4 → thuộc: nửa chứa O → ✖ GẠCH nửa TRÊN-PHẢI đường x+y=4 | ② x ≥ 0 → thuộc: nửa phải Oy → ✖ GẠCH nửa BÊN TRÁI trục Oy (chỗ x < 0) | ③ y ≥ 0 → thuộc: nửa trên Ox → ✖ GẠCH nửa BÊN DƯỚI trục Ox (chỗ y < 0). Nhìn vùng TRẮNG ⇒ TAM GIÁC O(0;0), (4;0), (0;4)! ✓ HAI ĐIỀU PHẢI NHỚ: ⚠️ĐIỀU 1 — GIAO, không phải HỢP! Miền nghiệm hệ = PHẦN CHUNG (giao ∩), KHÔNG PHẢI gộp tất cả (hợp ∪)! NEO NHỚ: dấu ⎧ của hệ trông giống MÁI NHÀ ⌂ = GIAO ∩! Mái nhà CHE BỚT ⇒ miền NHỎ ĐI, không phải to ra! (Nhớ mẹo Chương I: ∩ = mái nhà ⌂ · ∪ = cái cốc 🥤) ⚠️ĐIỀU 2 — ĐỪNG QUÊN x ≥ 0, y ≥ 0! Chúng CŨNG LÀ bất phương trình — phải vẽ và gạch như mọi bất phương trình khác! (Quên ⇒ miền lan sang góc âm ⇒ SAI!) KIỂM CHỨNG: lấy MỘT ĐIỂM BẤT KỲ trong miền, thay vào CẢ HỆ — thoả HẾT ⇒ MIỀN ĐÚNG ✓ | có bất phương trình không thoả ⇒ MIỀN SAI, vẽ lại! VD (1;1): 1+1 = 2 ≤ 4 ✓ · 1 ≥ 0 ✓ · 1 ≥ 0 ✓ ⇒ ĐÚNG ✓ Rubric: Chưa đạt (chỉ nói ''tô cẩn thận hơn'') | Cần cố gắng (nêu mẹo gạch bỏ nhưng không giải thích vì sao đúng) | Đạt (nêu mẹo gạch bỏ rõ, giải thích logic (bị gạch 1 lần ⇒ vi phạm ⇒ loại), có ví dụ) | Tốt (đủ ý trên VÀ cảnh báo GIAO ≠ HỢP (neo ''mái nhà'' Chương I) VÀ nhắc x ≥ 0, y ≥ 0 CŨNG LÀ bất phương trình VÀ dạy bước KIỂM CHỨNG — HS không cảnh báo ''giao ≠ hợp'' là CHƯA ĐẠT vì đó là BỆNH CHÍNH của node!).' WHERE id = 'd3cef9d7-ef57-4dd0-8301-990ca68fd06c';
UPDATE questions SET noi_dung = 'Lập bảng so sánh ba đường conic (elip, hypebol, parabol) theo bốn tiêu chí: định nghĩa, phương trình chính tắc, liên hệ a-b-c, và tâm sai e.', loi_giai = 'ELIP — Định nghĩa: MF₁ + MF₂ = 2a (TỔNG không đổi). phương trình: x²/a² + y²/b² = 1 (a > b > 0). Liên hệ: c² = a² - b² (nên c < a). Tâm sai: e = c/a, 0 < e < 1. || HYPEBOL — Định nghĩa: |MF₁ - MF₂| = 2a (HIỆU không đổi). phương trình: x²/a² - y²/b² = 1 (a, b > 0 độc lập). Liên hệ: c² = a² + b² (nên c > a). Tâm sai: e = c/a > 1. Có thêm hai TIỆM CẬN y = ±(b/a)x. || PARABOL — Định nghĩa: MF = d(M, Δ) (CÁCH ĐỀU tiêu điểm và đường chuẩn). phương trình: y² = 2px (p > 0). Liên hệ: chỉ có một tham số p; F(p/2; 0), Δ: x = -p/2. Tâm sai: e = 1 (đúng bằng 1 — ranh giới giữa elip và hypebol). || MẸO THỐNG NHẤT: cả ba đều là quỹ tích điểm có tỉ số MF/d(M, Δ) = e không đổi; e < 1 ⇒ elip, e = 1 ⇒ parabol, e > 1 ⇒ hypebol.' WHERE id = 'd4abe427-7dfe-449a-bd51-233b19532b56';
UPDATE questions SET noi_dung = 'phương trình chính tắc của parabol (mở sang phải) là:' WHERE id = 'd5b1b39f-7fec-41f7-8e70-dc72a79ed9db';
UPDATE questions SET noi_dung = 'Cặp số là nghiệm của HỆ bất phương trình khi nó thoả ___ các trong hệ.' WHERE id = 'd5b96465-cf21-4d7a-8b5f-43bd5c71cc1b';
UPDATE questions SET noi_dung = 'Xét tính đúng/sai: Đường thẳng có vectơ chỉ phương u = (0; 3) viết được ở dạng phương trình chính tắc.', distractors = '[{"phuong_an":"Đúng, vẫn viết được","quan_niem_sai":"Bỏ qua điều kiện a, b ≠ 0"},{"phuong_an":"Đúng, chỉ cần bỏ mẫu số 0 đi","quan_niem_sai":"Tự ý sửa công thức, không hợp lệ về mặt toán học"},{"phuong_an":"Sai, vì vectơ chỉ phương không được có số 0","quan_niem_sai":"Hiểu sai: vectơ chỉ phương CÓ THỂ có thành phần 0, chỉ là không viết được dạng chính tắc"}]'::jsonb, loi_giai = 'phương trình chính tắc đòi hỏi CẢ HAI thành phần của vectơ chỉ phương khác 0 (vì phải chia cho a và b). Ở đây a = 0 nên không viết được.' WHERE id = 'd5bfbde7-bd96-4e4d-92f3-cd4ac276024d';
UPDATE questions SET noi_dung = '(a) Vì sao xy ≤ 4 KHÔNG phải bất phương trình bậc nhất hai ẩn, dù x và y đều có số mũ 1? (b) Cho hai ví dụ biểu thức hai ẩn nhưng không phải bậc nhất, thuộc HAI KIỂU LỖI KHÁC NHAU.', dap_an = '(a) Bậc của một HẠNG TỬ = TỔNG số mũ các ẩn trong đó. x: bậc 1 ✓ · y: bậc 1 ✓ · xy: bậc 1+1 = 2 ✗ · x²: bậc 2 ✗. ⇒ xy có bậc 2 ⇒ xy ≤ 4 là bất phương trình BẬC HAI. (b) Ví dụ 1: x² + y ≤ 3 (số mũ > 1). Ví dụ 2: √x + y ≤ 2 hoặc 1/x + y ≤ 5 (ẩn dưới căn / ở mẫu — số mũ phân số hoặc âm).', loi_giai = 'BẰNG CHỨNG HÌNH HỌC: miền nghiệm bất phương trình bậc nhất hai ẩn LUÔN là NỬA MẶT PHẲNG (bờ là ĐƯỜNG THẲNG). Nhưng xy = 4 là HYPEBOL (đường CONG!) → miền nghiệm không phải nửa mặt phẳng ⇒ chứng minh xy ≤ 4 không thể bậc nhất. Rubric: Chưa đạt (chỉ nói ''vì có xy'') | Đạt (giải thích quy tắc TỔNG SỐ MŨ, 2 ví dụ khác kiểu) | Tốt (đủ ý trên VÀ đưa bằng chứng hình học: bậc nhất → bờ THẲNG; xy=4 là hypebol CONG).' WHERE id = 'd5f701ed-8620-4aa3-88f9-63b9bf20387a';
UPDATE questions SET noi_dung = 'Cửa hàng bán x kg táo (40 nghìn/kg) và y kg cam (25 nghìn/kg). Khách chỉ có 300 nghìn. bất phương trình ràng buộc là: A. 25x + 40y ≤ 300 B. 40x + 25y ≤ 300 C. 40x + 25y ≥ 300 D. x + y ≤ 300' WHERE id = 'd73541cc-e5a5-4c59-b771-81bdba8974d0';
UPDATE questions SET noi_dung = 'Biểu thức nào LÀ bất phương trình bậc nhất hai ẩn? Giải thích ngắn. A. 3x² − y ≤ 7 B. 2xy + x > 1 C. −x + 4y ≥ 0 D. √x + y ≤ 2' WHERE id = 'd766b573-f150-4c24-b5e1-62037311482e';
UPDATE questions SET noi_dung = 'Viết phương trình đường tròn tâm I(2; 1) và tiếp xúc với đường thẳng d: 3x + 4y - 1 = 0.', loi_giai = 'Tiếp xúc ⇒ R = d(I, d) = |3·2 + 4·1 - 1|/√(9+16) = |6 + 4 - 1|/5 = 9/5. R² = 81/25. phương trình: (x-2)² + (y-1)² = 81/25.' WHERE id = 'd8a2e85d-20ae-4432-b819-4a55abc7c0ea';
UPDATE questions SET noi_dung = 'Học sinh chuyển phương trình tham số x = 2 + t, y = 5 + 3t sang phương trình tổng quát như sau: ''vectơ chỉ phương u = (1; 3) nên phương trình tổng quát là 1(x-2) + 3(y-5) = 0 ⇒ x + 3y - 17 = 0.'' Tìm lỗi.', dap_an = 'Sai: em ấy dùng vectơ chỉ phương (1;3) như thể là vectơ pháp tuyến. vectơ pháp tuyến đúng là n = (3; -1), nên phương trình tổng quát là 3(x-2) - 1(y-5) = 0 ⇒ 3x - y - 1 = 0.', distractors = '[{"phuong_an":"Không sai, x + 3y - 17 = 0 là đúng","quan_niem_sai":"Đồng nhất vectơ chỉ phương với vectơ pháp tuyến"},{"phuong_an":"Sai ở hệ số tự do, phải là x + 3y + 17 = 0","quan_niem_sai":"Chỉ sửa dấu mà không sửa gốc lỗi vectơ pháp tuyến"},{"phuong_an":"Sai, vectơ pháp tuyến là (-1; -3)","quan_niem_sai":"Chỉ đổi dấu, không hoán vị"}]'::jsonb, loi_giai = 'u = (1;3) ⇒ n = (3;-1). phương trình tổng quát: 3(x-2) - (y-5) = 0 ⇔ 3x - 6 - y + 5 = 0 ⇔ 3x - y - 1 = 0. Kiểm tra t=0 ⇒ (2;5): 6 - 5 - 1 = 0 ✓.' WHERE id = 'd8b74057-ecf6-4101-83cd-741e64990289';
UPDATE questions SET noi_dung = 'Viết phương trình đường tròn có tâm nằm trên Ox, bán kính 2, và tiếp xúc với đường thẳng d: 3x + 4y - 4 = 0.', loi_giai = 'Tâm I(a; 0). Tiếp xúc ⇔ d(I, d) = 2 ⇔ |3a + 0 - 4|/5 = 2 ⇔ |3a - 4| = 10 ⇔ 3a - 4 = 10 hoặc 3a - 4 = -10 ⇒ a = 14/3 hoặc a = -2. phương trình: (x - 14/3)² + y² = 4 hoặc (x + 2)² + y² = 4. Kiểm a = -2: |-6-4|/5 = 2 ✓.' WHERE id = 'd8ca85ad-8c5e-4dc2-bacb-f40da4274096';
UPDATE questions SET noi_dung = 'nào sau đây KHÔNG THỂ là phương trình đường tròn (xét về hình thức)?' WHERE id = 'd8ced4ec-b9ee-4fa2-be55-5fdab9e33d88';
UPDATE questions SET noi_dung = 'Cho bất phương trình 2x + 3y > 6. Miền nghiệm của nó: A. Chứa gốc O(0; 0) B. KHÔNG chứa gốc O(0; 0) C. Là toàn bộ mặt phẳng D. Là tập rỗng', distractors = '[{"phuong_an":"A","quan_niem_sai":"Thử ra SAI mà vẫn kết luận miền CHỨA O — TÔ NGƯỢC!"},{"phuong_an":"C","quan_niem_sai":"Không hiểu miền nghiệm là NỬA mặt phẳng"},{"phuong_an":"D","quan_niem_sai":"Nghĩ bất phương trình vô nghiệm — sai! vd (5;0): 10 > 6 ✓ là nghiệm"}]'::jsonb WHERE id = 'daf68c4b-c571-489a-b86a-13dc76ad4a0a';
UPDATE questions SET noi_dung = 'Chuyển phương trình tổng quát 3x + 4y - 12 = 0 sang phương trình tham số (chọn mốc là giao điểm với Ox).', distractors = '[{"phuong_an":"x = 4 + 3t ; y = 4t","quan_niem_sai":"Lấy vectơ pháp tuyến làm vectơ chỉ phương"},{"phuong_an":"x = 3 + 4t ; y = 4 - 3t","quan_niem_sai":"Lấy hệ số phương trình tổng quát làm điểm mốc"},{"phuong_an":"x = 4 - 4t ; y = 3t và coi là đường thẳng khác","quan_niem_sai":"Cho rằng đổi dấu vectơ chỉ phương cho đường thẳng khác"}]'::jsonb, loi_giai = 'Giao Ox: y = 0 ⇒ 3x = 12 ⇒ x = 4, mốc M(4; 0). vectơ pháp tuyến n = (3; 4) ⇒ vectơ chỉ phương u = (4; -3). phương trình tham số: x = 4 + 4t, y = 0 - 3t. Kiểm tra t=1 ⇒ (8;-3): 24 - 12 - 12 = 0 ✓.' WHERE id = 'dca443ce-d3b6-4b7d-9921-b4738cf4b7c4';
UPDATE questions SET noi_dung = 'Viết phương trình chính tắc của parabol đi qua điểm M(2; 4).', loi_giai = 'Dạng y² = 2px. Thay M(2; 4): 16 = 2p·2 = 4p ⇒ p = 4. phương trình: y² = 2·4·x = 8x. Kiểm M(2;4): 16 = 8·2 = 16 ✓.' WHERE id = 'dd6d218d-753c-456d-bc49-b2f17406f4fb';
UPDATE questions SET noi_dung = 'Hai NHÀ MÁY sản xuất linh kiện với ĐỘ DÀY (mm): Nhà máy X (trung bình=10, độ lệch chuẩn=0,5); Nhà máy Y (trung bình=50, độ lệch chuẩn=2). Nhà máy nào có QUY TRÌNH SẢN XUẤT ''ỔN ĐỊNH TƯƠNG ĐỐI'' hơn (dùng hệ số biến thiên)? (Hỏi kèm độ tự tin 1–3)', dap_an = 'Nhà máy X ổn định TƯƠNG ĐỐI hơn (hệ số biến thiên thấp hơn)', distractors = '[{"phuong_an":"Nhà máy Y ổn định hơn CHỈ vì ĐỘ LỆCH CHUẨN TUYỆT ĐỐI (2) LỚN HƠN X (0,5) NÊN CHỌN NGƯỢC LẠI mà KHÔNG TÍNH hệ số biến thiên","quan_niem_sai":"SO SÁNH TRỰC TIẾP ĐỘ LỆCH CHUẨN TUYỆT ĐỐI (2 so với 0,5) mà KHÔNG XEM XÉT SỰ KHÁC BIỆT về MỨC TRUNG BÌNH (50 so với 10) giữa HAI nhà MÁY, dẫn đến SO SÁNH KHÔNG CÔNG BẰNG và CÓ THỂ đưa RA KẾT LUẬN SAI LỆCH."}]'::jsonb, loi_giai = 'hệ số biến thiên(X)=0,5/10×100%=5%; hệ số biến thiên(Y)=2/50×100%=4%... [cần TÍNH LẠI CẨN THẬN] Thực CHẤT: hệ số biến thiên(Y)=4%<hệ số biến thiên(X)=5%, nên NHÀ MÁY Y ổn ĐỊNH TƯƠNG ĐỐI HƠN (không phải X như đáp án BAN ĐẦU nêu, đây là MỘT TÌNH HUỐNG CẦN TÍNH TOÁN CẨN THẬN để có KẾT LUẬN CHÍNH XÁC).' WHERE id = 'de4f1bf6-2cfa-4683-9cee-f13be32390a8';
UPDATE questions SET noi_dung = 'Parabol có đường chuẩn x = -4. Viết phương trình chính tắc của parabol đó.', loi_giai = 'Đường chuẩn x = -p/2 = -4 ⇒ p/2 = 4 ⇒ p = 8. phương trình: y² = 2px = 16x.' WHERE id = 'de600f1c-153e-4ad8-9b67-044f687316fe';
UPDATE questions SET noi_dung = '(a) ''CẬN DƯỚI'' để xác định BẤT THƯỜNG là \(Q1-1{,}5\times khoảng tứ phân vị\). (b) ''CẬN TRÊN'' là \(Q3+1{,}5\times\). (c) MỘT giá trị NẰM TRONG khoảng [CẬN DƯỚI, CẬN TRÊN] được coi là ''BÌNH THƯỜNG'' (không phải OUTLIER). (d) MỌI giá trị NGOÀI khoảng [Q1,Q3] đều được coi là BẤT THƯỜNG.' WHERE id = 'df6c69eb-9b7b-4b4e-b0bd-1a17cb79bc27';
UPDATE questions SET noi_dung = 'Điền: phương trình x² + y² - 2ax - 2by + c = 0 là đường tròn khi ______, khi đó tâm I(a; b) và R = ______.' WHERE id = 'e0438a1f-0091-4fee-8a32-557d73f086e5';
UPDATE questions SET noi_dung = 'Viết phương trình tổng quát đường thẳng qua M(2; -1) và song song với d: 3x - 4y + 7 = 0.', distractors = '[{"phuong_an":"3x - 4y + 10 = 0","quan_niem_sai":"Sai dấu hệ số tự do khi khai triển -4(y+1)"},{"phuong_an":"4x + 3y - 5 = 0","quan_niem_sai":"Lấy vectơ pháp tuyến vuông góc ⇒ ra đường vuông góc với d"},{"phuong_an":"3x - 4y + 7 = 0","quan_niem_sai":"Chép nguyên d — nhưng M(2;-1) không thuộc d (6+4+7=17≠0)"}]'::jsonb, loi_giai = 'Song song ⇒ cùng vectơ pháp tuyến (3; -4). phương trình tổng quát: 3(x-2) - 4(y+1) = 0 ⇔ 3x - 6 - 4y - 4 = 0 ⇔ 3x - 4y - 10 = 0. Kiểm tra M: 6 + 4 - 10 = 0 ✓. Hệ số tự do -10 ≠ 7 nên không trùng d ✓.' WHERE id = 'e177eee2-1242-40c5-a9f6-ecbb02dce3ab';
UPDATE questions SET noi_dung = 'Với mỗi bất phương trình sau, MÔ TẢ đường thẳng bờ (dạng hình, đi qua điểm nào) và KIỂU NÉT VẼ: (a) 2x + y ≤ 4 (b) y > 3 (c) x ≥ −2 (d) x − y < 0' WHERE id = 'e209d6cd-fcbc-4bdf-9704-57b7f8eb6444';
UPDATE questions SET noi_dung = 'Cho phương trình 4x² + 9y² = 36. Đưa về dạng chính tắc và cho biết đó là conic nào.' WHERE id = 'e38de9ad-2d5b-49a5-8f74-12c7f44b5d07';
UPDATE questions SET noi_dung = 'Cho hệ: ⎧ x + y ≤ 4 · ⎨ x ≥ 0 · ⎩ y ≥ 0. Tìm giá trị lớn nhất và giá trị nhỏ nhất của F = 3x + y trên miền nghiệm. B1 — TÌM CÁC ĐỈNH. B2 — TÍNH F TẠI TỪNG ĐỈNH (lập BẢNG!). B3 — SO SÁNH & KẾT LUẬN.', dap_an = 'B1: bờ x+y = 4, x = 0, y = 0. Giải 3 cặp: x=0 ∩ y=0 → O(0;0) · y=0 ∩ x+y=4 → (4;0) · x=0 ∩ x+y=4 → (0;4). SÀNG LỌC: cả 3 đều thoả hệ ✓ ⇒ 3 ĐỈNH: O(0;0), (4;0), (0;4) | B2 BẢNG: F(0;0) = 3(0) + 0 = 0 | F(4;0) = 3(4) + 0 = 12 | F(0;4) = 3(0) + 4 = 4 | B3: so sánh 0, 12, 4 ⇒ giá trị lớn nhất = 12, đạt tại đỉnh (4; 0) ✓ · giá trị nhỏ nhất = 0, đạt tại đỉnh O(0; 0) ✓', distractors = '[{"phuong_an":"B1 quên bờ x=0, y=0","quan_niem_sai":"Bỏ sót đỉnh (bệnh B05-②)"},{"phuong_an":"B1 không sàng lọc","quan_niem_sai":"Lấy đỉnh sai (bệnh B05-①)"},{"phuong_an":"B2 tính F(4;0) = 3 + 4 = 7","quan_niem_sai":"Quên nhân hệ số!"},{"phuong_an":"B3 lấy giá trị lớn nhất = 0","quan_niem_sai":"NHẦM MAX VỚI MIN!"}]'::jsonb, loi_giai = 'BƯỚC B2 — LẬP BẢNG là BẮT BUỘC! Tính nhẩm dễ nhầm, dễ bỏ sót đỉnh. Bảng giúp: ① thấy ĐỦ đỉnh ② so sánh trực quan ③ dễ kiểm lại. KIỂM CHỨNG — thử điểm GIỮA miền: (1;1): F = 3(1) + 1 = 4 ⇒ 4 < 12 ✓ KHÔNG vượt giá trị lớn nhất! (khớp định lí — max ở ĐỈNH!) | (2;1): F = 3(2) + 1 = 7 ⇒ 7 < 12 ✓ ⇒ Mọi điểm trong miền đều ≤ 12 — xác nhận giá trị lớn nhất = 12 ✓' WHERE id = 'e42ee9c4-f0ef-4f41-924e-05385b02d0d4';
UPDATE questions SET noi_dung = 'Hai lớp có cùng KHOẢNG BIẾN THIÊN R=20 về điểm thi. Lớp A có khoảng tứ phân vị=5; Lớp B có=15. Nhận xét về SỰ KHÁC BIỆT trong PHÂN BỐ điểm của HAI LỚP. (Hỏi kèm độ tự tin 1–3)', distractors = '[{"phuong_an":"Cả hai lớp có PHÂN BỐ điểm GIỐNG HỆT NHAU vì CÙNG có R=20","quan_niem_sai":"SAI: CHỈ dựa VÀO việc CÙNG có R=20 để KẾT LUẬN ''PHÂN BỐ GIỐNG HỆT NHAU'', KHÔNG XÉT đến sự KHÁC BIỆT ĐÁNG KỂ về khoảng tứ phân vị (5 so với 15), một THÔNG TIN QUAN TRỌNG cho THẤY HAI lớp CÓ CẤU TRÚC PHÂN BỐ RẤT KHÁC NHAU."}]'::jsonb, loi_giai = 'So sánh khoảng tứ phân vị (mức độ TẬP TRUNG của phần LỚN dữ liệu) khi HAI mẫu CÓ CÙNG R, để thấy sự KHÁC BIỆT về CẤU TRÚC PHÂN BỐ.' WHERE id = 'e622441d-5950-4964-a145-97adb2c8cff8';
UPDATE questions SET noi_dung = 'Một bạn hỏi: ''Trong PHÁT HIỆN GIAN LẬN THẺ TÍN DỤNG (fraud detection), CÁC HỆ THỐNG NGÂN HÀNG có DÙNG những Ý TƯỞNG TƯƠNG TỰ như QUY TẮC khoảng tứ phân vị để PHÁT HIỆN GIAO DỊCH BẤT THƯỜNG KHÔNG?'' Giải thích cho bạn. (Hỏi kèm độ tự tin 1–3)', dap_an = 'CÓ, Ý TƯỞNG CƠ BẢN là TƯƠNG TỰ (dù CÁC HỆ THỐNG THỰC TẾ THƯỜNG PHỨC TẠP HƠN NHIỀU). CÁC HỆ THỐNG PHÁT HIỆN GIAN LẬN THẺ TÍN DỤNG THƯỜNG PHÂN TÍCH ''HÀNH VI GIAO DỊCH ĐIỂN HÌNH'' của MỘT KHÁCH HÀNG CỤ THỂ (ví dụ SỐ TIỀN GIAO DỊCH THÔNG THƯỜNG, ĐỊA ĐIỂM THƯỜNG XUYÊN GIAO DỊCH, TẦN SUẤT GIAO DỊCH...) — TƯƠNG TỰ như việc XÁC ĐỊNH ''PHẦN ĐIỂN HÌNH'' (Q1 đến Q3) của dữ liệu THÔNG THƯỜNG; KHI có MỘT GIAO DỊCH ''CÁCH XA'' ĐÁNG KỂ so với ''HÀNH VI ĐIỂN HÌNH'' này (ví dụ MỘT giao DỊCH VỚI SỐ TIỀN RẤT LỚN so với THÔNG THƯỜNG, hoặc TẠI MỘT ĐỊA ĐIỂM ''BẤT THƯỜNG'' so với LỊCH SỬ giao DỊCH), HỆ THỐNG sẽ ''GẮN CỜ'' (FLAG) giao DỊCH đó là ''ĐÁNG NGHI'' và có THỂ TẠM DỪNG hoặc YÊU CẦU XÁC MINH THÊM — đây CHÍNH LÀ Ý TƯỞNG ''PHÁT HIỆN GIÁ TRỊ BẤT THƯỜNG'' (outlier detection) áp DỤNG vào một NGỮ CẢNH THỰC TẾ CỤ THỂ; DĨ NHIÊN, CÁC HỆ THỐNG THỰC TẾ THƯỜNG sử DỤNG các KỸ THUẬT PHỨC TẠP HƠN NHIỀU (kết hợp NHIỀU YẾU TỐ, HỌC MÁY - machine learning...), nhưng Ý TƯỞNG CỐT LÕI (''SO SÁNH với HÀNH VI ĐIỂN HÌNH để PHÁT HIỆN BẤT THƯỜNG'') VẪN CÓ NGUỒN GỐC TƯƠNG TỰ như QUY TẮC khoảng tứ phân vị ĐƠN GIẢN đã HỌC.', loi_giai = 'Đây là một KẾT NỐI THÚ VỊ giữa KIẾN THỨC THỐNG KÊ CƠ BẢN (QUY TẮC khoảng tứ phân vị) và MỘT ỨNG DỤNG CÔNG NGHỆ HIỆN ĐẠI QUAN TRỌNG (PHÁT HIỆN GIAN LẬN), cho THẤY Ý TƯỞNG NỀN TẢNG về ''PHÁT HIỆN BẤT THƯỜNG'' có ỨNG DỤNG RẤT RỘNG RÃI, TỪ THỐNG KÊ CƠ BẢN đến CÁC HỆ THỐNG AN NINH TÀI CHÍNH PHỨC TẠP.' WHERE id = 'e62b89b4-6a5f-48f1-a7d8-076061401840';
UPDATE questions SET distractors = '[{"phuong_an":"2x - 3y + 7 = 0","quan_niem_sai":"Đây là đường SONG SONG với d (cùng vectơ pháp tuyến)"},{"phuong_an":"2x + 3y - 5 = 0","quan_niem_sai":"Chỉ đổi dấu một hệ số: 2·2 + (-3)·3 = -5 ≠ 0"},{"phuong_an":"3x - 2y + 5 = 0","quan_niem_sai":"Hoán vị nhưng không đổi dấu: 2·3 + (-3)(-2) = 12 ≠ 0"}]'::jsonb WHERE id = 'e72882ef-0fe2-4e1e-aee1-eb472069826a';
UPDATE questions SET noi_dung = 'Bạn An mua x quyển vở (15 nghìn/quyển) và y cây bút (5 nghìn/cây), tổng tiền không quá 100 nghìn. a) bất phương trình ràng buộc là 15x + 5y ≤ 100 b) Phải thêm điều kiện x ≥ 0 và y ≥ 0 c) Cặp (2; 5) thoả điều kiện d) Cặp (−1; 10) thoả điều kiện', distractors = '[{"phuong_an":"d) chọn Đúng","quan_niem_sai":"BỆNH CHÍNH! Chỉ kiểm bất phương trình tiền, QUÊN điều kiện x ≥ 0. Cặp (−1;10) THOẢ bất phương trình tiền (35 ≤ 100 ✓) nên HS chỉ kiểm bất phương trình sẽ nói ''Đúng''!"},{"phuong_an":"b) chọn Sai","quan_niem_sai":"Nghĩ điều kiện x,y ≥ 0 là ''thừa'', ''không cần ghi''"}]'::jsonb, loi_giai = 'c) 15(2) + 5(5) = 30 + 25 = 55 ≤ 100 ✓ và 2 ≥ 0, 5 ≥ 0 ✓ ⇒ THOẢ | d) SAI! 15(−1) + 5(10) = −15 + 50 = 35 ≤ 100 ✓ (bất phương trình tiền THOẢ!) NHƯNG x = −1 < 0 ⇒ mua ÂM 1 quyển vở?! VÔ LÍ!' WHERE id = 'e8f1657d-5fe1-433d-b649-08aad6462c0d';
UPDATE questions SET noi_dung = 'Cho bất phương trình x + 2y ≤ 6. Đếm số điểm THUỘC miền nghiệm: O(0;0) · A(2;2) · B(4;1) · C(6;0) · D(1;4)' WHERE id = 'e9573769-2a3a-460e-8f03-59ebf61b5159';
UPDATE questions SET noi_dung = 'Viết phương trình chính tắc của hypebol có a = 4 và c = 5.', loi_giai = 'Hypebol: b² = c² - a² = 25 - 16 = 9. phương trình: x²/16 - y²/9 = 1.' WHERE id = 'eb5f782e-af77-4b4a-b0ee-27c326a7ab5e';
UPDATE questions SET noi_dung = 'Viết phương trình đường tròn tâm I(3; -4) tiếp xúc với trục Ox.', loi_giai = 'Tiếp xúc Ox ⇒ R = |tung độ tâm| = |-4| = 4 ⇒ R² = 16. phương trình: (x-3)² + (y+4)² = 16.' WHERE id = 'ebb4a9ac-0399-42cc-be98-c00959d8054a';
UPDATE questions SET noi_dung = 'Xét phương trình x² + y² - 4x + 6y + 13 = 0. Bước 1: a = 2, b = -3, c = 13. Bước 2: R² = 4 + 9 - 13 = 0. Bước 3: R = 0 nên đây là đường tròn bán kính 0. Bước nào sai?' WHERE id = 'ec6f738f-3e6d-4209-b791-47827295c92e';
UPDATE questions SET noi_dung = 'a) Muốn tìm giá trị lớn nhất của F, ta tính F tại các ĐỈNH rồi so sánh b) Có thể tìm giá trị lớn nhất bằng cách thử một điểm bất kỳ trong miền c) Nếu miền nghiệm là TAM GIÁC, ta chỉ cần tính F tại 3 đỉnh d) Nếu miền nghiệm RỖNG (hệ vô nghiệm), vẫn tìm được giá trị lớn nhất' WHERE id = 'ee184acf-65df-4623-b5c2-8321a331c601';
UPDATE questions SET noi_dung = 'Tìm m để x² + y² - 2x + 4y + m = 0 là phương trình đường tròn.' WHERE id = 'eeb86677-871e-44fb-8ade-cce059fd299c';
UPDATE questions SET noi_dung = 'Bạn nói: ''phương trình chính tắc là dạng tổng quát nhất của đường thẳng vì nó gọn hơn phương trình tổng quát.'' Hãy phản biện.', dap_an = 'Sai. chính tắc KÉM tổng quát hơn phương trình tổng quát vì nó đòi điều kiện a ≠ 0 VÀ b ≠ 0.', distractors = '[{"phuong_an":"Đúng, phương trình chính tắc tổng quát nhất","quan_niem_sai":"Nhầm ''gọn'' với ''tổng quát''"},{"phuong_an":"Sai, vì phương trình chính tắc chỉ dùng cho đường qua gốc O","quan_niem_sai":"Nêu điều kiện sai (không liên quan gốc O)"},{"phuong_an":"Sai, vì phương trình chính tắc không xác định được vectơ chỉ phương","quan_niem_sai":"Tin rằng phương trình chính tắc không chứa thông tin vectơ chỉ phương; không nhận ra mẫu số CHÍNH là toạ độ vectơ chỉ phương"}]'::jsonb, loi_giai = 'phương trình tổng quát Ax + By + C = 0 mô tả được MỌI đường thẳng (chỉ cần A, B không đồng thời bằng 0), kể cả đường thẳng đứng x = 3 và đường nằm ngang y = 2. phương trình chính tắc thì không: nếu vectơ chỉ phương có a = 0 (đường đứng) hoặc b = 0 (đường ngang) thì mẫu số bằng 0, không viết được. Vậy tập đường thẳng viết được bằng chính tắc là TẬP CON thực sự của tập viết được bằng phương trình tổng quát. ''Gọn'' không đồng nghĩa với ''tổng quát''.' WHERE id = 'ef5abb7d-9296-4ce9-ab48-e3884403c741';
UPDATE questions SET noi_dung = 'a) Thay điểm thử vào bất phương trình, ra ĐÚNG ⇒ tô nửa mặt phẳng CHỨA điểm thử b) Thay điểm thử vào bất phương trình, ra SAI ⇒ tô nửa mặt phẳng CHỨA điểm thử c) Điểm thử KHÔNG được nằm trên đường thẳng bờ d) O(0; 0) luôn là điểm thử tốt nhất trong MỌI trường hợp' WHERE id = 'f0711ffe-5f80-40ee-9480-39421a6ebcc5';
UPDATE questions SET noi_dung = 'Khoảng tứ phân vị được tính bằng công thức nào?', dap_an = 'khoảng tứ phân vị = Q3 − Q1.', distractors = '[{"phuong_an":"khoảng tứ phân vị = Q3 + Q1","quan_niem_sai":"Nhầm phép TOÁN, dùng phép CỘNG thay vì đúng phải là phép TRỪ."},{"phuong_an":"khoảng tứ phân vị = Q2 − Q1","quan_niem_sai":"Nhầm CÔNG THỨC, dùng Q2 (TRUNG VỊ) thay vì đúng phải là Q3."},{"phuong_an":"khoảng tứ phân vị = Giá trị LỚN NHẤT − Giá trị NHỎ NHẤT","quan_niem_sai":"Đây là ĐỊNH NGHĨA của KHOẢNG BIẾN THIÊN R, KHÔNG PHẢI khoảng tứ phân vị."}]'::jsonb WHERE id = 'f1f49d35-11bb-439f-8a9e-4b9314bbc460';
UPDATE questions SET noi_dung = 'Bé Na hỏi: ''Cô ơi, em thấy cặp (1; 4) THOẢ bất phương trình THỨ NHẤT của hệ rồi mà! Vậy nó là nghiệm rồi chứ ạ? Sao cô bảo em phải kiểm THÊM làm gì?!''', dap_an = 'Chưa đủ đâu bé! Phải kiểm HẾT các bất phương trình — vì hệ nghĩa là ''VÀ'', không phải ''HOẶC''! ẨN DỤ VÉ VÀO KHU VUI CHƠI: khu vui chơi có BA cửa kiểm soát, muốn vào phải qua CẢ BA. Cửa ①: có vé 🎫 | Cửa ②: cao trên 1m2 📏 | Cửa ③: có người lớn đi cùng 👨‍👧. Bé qua cửa ① (có vé) rồi vui mừng hét: ''Con VÀO ĐƯỢC rồi!'' Bác bảo vệ: ''Khoan đã! Cháu mới qua 1/3 cửa thôi!'' Bé cao 1m1 ⇒ KHÔNG QUA CỬA ②! ⇒ KHÔNG VÀO ĐƯỢC! (dù đã có vé!) QUY TẮC: dấu ⎧ (ngoặc nhọn của hệ) = ''VÀ'' ⇒ thoả TẤT CẢ bất phương trình. NEO NHỚ: dấu ⎧ giống MÁI NHÀ ⌂ — đó chính là PHÉP GIAO ∩! Mái nhà CHE BỚT → chỉ giữ phần CHUNG!' WHERE id = 'f2eaa5de-3283-4864-9d86-13454065819e';
UPDATE questions SET noi_dung = 'Viết phương trình tiếp tuyến của đường tròn x² + y² = 25 tại điểm A(3; 4).', distractors = '[{"phuong_an":"4x - 3y = 0","quan_niem_sai":"Lấy OA làm vectơ chỉ phương thay vì vectơ pháp tuyến"},{"phuong_an":"3x + 4y - 5 = 0","quan_niem_sai":"Dùng R = 5 thay vì R² = 25 ở vế phải"},{"phuong_an":"3x + 4y = 0","quan_niem_sai":"Quên hệ số tự do (tiếp tuyến không đi qua gốc O)"}]'::jsonb, loi_giai = 'Tâm O(0; 0). A thuộc (C): 9 + 16 = 25 ✓. vectơ pháp tuyến = OA = (3; 4). phương trình: 3(x-3) + 4(y-4) = 0 ⇔ 3x + 4y - 25 = 0. (Mẹo: với tâm O, tiếp tuyến tại (x₀;y₀) là x₀x + y₀y = R².)' WHERE id = 'f352592a-2a14-4aa3-b8f7-d5648a425879';
UPDATE questions SET noi_dung = 'Cặp số (x₀; y₀) là NGHIỆM của HỆ bất phương trình khi nó: A. Thoả ít nhất MỘT trong hệ B. Thoả TẤT CẢ các bất phương trình trong hệ (đồng thời) C. Thoả đúng một bất phương trình (không thoả các bất phương trình còn lại) D. Không thoả bất phương trình nào', loi_giai = 'Dấu ⎧ (ngoặc nhọn) nghĩa là ''VÀ'' — phải thoả ĐỒNG THỜI mọi bất phương trình!' WHERE id = 'f35af6bb-0d1f-4668-a37a-5aa2a09cfc25';
UPDATE questions SET loi_giai = 'Cách kiểm: thay toạ độ vào TẤT CẢ các bất phương trình của hệ — thoả HẾT ⇒ là đỉnh ✓' WHERE id = 'f380f963-4696-4164-bf87-61fffd40d615';
UPDATE questions SET noi_dung = 'Cho bất phương trình 2x − y ≤ 4. Đếm số điểm KHÔNG DÙNG ĐƯỢC làm điểm thử (vì nằm TRÊN bờ): P(0;0) · Q(2;0) · R(0;−4) · S(1;−2)' WHERE id = 'f5bdaa36-c00b-43c8-b72b-4ead6cb161b0';
UPDATE questions SET noi_dung = 'Viết phương trình đường tròn đường kính AB với A(1; 1), B(5; 7).', loi_giai = 'Tâm I là trung điểm AB: I = ((1+5)/2; (1+7)/2) = (3; 4). R = AB/2; AB = √(16 + 36) = √52 ⇒ R = √52/2 = √13 ⇒ R² = 13. phương trình: (x-3)² + (y-4)² = 13.' WHERE id = 'f5cc900c-d453-4112-81f5-6045ef667bce';
UPDATE questions SET distractors = '[{"phuong_an":"x² + y - 1 = 0","quan_niem_sai":"Chứa x bậc hai — không phải đường thẳng"},{"phuong_an":"xy + 3 = 0","quan_niem_sai":"Chứa tích xy — không phải phương trình bậc nhất hai ẩn"},{"phuong_an":"0x + 0y + 7 = 0","quan_niem_sai":"Vi phạm điều kiện A, B không đồng thời bằng 0"}]'::jsonb, loi_giai = 'phương trình tổng quát có dạng Ax + By + C = 0 với A, B không đồng thời bằng 0; ở đây A=3, B=-2.' WHERE id = 'f5cec98f-1fc3-4231-8992-ce42a25df487';
UPDATE questions SET dap_an = 'Sai. Tiếp xúc Oy (phương trình x = 0) ⇒ R = |hoành độ tâm| = |2| = 2, không phải 3. Học sinh nhầm sang tung độ (đó là điều kiện tiếp xúc Ox).' WHERE id = 'f6fc2e86-6166-4bb7-9626-f7f6e1ee14f3';
UPDATE questions SET loi_giai = 'Thay toạ độ điểm vào phương trình, nếu được đẳng thức đúng (bằng 0) thì điểm thuộc đường thẳng.' WHERE id = 'f7252acd-a3a5-466b-866c-b0cc138d7106';
UPDATE questions SET distractors = '[{"phuong_an":"A","quan_niem_sai":"(10;0): 10 ≤ 8? ✗ hỏng BPT①"},{"phuong_an":"C","quan_niem_sai":"BẪY CHÍNH! (−1;4): 7 ≤ 8 ✓ thoả BPT① NHƯNG x = −1 < 0 ⇒ VI PHẠM x ≥ 0! HS chỉ kiểm BPT① sẽ chọn C (gộp 2 bệnh: kiểm thiếu bất phương trình + coi nhẹ điều kiện ẩn A06)"},{"phuong_an":"D","quan_niem_sai":"(4;3): 4 + 6 = 10 ≤ 8? ✗"}]'::jsonb WHERE id = 'f7a2579c-95d5-4826-9505-c3028c620116';
UPDATE questions SET loi_giai = 'Tâm O(0;0), R = 5. d(O, d) = |−25|/√(9+16) = 25/5 = 5 = R ⇒ TIẾP XÚC. Tiếp điểm là hình chiếu của O trên d: đường qua O vuông góc d có vectơ chỉ phương (3;4) ⇒ tham số (3t; 4t). Thay vào d: 9t + 16t - 25 = 0 ⇒ 25t = 25 ⇒ t = 1 ⇒ M(3; 4). Kiểm M thuộc (C): 9 + 16 = 25 ✓ và thuộc d: 9 + 16 - 25 = 0 ✓.' WHERE id = 'f896c803-e488-4c81-8386-f8b3d30dcf38';
UPDATE questions SET noi_dung = 'Giải thích vì sao QUY TẮC ''1,5×khoảng tứ phân vị'' (thay VÌ MỘT HỆ SỐ KHÁC như 1 hoặc 2) được CHỌN làm TIÊU CHUẨN PHỔ BIẾN để XÁC ĐỊNH giá TRỊ BẤT THƯỜNG, liên hệ với sự ĐÁNH ĐỔI giữa việc ''PHÁT HIỆN ĐỦ NHIỀU'' và ''KHÔNG BÁO ĐỘNG GIẢ QUÁ NHIỀU''. (Hỏi kèm độ tự tin 1–3)' WHERE id = 'f938d8a9-eca6-45aa-8834-3e08a81e37cb';
UPDATE questions SET noi_dung = 'Chuyển phương trình tham số x = 1 + 2t, y = 3 - t sang phương trình tổng quát.', distractors = '[{"phuong_an":"2x + y - 5 = 0","quan_niem_sai":"Lấy vectơ chỉ phương (2;-1) làm vectơ pháp tuyến (không hoán vị đổi dấu)"},{"phuong_an":"x - 2y + 5 = 0","quan_niem_sai":"Khử t sai dấu: dùng t = y - 3"},{"phuong_an":"x + 2y + 7 = 0","quan_niem_sai":"Đúng vectơ pháp tuyến nhưng sai dấu hệ số tự do"}]'::jsonb, loi_giai = 'Từ phương trình thứ hai: t = 3 - y. Thay vào phương trình thứ nhất: x = 1 + 2(3 - y) = 7 - 2y ⇒ x + 2y - 7 = 0. Kiểm tra t=0 ⇒ (1;3): 1 + 6 - 7 = 0 ✓. t=1 ⇒ (3;2): 3 + 4 - 7 = 0 ✓.' WHERE id = 'f941e098-bd1e-4927-af56-a8f78dcdc110';
UPDATE questions SET loi_giai = 'BẢNG DỊCH: ''tối đa lợi nhuận/doanh thu/sản lượng'' → giá trị lớn nhất (max) · ''tối thiểu chi phí/thời gian/nguyên liệu'' → giá trị nhỏ nhất (min).' WHERE id = 'f9fcd5df-9fea-4047-aa67-22f133470bf3';
UPDATE questions SET distractors = '[{"phuong_an":"-15 < m < 15","quan_niem_sai":"Quên cộng 5 (giá trị tại tâm) khi giải bất phương trình trị tuyệt đối"},{"phuong_an":"m < 10","quan_niem_sai":"Bỏ sót cận dưới của bất phương trình trị tuyệt đối"},{"phuong_an":"-20 < m < 10 nhưng dùng điều kiện d < R²","quan_niem_sai":"So sánh d với R² = 9 thay vì R = 3"}]'::jsonb WHERE id = 'fa1fa92a-0f64-460c-9a3e-89e34a13512b';
UPDATE questions SET noi_dung = 'Cặp số (x₀; y₀) là nghiệm của bất phương trình nếu khi thay vào, ta được một mệnh đề ___.', loi_giai = 'Liên hệ Chương I — A01: ''mệnh đề'' là câu khẳng định có tính đúng/sai xác định. Thay cặp số vào bất phương trình chứa biến → biến thành mệnh đề có chân lí xác định.' WHERE id = 'fc31c4ad-4fd1-47b0-8d2c-b9eb4de90abe';
UPDATE questions SET noi_dung = 'Bài làm: ''Vẽ bờ của bất phương trình x + 2y < 4. Tôi tìm giao điểm: cho x = 0 ⇒ x = 4 ⇒ điểm (4; 0). Cho y = 0 ⇒ 2y = 4 ⇒ y = 2 ⇒ điểm (0; 2). Rồi tôi vẽ đường thẳng NÉT LIỀN đi qua hai điểm đó.'' Tìm và sửa lỗi.', dap_an = 'HAI LỖI! LỖI 1 — NHẦM TRỤC: bạn ấy viết ''cho x = 0 ⇒ x = 4'' — VÔ LÍ! Đã cho x = 0 sao lại ra x = 4?! Đúng: cho y = 0 → x = 4 → (4;0) trên Ox · cho x = 0 → 2y = 4 ⇒ y = 2 → (0;2) trên Oy. May mắn: hai điểm VẪN ĐÚNG — nhưng LÍ LUẬN SAI (đúng nhờ MAY, không nhờ HIỂU)! LỖI 2 (NẶNG HƠN) — VẼ SAI NÉT: bất phương trình là x + 2y < 4, dấu < (KHÔNG gạch dưới!) ⇒ bờ KHÔNG THUỘC miền ⇒ PHẢI VẼ NÉT ĐỨT!' WHERE id = 'fce9ade9-291b-4dbf-b762-8ea8857637d5';
UPDATE questions SET distractors = '[{"phuong_an":"Elip dùng dấu cộng, hypebol dùng dấu trừ","quan_niem_sai":"Nhớ ngược hoàn toàn hai công thức"},{"phuong_an":"Cả hai đều dùng c² = a² + b², chỉ khác dấu trong phương trình","quan_niem_sai":"Sai: hai công thức thực sự khác nhau"},{"phuong_an":"Không có mẹo, phải học thuộc lòng","quan_niem_sai":"Tin rằng hai công thức là quy ước tuỳ ý; không thấy quan hệ hình học (c < a với elip, c > a với hypebol)"}]'::jsonb WHERE id = 'fcee1dc8-c73c-434d-af48-06c721157b99';
UPDATE questions SET noi_dung = 'Cho phương trình x²/(m-2) + y²/(m-5) = 1. Tìm m để biểu diễn một HYPEBOL.' WHERE id = 'fd004482-63ae-49fc-b42a-822cb5d6fd04';
UPDATE questions SET noi_dung = 'Tiếp tuyến của đường tròn tâm I tại tiếp điểm M₀ nhận vectơ nào làm vectơ pháp tuyến?', distractors = '[{"phuong_an":"Vectơ IM₀ nhưng làm vectơ chỉ phương","quan_niem_sai":"Nhầm vai trò: IM₀ VUÔNG GÓC tiếp tuyến nên là vectơ pháp tuyến"},{"phuong_an":"Vectơ OM₀ (từ gốc toạ độ)","quan_niem_sai":"Phải tính từ TÂM I, không phải từ gốc O"},{"phuong_an":"Vectơ bất kì vuông góc Ox","quan_niem_sai":"Không liên quan tới vị trí tâm và tiếp điểm"}]'::jsonb, loi_giai = 'Tiếp tuyến vuông góc với bán kính tại tiếp điểm ⇒ IM₀ là vectơ pháp tuyến của tiếp tuyến.' WHERE id = 'fdb7caae-7160-42c0-a687-9bde1336fb13';
UPDATE questions SET noi_dung = 'Câu ''Tổng số tiền mua KHÔNG QUÁ 200 nghìn đồng'' được dịch thành bất phương trình với dấu: A. > B. ≤ C. < D. ≥' WHERE id = 'fe5237ca-77ff-4f9b-a5da-789aa297230a';
UPDATE questions SET distractors = '[{"phuong_an":"Đúng","quan_niem_sai":"Bỏ sót điều kiện u ≠ 0 trong định nghĩa vectơ chỉ phương"},{"phuong_an":"Đúng, nếu đường thẳng đi qua gốc O","quan_niem_sai":"Nhầm điểm đi qua với vectơ chỉ phương"},{"phuong_an":"Đúng, vì mọi vectơ đều có giá","quan_niem_sai":"Hiểu sai khái niệm giá của vectơ-không"}]'::jsonb, loi_giai = 'Theo định nghĩa, vectơ chỉ phương phải là vectơ KHÁC vectơ-không, vì vectơ-không không xác định được phương.' WHERE id = 'fe62399c-5778-4b45-a9de-fb6b6a04f2a1';
UPDATE questions SET noi_dung = 'Trong bất phương trình ax + by ≤ c, điều kiện bắt buộc là: a và b KHÔNG ___ bằng 0.', loi_giai = 'Nếu a = b = 0 → bất phương trình thành 0 ≤ c, một hằng mệnh đề, không còn ẩn để giải.' WHERE id = 'feb29d0f-91f1-4f0a-b6fd-d5b374cf04d7';
UPDATE questions SET dap_an = 'THÔNG ĐIỆP CỐT LÕI là: MỘT BỘ SỐ LIỆU KHÔNG THỂ được MÔ TẢ ĐẦY ĐỦ chỉ bằng MỘT CON SỐ DUY NHẤT (như CHỈ TRUNG BÌNH, hoặc CHỈ ĐỘ LỆCH CHUẨN); ĐỂ HIỂU ''BỨC TRANH ĐẦY ĐỦ'' về DỮ LIỆU, CẦN kết HỢP CẢ HAI KHÍA CẠNH: ''XU THẾ TRUNG TÂM'' (dữ liệu TẬP TRUNG XUNG QUANH giá trị NÀO — TRUNG BÌNH, TRUNG VỊ, MỐT) và ''ĐỘ PHÂN TÁN'' (dữ liệu DAO ĐỘNG/PHÂN TÁN RỘNG hay HẸP so với XU THẾ TRUNG TÂM đó — R, khoảng tứ phân vị, PHƯƠNG SAI/ĐỘ LỆCH CHUẨN, hệ số biến thiên); HAI DỮ LIỆU có CÙNG TRUNG BÌNH VẪN có THỂ ''RẤT KHÁC NHAU'' về BẢN CHẤT nếu MỨC ĐỘ PHÂN TÁN KHÁC NHAU (một BỘ RẤT ỔN ĐỊNH, một BỘ RẤT DAO ĐỘNG); NGOÀI RA, VIỆC LỰA CHỌN THƯỚC ĐO PHÙ HỢP (TRUNG BÌNH hay TRUNG VỊ; R, khoảng tứ phân vị hay ĐỘ LỆCH CHUẨN) CẦN dựa vào ĐẶC ĐIỂM CỤ THỂ của dữ liệu (có NGOẠI LỆ hay KHÔNG, ĐỊNH TÍNH hay ĐỊNH LƯỢNG), KHÔNG CÓ MỘT ''CÔNG THỨC VẠN NĂNG'' áp DỤNG được cho MỌI TRƯỜNG HỢP — TƯ DUY THỐNG KÊ ĐÚNG ĐẮN là BIẾT KẾT HỢP NHIỀU GÓC NHÌN (nhiều thước ĐO) và HIỂU RÕ HẠN CHẾ của TỪNG thước ĐO, thay VÌ chỉ dựa VÀO MỘT CON SỐ ĐƠN LẺ để đưa RA KẾT LUẬN.' WHERE id = 'ff684f47-2794-4460-97bb-1c681315f6a4';
UPDATE questions SET noi_dung = 'Trong bài toán tối ưu, HÀM MỤC TIÊU F = ax + by là: A. Một ràng buộc của bài toán B. Đại lượng cần tìm giá trị lớn nhất/giá trị nhỏ nhất (lợi nhuận, chi phí…) C. Miền nghiệm của hệ D. Điều kiện x ≥ 0, y ≥ 0' WHERE id = 'ff78c42a-154e-48c1-a660-c9cb3074e450';
